les\":{\"type\":\"object\",\"description\":\"Each profile, keyed by DID.\",\"additionalProperties\":{\"$ref\":\"https://xynolog.org/protocol/Profile.json\"}}},\"required\":[\"profiles\"],\"additionalProperties\":false}},\"required\":[\"response\"]},\"BrowseAnnotationHistoryRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseAnnotationHistoryRequest.json\",\"type\":\"object\",\"description\":\"Request to browse the history of an annotation\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"}},\"required\":[\"resourceId\",\"annotationId\"]},\"BrowseAnnotationHistoryResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseAnnotationHistoryResult.json\",\"type\":\"object\",\"description\":\"Result of browsing annotation history\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/GetAnnotationHistoryResponse.json\"}},\"required\":[\"response\"]},\"BrowseAnnotationRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseAnnotationRequest.json\",\"type\":\"object\",\"description\":\"Request to browse a single annotation\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"}},\"required\":[\"resourceId\",\"annotationId\"]},\"BrowseAnnotationResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseAnnotationResult.json\",\"type\":\"object\",\"description\":\"Result of browsing a single annotation\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/GetAnnotationResponse.json\"}},\"required\":[\"response\"]},\"AnchorRect\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchorRect.json\",\"type\":\"object\",\"description\":\"Where a clicked annotation's element is on the viewer's screen: its rectangle in viewport pixels, as a DOM rectangle states it. A viewer's own geometry: it rides a viewer's local frames, and a frame another participant's screen receives carries none.\",\"properties\":{\"x\":{\"type\":\"number\",\"description\":\"The rectangle's horizontal origin.\"},\"y\":{\"type\":\"number\",\"description\":\"The rectangle's vertical origin.\"},\"width\":{\"type\":\"number\",\"description\":\"The rectangle's width.\"},\"height\":{\"type\":\"number\",\"description\":\"The rectangle's height.\"},\"top\":{\"type\":\"number\",\"description\":\"The rectangle's top edge.\"},\"right\":{\"type\":\"number\",\"description\":\"The rectangle's right edge.\"},\"bottom\":{\"type\":\"number\",\"description\":\"The rectangle's bottom edge.\"},\"left\":{\"type\":\"number\",\"description\":\"The rectangle's left edge.\"}},\"required\":[\"x\",\"y\",\"width\",\"height\",\"top\",\"right\",\"bottom\",\"left\"]},\"BrowseClickEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseClickEvent.json\",\"type\":\"object\",\"description\":\"An annotation was clicked \u2014 open it: the viewer selects its entry in the annotations panel and relays a focus signal to scroll to it. The annotation id is the whole address; it identifies exactly one annotation on exactly one resource, so no resource field is carried and none is needed to scope the event. Motivation is NOT on the wire either: the viewer derives it from the annotation the id names, so the wire states the fact once. A viewer that has not loaded that annotation finds nothing and does nothing. Emitted locally by every clickable annotation surface, and over the wire by a driver opening an annotation on another participant's screen.\",\"properties\":{\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"},\"anchorRect\":{\"$ref\":\"https://xynolog.org/protocol/AnchorRect.json\"}},\"required\":[\"annotationId\"]},\"BrowseDirectoryRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseDirectoryRequest.json\",\"type\":\"object\",\"description\":\"Request to browse a directory listing\",\"properties\":{\"path\":{\"type\":\"string\"},\"sort\":{\"type\":\"string\",\"enum\":[\"name\",\"mtime\",\"annotationCount\"]}},\"required\":[\"path\"]},\"BrowseDirectoryResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseDirectoryResult.json\",\"type\":\"object\",\"description\":\"Result of browsing a directory listing\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/BrowseDirectoryResultResponse.json\"}},\"required\":[\"response\"]},\"BrowseDirectoryResultResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseDirectoryResultResponse.json\",\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\"},\"entries\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/DirectoryEntry.json\"}}},\"required\":[\"path\",\"entries\"]},\"BrowseEntityTypeClickedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseEntityTypeClickedEvent.json\",\"type\":\"object\",\"description\":\"Emitted when an entity type is clicked in the browse panel\",\"properties\":{\"entityType\":{\"type\":\"string\"}},\"required\":[\"entityType\"]},\"BrowseEntityTypesRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseEntityTypesRequest.json\",\"type\":\"object\",\"description\":\"Request to browse available entity types\",\"properties\":{}},\"BrowseEntityTypesResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseEntityTypesResult.json\",\"type\":\"object\",\"description\":\"Result of browsing entity types\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/GetEntityTypesResponse.json\"}},\"required\":[\"response\"]},\"BrowseEventsRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseEventsRequest.json\",\"type\":\"object\",\"description\":\"Request to browse events for a resource\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"type\":{\"type\":\"string\"},\"userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\"},\"limit\":{\"type\":\"integer\"}},\"required\":[\"resourceId\"]},\"BrowseEventsResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseEventsResult.json\",\"type\":\"object\",\"description\":\"Result of browsing events for a resource\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/GetEventsResponse.json\"}},\"required\":[\"response\"]},\"BrowseExternalNavigateEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseExternalNavigateEvent.json\",\"type\":\"object\",\"description\":\"Emitted when navigation to an external URL is requested\",\"properties\":{\"url\":{\"type\":\"string\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"url\"]},\"BrowseFilesResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseFilesResponse.json\",\"type\":\"object\",\"required\":[\"path\",\"entries\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"The directory path that was listed, relative to project root\"},\"entries\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/DirectoryEntry.json\"}}},\"additionalProperties\":false},\"BrowseKbRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseKbRequest.json\",\"type\":\"object\",\"description\":\"Request for the knowledge base's description of itself\",\"properties\":{}},\"BrowseKbResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseKbResult.json\",\"type\":\"object\",\"description\":\"Result of browse:kb-requested\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/KbDescription.json\"}},\"required\":[\"response\"]},\"BrowseLinkClickedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseLinkClickedEvent.json\",\"type\":\"object\",\"description\":\"Emitted when a link is clicked in the browse panel\",\"properties\":{\"href\":{\"type\":\"string\"},\"label\":{\"type\":\"string\"}},\"required\":[\"href\"]},\"BrowsePanelOpenEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowsePanelOpenEvent.json\",\"type\":\"object\",\"description\":\"Emitted when a browse panel is opened\",\"properties\":{\"panel\":{\"type\":\"string\"},\"scrollToAnnotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"},\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\"}},\"required\":[\"panel\"]},\"BrowsePanelToggleEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowsePanelToggleEvent.json\",\"type\":\"object\",\"description\":\"Emitted when a browse panel is toggled\",\"properties\":{\"panel\":{\"type\":\"string\"}},\"required\":[\"panel\"]},\"BrowseResourceOpenEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseResourceOpenEvent.json\",\"type\":\"object\",\"description\":\"Domain intent to open a resource in the viewer: emitted locally by in-app link handlers and remotely by the launcher's tour verbs; the viewer translates it to host routing (nav:push), which never crosses the wire. Deliberately not named 'navigate' \u2014 that word and the nav:* prefix belong to the host-local framework layer.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"resourceId\"]},\"BrowseResourceViewedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseResourceViewedEvent.json\",\"type\":\"object\",\"description\":\"REPORT that a resource has loaded in a viewer \u2014 emitted on arrival by ANY means: a followed cue, an in-app link, the back button, a typed URL. Deliberately distinct from the imperative browse:resource-open: drive and report never share a channel, or the driver hears its own commands and one viewer's arrival steers another's page.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"resourceId\"]},\"BrowseResourceCloseEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseResourceCloseEvent.json\",\"type\":\"object\",\"description\":\"Emitted when a resource is closed in the browse panel\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"resourceId\"]},\"BrowseResourceReorderEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseResourceReorderEvent.json\",\"type\":\"object\",\"description\":\"Emitted when resources are reordered in the browse panel\",\"properties\":{\"oldIndex\":{\"type\":\"integer\"},\"newIndex\":{\"type\":\"integer\"}},\"required\":[\"oldIndex\",\"newIndex\"]},\"AnchoredText\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchoredText.json\",\"type\":\"object\",\"description\":\"Text paired with the geometry that indexes it \u2014 the minimum needed to turn a range of the text, two offsets counted in Unicode code points, into a selection, or a rectangle into a quote. Whole-resource: a producer iterates page by page, but every consumer wants one map.\",\"properties\":{\"text\":{\"type\":\"string\",\"description\":\"Reading-order text of the whole resource.\"},\"items\":{\"type\":\"array\",\"description\":\"Positioned runs indexing `text`, roughly one per word.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/PdfTextItem.json\"}}},\"required\":[\"text\",\"items\"]},\"JobId\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobId.json\",\"type\":\"string\",\"description\":\"A job's id. 1 to 128 of the letters `A`\u2013`Z` and `a`\u2013`z`, the digits, `_` and `-`. It is one segment of a URL and one name in a file system, and it is held to that wherever it enters: a gateway refuses a payload that carries anything else. How one is made is no part of the rule.\",\"pattern\":\"^[A-Za-z0-9_-]{1,128}$\"},\"PdfTextItem\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/PdfTextItem.json\",\"type\":\"object\",\"description\":\"One positioned text run. Coordinates are PDF points with the origin at the bottom-left of the page, Y increasing upward; the flip to canvas pixels happens in the browser.\",\"properties\":{\"start\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Offset into AnchoredText.text, in Unicode code points from its start, inclusive.\"},\"end\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Offset into AnchoredText.text, in Unicode code points from its start, exclusive.\"},\"page\":{\"type\":\"integer\",\"description\":\"1-indexed page number.\"},\"x\":{\"type\":\"number\"},\"y\":{\"type\":\"number\"},\"width\":{\"type\":\"number\"},\"height\":{\"type\":\"number\"}},\"required\":[\"start\",\"end\",\"page\",\"x\",\"y\",\"width\",\"height\"]},\"AnchoredTextAnswer\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchoredTextAnswer.json\",\"description\":\"What a reader gets when it asks for a resource's coordinate map: the map, a stored decline, or a named absence.\\n\\nDistinct from `ExtractionOutcome` on purpose. That type is what the STORE holds and what an extractor RETURNS \u2014 neither of which can ever be 'not yet'. This is the read answer, which can, so widening ExtractionOutcome itself would have put an impossible state into the store's own type.\\n\\nFlat, one discriminant: every member carries `kind`, rather than nesting an outcome inside a status envelope and giving the wire two `kind` fields at different depths.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/ExtractedText.json\"},{\"$ref\":\"https://xynolog.org/protocol/ExtractionDeclined.json\"},{\"$ref\":\"https://xynolog.org/protocol/AnchoredTextAbsent.json\"}],\"discriminator\":{\"propertyName\":\"kind\",\"mapping\":{\"extracted\":\"https://xynolog.org/protocol/ExtractedText.json\",\"declined\":\"https://xynolog.org/protocol/ExtractionDeclined.json\",\"not-yet\":\"https://xynolog.org/protocol/AnchoredTextAbsent.json\",\"no-map\":\"https://xynolog.org/protocol/AnchoredTextAbsent.json\",\"unknown\":\"https://xynolog.org/protocol/AnchoredTextAbsent.json\"}}},\"AnchoredTextAbsent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchoredTextAbsent.json\",\"type\":\"object\",\"description\":\"There is no coordinate map to serve, and WHY \u2014 the distinction a bare null could not carry.\\n\\nOne member covers all three absences because none carries a payload; `kind` alone is the fact. Retryability is legible from the name, deliberately: a caller must not need a lookup table to decide whether to come back.\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"not-yet\",\"no-map\",\"unknown\"],\"description\":\"Discriminant, sharing the `kind` field with the ExtractedText/ExtractionDeclined members so the whole answer is one flat union.\\n\\n`not-yet` \u2014 the resource's media type has text that is derived by reading its content, and the store holds no entry for this content: the Smelter has not read it yet, or the entry was lost (a loss the Smelter's reconcile pass re-derives). RETRY.\\n\\n`no-map` \u2014 the resource's media type has no derived text, so no entry exists and none will until the type is given a reader. Decided by the media type alone, and answered at once. TERMINAL.\\n\\n`unknown` \u2014 no content identity to look up: the resource is not in the view store, or its primary representation carries no checksum. TERMINAL.\"}},\"required\":[\"kind\"]},\"BrowseResourceRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseResourceRequest.json\",\"type\":\"object\",\"description\":\"Request to browse a single resource\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"resourceId\"]},\"BrowseResourceResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseResourceResult.json\",\"type\":\"object\",\"description\":\"A resource's descriptor, and the sequence number of the last of its events the descriptor reflects. Its annotations are not here: their number follows the document's, so they are read over HTTP (`GET /resources/{id}/annotations`).\",\"properties\":{\"response\":{\"type\":\"object\",\"properties\":{\"resource\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"},\"lastSequence\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The sequence number of the resource's last event. A graph read that follows a write waits for the graph projection to reach it.\"}},\"required\":[\"resource\",\"lastSequence\"],\"additionalProperties\":false}},\"required\":[\"response\"]},\"BrowseResourcesRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseResourcesRequest.json\",\"type\":\"object\",\"description\":\"Request to browse resources with optional filtering and pagination\",\"properties\":{\"archived\":{\"type\":\"boolean\"},\"entityType\":{\"type\":\"string\"},\"offset\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many of the resources the filters admit are passed over before the page begins.\"},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The most resources a page has.\"}}},\"BrowseResourcesResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseResourcesResult.json\",\"type\":\"object\",\"description\":\"Result of browsing resources\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/ListResourcesResponse.json\"}},\"required\":[\"response\"]},\"BrowseRouterPushEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseRouterPushEvent.json\",\"type\":\"object\",\"description\":\"Emitted when the browse panel requests a router navigation\",\"properties\":{\"path\":{\"type\":\"string\"},\"reason\":{\"type\":\"string\"}},\"required\":[\"path\"]},\"BrowseTagSchemasRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseTagSchemasRequest.json\",\"type\":\"object\",\"description\":\"Request to browse registered tag schemas\",\"properties\":{}},\"BrowseTagSchemasResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseTagSchemasResult.json\",\"type\":\"object\",\"description\":\"Result of browsing tag schemas\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/GetTagSchemasResponse.json\"}},\"required\":[\"response\"]},\"BusEmitAccepted\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BusEmitAccepted.json\",\"type\":\"object\",\"description\":\"Result of publishing one event. `subscribers` is the number of observers attached to the target subject at dispatch \u2014 the GLOBAL subject for an unscoped emit, the scoped one when `scope` is set. Zero means the signal reached nobody: /bus/subscribe enforces no channel allowlist and the emit handler publishes unconditionally, so a client can emit a channel no participant subscribes to and otherwise receive a clean 202 with no way to tell. Deliberately NOT named `delivered`: this is the count at dispatch, and a subscriber may still drop the frame downstream, so the field is named after what the server can actually observe.\",\"properties\":{\"subscribers\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Observers on the target subject when the event was dispatched. ABSENT means the gateway could not count: under a broker signal plane (the KnowledgeBase document's `spec.messaging.signal.type: nats`) the event is published to a fabric whose observers the gateway cannot see. The one zero a broker plane states is a registry operation's request with a `correlationId` that reached nobody, which the broker itself reports (no responders). Never defaulted: a zero here is the claim that nobody was listening, and a gateway that did not observe that never makes it.\"}}},\"BusEmitRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BusEmitRequest.json\",\"type\":\"object\",\"description\":\"One event for the bus. `channel` names a channel of the bus registry (specs/src/bus/registry.json) and `payload` must match the schema the registry's `validate` names for it. `scope` publishes a resource-bound broadcast to that resource's subscribers only; everything else is unscoped. `clientId` and `correlationId` are routing facts beside the payload, never inside it.\",\"properties\":{\"channel\":{\"type\":\"string\",\"description\":\"A channel of the bus registry.\",\"minLength\":1},\"payload\":{\"type\":\"object\",\"description\":\"The channel's payload, validated against the schema its registry entry names. `_userId` and `_roles` are the gateway's to write: whatever a caller puts there is replaced.\",\"additionalProperties\":true},\"scope\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource scope of a resource-bound broadcast. Publishers of those broadcasts only; a command or request never carries one.\"},\"clientId\":{\"type\":\"string\",\"description\":\"The address this request's reply is delivered to: the emit claims `correlationId` for this clientId and the verified principal. Required when `channel` is a registry operation's request and a correlationId is present; ignored otherwise. An empty string counts as absent.\"},\"correlationId\":{\"type\":\"string\",\"description\":\"Pairs a reply with its request. On a registry operation's request it claims the id: a second claim of a live id is refused with 409. Replies carry it back on the frame, never in the payload.\",\"minLength\":1}},\"required\":[\"channel\",\"payload\"]},\"BusSubscribeRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BusSubscribeRequest.json\",\"type\":\"object\",\"description\":\"Subscription matrix for the bus stream. `global` channels are delivered unscoped; each `scoped` entry subscribes the connection to one resource scope's channels, optionally resuming from that scope's last-seen persisted event id. At least one global channel or one scoped entry is required, and no scope may appear in two entries.\",\"properties\":{\"global\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1},\"description\":\"Unscoped channels to subscribe to.\"},\"pendingReplies\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1},\"maxItems\":256,\"description\":\"Correlation ids of requests this client still awaits a reply to. The gateway writes every reply it still retains for them (for `x-xynolog-limits.replyRetentionSeconds` after it was published) as an ordinary frame with its ReplyEventId, so a reply that also arrived live dedups client-side. A client can have no more pending than it may have unanswered requests, so this bound is also the number of unanswered requests `POST /bus/emit` allows a client.\"},\"scoped\":{\"type\":\"array\",\"description\":\"Per-resource-scope subscriptions, at most 512 on one connection. Scopes must be unique across entries.\",\"items\":{\"type\":\"object\",\"required\":[\"scope\",\"channels\"],\"additionalProperties\":false,\"properties\":{\"scope\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Resource scope (a resourceId).\"},\"channels\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1},\"description\":\"Channels to subscribe within this scope.\",\"minItems\":1},\"lastEventId\":{\"type\":\"string\",\"description\":\"This scope's last-seen PersistedEventId. The gateway replays this scope's persisted events after it \u2014 those on the entry's channels \u2014 before the live tail, and writes a scoped `bus:resume-gap` (BusResumeGap) when it cannot cover the gap.\"}}},\"maxItems\":512},\"clientId\":{\"type\":\"string\",\"description\":\"Routing address for correlated replies: a UUID minted once per bus-client lifetime \u2014 per actor, not per connection, so it survives a reconnect and two overlapping connections share it. A correlated reply is delivered to a connection only when its request was emitted under the same clientId by the same principal. Not authentication \u2014 the bearer token stays that \u2014 and never echoed into any payload or broadcast frame.\",\"minLength\":1}},\"additionalProperties\":false,\"required\":[\"clientId\"]},\"CloneResourceWithTokenResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/CloneResourceWithTokenResponse.json\",\"type\":\"object\",\"properties\":{\"token\":{\"type\":\"string\",\"description\":\"Generated clone token\"},\"expiresAt\":{\"type\":\"string\",\"description\":\"ISO 8601 timestamp when token expires\"},\"resource\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"}},\"required\":[\"token\",\"expiresAt\",\"resource\"]},\"EngineEntry\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/EngineEntry.json\",\"type\":\"object\",\"description\":\"One of the knowledge base's engines: a provider and a model its Inference document names, and the jobs the document has it used for. An engine is not a principal: whichever worker claims a job does it, under its own account, and names on each write the engine it used, if any. Carries no inference limits: the services that hold the inference credentials report those (InferenceLimitsResult).\",\"properties\":{\"engine\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"jobs\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/JobFilter.json\"},\"description\":\"The jobs the knowledge base's Inference document has this engine used for, as a claim names them. Absent for an engine only Librarian actors ask.\"}},\"required\":[\"engine\"],\"additionalProperties\":false},\"CommandError\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/CommandError.json\",\"type\":\"object\",\"description\":\"Error response for failed bus commands. Replaces native Error objects on the EventBus so payloads are serializable and OpenAPI-typed.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"peer-unavailable\",\"not-found\",\"unauthorized\",\"none-pending\"],\"description\":\"Machine-readable failure class, for consumers that must BRANCH on why a command failed rather than log it. Optional and deliberately sparse: absent means 'no class declared', and every existing failure stays that way. An enum rather than a free string so the vocabulary has an owner \u2014 an unconstrained code is a mirror with no gate, and adding one should be a deliberate spec change. `message` remains the human-readable text and is unaffected. Members: `peer-unavailable` \u2014 the channel this command was sent on has no subscriber, i.e. the service that answers it has not connected yet. Transient by nature (a peer still starting), which is what distinguishes it from a refusal: retrying is the correct response. `not-found` \u2014 the resource this command addressed does not exist in this knowledge base. A verdict, not a symptom: it is emitted only where the answer comes from the event store, which is the system of record, and never from a projection that may merely be lagging. Deterministic, so unlike `peer-unavailable` retrying is pointless \u2014 and consumers may act destructively on it (the SDK deletes a restored tab). Absence is not denial: a future 'exists, but not for you' must travel as its own code, never as this one. `unauthorized` \u2014 that code: the caller is authenticated but not permitted to do what it asked. A verdict about the CALLER, not the resource, so retrying under the same credential cannot succeed and a consumer must never spin on it; emitted by `job:claim` for a caller whose token carries no worker role. `none-pending` \u2014 a declined claim, not an error: the queue holds no pending job of the requested types. Nothing went wrong; the one code a consumer PARKS on, meaning 'nothing to do until a wake-up'. Emitted by `job:claim` only. A `job:claim` refusal carrying neither is unclassified \u2014 a malformed record or a missing injection \u2014 and a consumer treats it as 'log it, assume nothing'.\"},\"message\":{\"type\":\"string\",\"description\":\"Human-readable error message\"},\"details\":{\"type\":\"string\",\"description\":\"Optional additional context (stack trace, field name, etc.)\"}},\"required\":[\"message\"]},\"ContentFormat\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ContentFormat.json\",\"type\":\"string\",\"description\":\"Content format as a MIME type, optionally with parameters. The base type (everything before the first ';') MUST be a SupportedMediaType; parameters such as charset are preserved as metadata. Semantic validation happens in code at the create/yield boundary \u2014 there is deliberately no pattern here, the vocabulary lives in SupportedMediaType. Examples: text/plain, text/plain; charset=iso-8859-1, text/markdown; charset=windows-1252, image/png, application/pdf\",\"examples\":[\"text/plain; charset=utf-8\"]},\"ContextualSummaryResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ContextualSummaryResponse.json\",\"type\":\"object\",\"properties\":{\"summary\":{\"type\":\"string\"},\"relevantFields\":{\"type\":\"object\",\"description\":\"What the summary is of: the resource the annotation is on, and the annotation's entity types.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"resourceName\":{\"type\":\"string\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}},\"required\":[\"resourceId\",\"resourceName\",\"entityTypes\"],\"additionalProperties\":false},\"context\":{\"type\":\"object\",\"properties\":{\"before\":{\"type\":\"string\"},\"selected\":{\"type\":\"string\"},\"after\":{\"type\":\"string\"}},\"required\":[\"selected\"]}},\"required\":[\"summary\",\"relevantFields\",\"context\"]},\"CreateAnnotationRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/CreateAnnotationRequest.json\",\"type\":\"object\",\"properties\":{\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\"},\"target\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationTarget.json\"},\"body\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationBodies.json\",\"description\":\"Optional body. Omit for annotations whose motivation alone is meaningful (highlighting) or whose user-supplied content is empty. Shape matches Annotation.body.\"}},\"required\":[\"target\",\"motivation\"]},\"CreateResourceResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/CreateResourceResponse.json\",\"type\":\"object\",\"description\":\"The id of the resource an upload created. The Archivist answers it (200) once it has stored the bytes and recorded the resource, and the gateway forwards it (202), so the id is the one the record minted and its creation event is persisted. What remains asynchronous is downstream projection: graph, views and vectors settle afterwards.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The id of the newly created resource, as the record minted it.\"}},\"required\":[\"resourceId\"]},\"DirEntry\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/DirEntry.json\",\"type\":\"object\",\"required\":[\"type\",\"name\",\"path\",\"mtime\"],\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"dir\"]},\"name\":{\"type\":\"string\",\"description\":\"Entry name (basename)\"},\"path\":{\"type\":\"string\",\"description\":\"Path relative to project root\"},\"mtime\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"Last modified time (ISO 8601)\"}},\"additionalProperties\":false},\"DirectoryEntry\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/DirectoryEntry.json\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/FileEntry.json\"},{\"$ref\":\"https://xynolog.org/protocol/DirEntry.json\"}],\"discriminator\":{\"propertyName\":\"type\",\"mapping\":{\"file\":\"https://xynolog.org/protocol/FileEntry.json\",\"dir\":\"https://xynolog.org/protocol/DirEntry.json\"}},\"description\":\"One entry in a directory listing: a file, which may carry the resource it was ingested as, or a subdirectory. Tell them apart by `type`, which is required on both and single-valued.\"},\"DiscoveredKB\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/DiscoveredKB.json\",\"title\":\"DiscoveredKB\",\"type\":\"object\",\"description\":\"One knowledge base the Xynolog launcher manages on this machine, as published in the discovery document (see DiscoveryDocument). Endpoints and identity only \u2014 never credentials; login remains the consumer's per-KB business.\",\"properties\":{\"host\":{\"type\":\"string\",\"description\":\"Hostname the KB is reachable on from this machine (always \\\"localhost\\\" \u2014 local stacks bind locally and codespace KBs arrive through a local port forward)\"},\"port\":{\"type\":\"integer\",\"description\":\"Local TCP port of the KB's API (the gateway port for a local stack; the allocated forward port for a codespace stack)\"},\"placement\":{\"type\":\"string\",\"enum\":[\"local\",\"codespace\"],\"description\":\"Where the stack actually runs. \\\"local\\\": containers on this machine. \\\"codespace\\\": a GitHub-hosted VM whose KB is port-forwarded here.\"},\"repo\":{\"type\":\"string\",\"description\":\"owner/name GitHub slug \u2014 present for codespace placements, where the repo is the stack's identity\"},\"did\":{\"type\":\"string\",\"description\":\"The KB's did:web identifier, from its committed .xynolog/config.yaml \u2014 \\\"did:web:\\\" + its site.domain, verbatim. REQUIRED: a KB that declares no domain has no identity to publish, and the launcher refuses to start it rather than inventing or defaulting one. NOT unique within a document: a did names the knowledge base, not a running copy of it, so a local clone and a codespace of the same repo legitimately share one and both are published. host:port is the unique field (at most one entry per address), so consumers look up by ADDRESS and use the did to VERIFY that the copy they reached is the KB they meant \u2014 an address alone cannot say which KB is which, and an identity alone cannot say which copy.\"},\"siteName\":{\"type\":\"string\",\"description\":\"Human-readable site name from the KB's .xynolog/config.yaml (site.siteName), for display\"},\"managedBy\":{\"type\":\"string\",\"description\":\"The agent that owns this entry's lifecycle (the launcher writes \\\"xynolog-launcher\\\"). Consumers treat managed entries as authoritative for themselves \u2014 upsert on appearance, remove on disappearance \u2014 and never touch entries they did not write.\"}},\"required\":[\"host\",\"port\",\"placement\",\"did\",\"managedBy\"]},\"DiscoveryDocument\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/DiscoveryDocument.json\",\"title\":\"DiscoveryDocument\",\"type\":\"object\",\"description\":\"The launcher's KB discovery document \u2014 the schema authority for <stateDir>/discovery/kbs.json, which the Xynolog CLI (xynolog/cli) regenerates on every stack mutation and the Browser container mounts read-only at /discovery. NOT an API endpoint: a static document fetched same-origin by browsers (via the Browser's static server). An empty kbs list is meaningful (\\\"the launcher manages nothing right now\\\") and distinct from an absent file.\",\"properties\":{\"version\":{\"type\":\"integer\",\"enum\":[1],\"description\":\"Document schema version. Consumers MUST check it and ignore documents they do not understand.\"},\"kbs\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/DiscoveredKB.json\"},\"description\":\"Every KB the launcher currently manages, local and forwarded\"}},\"required\":[\"version\",\"kbs\"]},\"EnrichedResourceEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/EnrichedResourceEvent.json\",\"type\":\"object\",\"description\":\"Wire format for persisted events delivered over the bus SSE stream (GET /bus/subscribe). Extends StoredEventResponse with optional enrichment fields the EventStore populates from the materialized view at publish time (persistence \u2192 view \u2192 enrich \u2192 notification). Subscribers read the enrichment fields directly to update local caches without an additional fetch.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/StoredEventResponse.json\"},{\"type\":\"object\",\"properties\":{\"annotation\":{\"$ref\":\"https://xynolog.org/protocol/Annotation.json\",\"description\":\"Populated for events that mutate an annotation (mark:added, mark:body-updated, mark:removed). Carries the post-materialization annotation as it exists in the view, so subscribers can update local caches in-place without refetching. Absent for events that don't touch annotations.\"}}}]},\"EntityTagChangedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/EntityTagChangedPayload.json\",\"type\":\"object\",\"description\":\"Payload for mark:entity-tag-added and mark:entity-tag-removed domain events\",\"properties\":{\"entityType\":{\"type\":\"string\"}},\"required\":[\"entityType\"]},\"EntityTypeAddedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/EntityTypeAddedPayload.json\",\"type\":\"object\",\"description\":\"Payload for frame:entity-type-added domain event (system-level, no resourceId \u2014 fan-out is global)\",\"properties\":{\"entityType\":{\"type\":\"string\"}},\"required\":[\"entityType\"]},\"ErrorResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ErrorResponse.json\",\"type\":\"object\",\"description\":\"The body of every error the gateway answers, whatever the status and whatever the route \u2014 including a path it does not serve.\",\"properties\":{\"error\":{\"type\":\"string\",\"description\":\"What went wrong, in a sentence.\"},\"code\":{\"type\":\"string\",\"description\":\"A machine-readable class, when the route defines one.\"},\"hint\":{\"type\":\"string\",\"description\":\"What the caller can do about it, when there is something to say.\"},\"details\":{}},\"required\":[\"error\"]},\"EventMetadata\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/EventMetadata.json\",\"type\":\"object\",\"description\":\"Metadata added at persistence time. Part of every StoredEvent. Integrity is provided by git at the commit level (when gitSync is enabled), not by in-event metadata fields.\",\"properties\":{\"sequenceNumber\":{\"type\":\"integer\",\"description\":\"Monotonic position in the event log (ordering authority)\"}},\"required\":[\"sequenceNumber\"]},\"ExtractedText\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ExtractedText.json\",\"description\":\"A successful extraction: the anchored text plus its provenance. The 'extracted' member of ExtractionOutcome, the record the anchored-text store holds.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/AnchoredText.json\"},{\"type\":\"object\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"extracted\"],\"description\":\"Discriminant \u2014 both ExtractionOutcome members carry `kind`, single-valued: the category here, the detail in `method`.\"},\"method\":{\"$ref\":\"https://xynolog.org/protocol/ExtractionMethod.json\",\"description\":\"How the text was extracted.\"},\"pdfClass\":{\"$ref\":\"https://xynolog.org/protocol/PdfClass.json\",\"description\":\"PDF classification, when the source was a PDF.\"},\"ocrConfidence\":{\"$ref\":\"https://xynolog.org/protocol/OcrConfidence.json\",\"description\":\"How well the engine read the pixels, when any of this text came from OCR.\"},\"unreadPages\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"description\":\"1-indexed pages this extraction could not read \u2014 present only for partially covered documents (class C).\"}},\"required\":[\"kind\",\"method\"]}]},\"PdfClass\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/PdfClass.json\",\"type\":\"string\",\"enum\":[\"A\",\"B\",\"C\",\"D\",\"E\",\"F\",\"G\"],\"description\":\"The class a PDF is sorted into, which decides how its text is read. smelter/extraction-cases.json states what each class is.\"},\"ExtractionMethod\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ExtractionMethod.json\",\"type\":\"string\",\"enum\":[\"text-passthrough\",\"pdf-text-layer\",\"table\",\"form\",\"ocr\"],\"description\":\"How a text was extracted: a plain text taken as it is, a PDF's text layer read, a grid written as rows, a filled form's values read, or pixels read by OCR.\"},\"OcrConfidence\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/OcrConfidence.json\",\"type\":\"object\",\"description\":\"How well an OCR engine read the pixels.\",\"properties\":{\"mean\":{\"type\":\"number\",\"description\":\"Mean per-word confidence, 0-100.\"},\"lowConfidenceWords\":{\"type\":\"integer\",\"description\":\"Words the engine was unsure of.\"},\"totalWords\":{\"type\":\"integer\"}},\"required\":[\"mean\",\"lowConfidenceWords\",\"totalWords\"]},\"ExtractionDeclined\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ExtractionDeclined.json\",\"type\":\"object\",\"description\":\"A named decline: extraction ran and yielded nothing, by class. A first-class, cacheable outcome \u2014 'we ran and there was nothing' costs a full recognition pass to discover.\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"declined\"],\"description\":\"Discriminant \u2014 both ExtractionOutcome members carry `kind`, single-valued: the category here, the detail in `declined`.\"},\"declined\":{\"$ref\":\"https://xynolog.org/protocol/ExtractionDeclinedReason.json\",\"description\":\"Why extraction yielded nothing, by class.\"}},\"required\":[\"kind\",\"declined\"]},\"ExtractionDeclinedReason\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ExtractionDeclinedReason.json\",\"type\":\"string\",\"enum\":[\"no-text-layer\",\"encrypted\",\"corrupt\",\"too-large\"],\"description\":\"Why extraction yielded nothing, by class.\"},\"ExtractionOutcome\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ExtractionOutcome.json\",\"description\":\"The full outcome of text extraction for one representation \u2014 the record the anchored-text store holds and the wire serves. Discriminated on `kind`: 'extracted' \u2014 the anchored text with its provenance; 'declined' \u2014 a named decline. ocrConfidence is extraction quality for operators, deliberately not anchor confidence.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/ExtractedText.json\"},{\"$ref\":\"https://xynolog.org/protocol/ExtractionDeclined.json\"}],\"discriminator\":{\"propertyName\":\"kind\",\"mapping\":{\"extracted\":\"https://xynolog.org/protocol/ExtractedText.json\",\"declined\":\"https://xynolog.org/protocol/ExtractionDeclined.json\"}}},\"FileEntry\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/FileEntry.json\",\"type\":\"object\",\"required\":[\"type\",\"name\",\"path\",\"size\",\"mtime\",\"tracked\"],\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"file\"]},\"name\":{\"type\":\"string\",\"description\":\"Entry name (basename)\"},\"path\":{\"type\":\"string\",\"description\":\"Path relative to project root\"},\"size\":{\"type\":\"integer\",\"description\":\"File size in bytes\"},\"mtime\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"Last modified time (ISO 8601)\"},\"tracked\":{\"type\":\"boolean\",\"description\":\"True if this file is a tracked resource in the Knowledge Base\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Resource ID (only when tracked is true)\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity types assigned to this resource (only when tracked is true)\"},\"annotationCount\":{\"type\":\"integer\",\"description\":\"Number of annotations on this resource (only when tracked is true)\"},\"creator\":{\"type\":\"string\",\"description\":\"DID of the resource's creator \u2014 the first of its derived `wasAttributedTo`, the requester as the knowledge base recorded it (only when tracked is true)\"}},\"additionalProperties\":false},\"FragmentSelector\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/FragmentSelector.json\",\"type\":\"object\",\"description\":\"W3C Web Annotation FragmentSelector for media fragment identifiers (RFC 3778 for PDFs)\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"FragmentSelector\"]},\"value\":{\"type\":\"string\",\"description\":\"Media fragment identifier (e.g., 'page=1&viewrect=100,200,50,30' for PDF)\",\"examples\":[\"page=1&viewrect=100,200,50,30\"]},\"conformsTo\":{\"type\":\"string\",\"description\":\"URI identifying the fragment syntax specification\",\"examples\":[\"http://tools.ietf.org/rfc/rfc3778\"]}},\"required\":[\"type\",\"value\"]},\"FrameAddEntityTypeCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/FrameAddEntityTypeCommand.json\",\"type\":\"object\",\"description\":\"Bus command to add a new entity type to the KB's vocabulary. Carried on the `frame:add-entity-type` channel \u2014 Frame is the schema-layer flow that owns vocabulary writes.\",\"properties\":{\"tag\":{\"type\":\"string\"},\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"}},\"required\":[\"tag\"]},\"FrameAddTagSchemaCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/FrameAddTagSchemaCommand.json\",\"type\":\"object\",\"description\":\"Bus command to register a tag schema with the KB's runtime registry. Carried on the `frame:add-tag-schema` channel \u2014 Frame is the schema-layer flow that owns vocabulary writes. Most-recent registration of a given `schema.id` wins; the projection reflects the latest content. Identical re-registrations are silent; differing content overwrites and logs a warning.\",\"properties\":{\"schema\":{\"$ref\":\"https://xynolog.org/protocol/TagSchema.json\"},\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"}},\"required\":[\"schema\"]},\"GatherAnnotationComplete\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherAnnotationComplete.json\",\"type\":\"object\",\"description\":\"Completion payload emitted on the gather:annotation-complete bus channel when annotation context gathering finishes.\",\"properties\":{\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Branded AnnotationId of the annotation whose context was gathered\"},\"response\":{\"$ref\":\"https://xynolog.org/protocol/GatheredContext.json\",\"description\":\"The gathered annotation context (unified GatheredContext, focus.kind:'annotation')\"}},\"required\":[\"annotationId\",\"response\"]},\"GatherAnnotationOptions\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherAnnotationOptions.json\",\"type\":\"object\",\"description\":\"Optional configuration for an annotation-focus gather, which windows text around a mark. Distinct from the resource-focus options (depth / maxResources / includeContent / includeSummary), which traverse the resource graph.\",\"properties\":{\"includeSourceContext\":{\"type\":\"boolean\",\"description\":\"Whether to include source context in the gathered result\"},\"includeTargetContext\":{\"type\":\"boolean\",\"description\":\"Whether to include target context in the gathered result\"},\"contextWindow\":{\"type\":\"integer\",\"minimum\":100,\"maximum\":5000,\"description\":\"How much of the text on each side of the annotation to include, counted in Unicode code points\"}}},\"GatherAnnotationRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherAnnotationRequest.json\",\"type\":\"object\",\"description\":\"Request payload sent on the gather:requested bus channel to gather context for an annotation.\",\"properties\":{\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Branded AnnotationId of the annotation to gather context for\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Branded ResourceId of the resource the annotation belongs to\"},\"options\":{\"$ref\":\"https://xynolog.org/protocol/GatherAnnotationOptions.json\"}},\"required\":[\"annotationId\",\"resourceId\"]},\"GatherResourceComplete\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherResourceComplete.json\",\"type\":\"object\",\"description\":\"Completion payload emitted on the gather:resource-complete bus channel when resource context gathering finishes.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Branded ResourceId of the resource whose context was gathered\"},\"response\":{\"$ref\":\"https://xynolog.org/protocol/GatheredContext.json\",\"description\":\"The gathered resource context (unified GatheredContext, focus.kind:'resource')\"}},\"required\":[\"resourceId\",\"response\"]},\"GatherResourceRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherResourceRequest.json\",\"type\":\"object\",\"description\":\"Request payload sent on the gather:resource-requested bus channel to gather context for a resource.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Branded ResourceId of the resource to gather context for\"},\"options\":{\"$ref\":\"https://xynolog.org/protocol/GatherResourceRequestOptions.json\"}},\"required\":[\"resourceId\",\"options\"]},\"GatherResourceRequestOptions\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherResourceRequestOptions.json\",\"type\":\"object\",\"properties\":{\"depth\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":3,\"description\":\"How many links out from the resource the knowledge graph reaches, nearest first: 1 is what the resource links to and what cites it, and each further link out adds what those link to and what cites them\"},\"maxResources\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":200,\"description\":\"Maximum number of related resources to include\"},\"includeContent\":{\"type\":\"boolean\",\"description\":\"Whether to include resource content in the gathered result\"},\"includeSummary\":{\"type\":\"boolean\",\"description\":\"Whether to include resource summaries in the gathered result\"},\"excludeEntityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity types to exclude from the semantic recall built into this context (caller-supplied; e.g. a chat consumer passes ['Question'] so prior questions never ground answer generation). Optional; default none.\"}},\"required\":[\"depth\",\"maxResources\",\"includeContent\",\"includeSummary\"],\"description\":\"Gathering configuration\"},\"GatherSummaryRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherSummaryRequest.json\",\"type\":\"object\",\"description\":\"Request to generate an AI summary of an annotation\",\"properties\":{\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"annotationId\",\"resourceId\"]},\"GatherReferencedByRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherReferencedByRequest.json\",\"type\":\"object\",\"description\":\"Request for the annotations elsewhere that refer to a resource. The Librarian answers from the graph.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\",\"description\":\"The one motivation the annotations answered have. Every annotation that refers to the resource is answered where none is stated.\"}},\"required\":[\"resourceId\"]},\"GatherReferencedByResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherReferencedByResult.json\",\"type\":\"object\",\"description\":\"The annotations elsewhere that refer to a resource\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/GetReferencedByResponse.json\"}},\"required\":[\"response\"]},\"DurabilityEvidence\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/DurabilityEvidence.json\",\"type\":\"string\",\"enum\":[\"acknowledged\",\"probe-confirmed\",\"probe-refused\",\"probe-unreachable\"],\"description\":\"How a job's annotations were established as durable \u2014 the OBSERVATION, never a conclusion drawn from it. 'acknowledged': the event log confirmed the batch (mark:commit-ok). 'probe-confirmed': the acknowledgement was lost and a later read found the batch's last annotation present \u2014 true, but a weaker claim than an ack, since it rests on the log appending a batch in order and stopping at the first failure. 'probe-refused': the read returned a failure reply; note this does NOT assert the annotations are absent, because a read that failed for its own reasons answers on the same channel. 'probe-unreachable': no answer came at all, so nothing was established either way. ABSENT means the question never arose \u2014 a job that committed no annotations. Never defaulted: a manufactured value here is a claim nobody made, in a log nobody can rewrite.\"},\"FailureClass\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/FailureClass.json\",\"type\":\"string\",\"enum\":[\"transient\",\"deterministic\",\"withheld\"],\"description\":\"The class of a job's failure, stated by the worker, where the failure is still typed: at the gateway it is already text, and classing a failure by its text is what this exists to avoid. A job no worker concluded, because its worker stopped reporting, is classed by the dispatcher, as 'transient'. Each value is a claim. 'transient': nothing about the request was judged (the worker's own bound ran out, the provider said not now), so another attempt may succeed. 'deterministic': the same request cannot succeed on a second attempt. 'withheld': the model's provider had the request and withheld its answer, by a refusal or a content filter, and the same request is withheld again; nothing broke. A 'deterministic' or a 'withheld' failure is not retried, whatever retry budget is left. ABSENT means the failure was not classified, which is not the claim 'transient' makes; it is retried as a transient one is. Only a failure known to be deterministic or withheld is called so: calling a transient failure either one halves reliability, where the reverse costs one wasted attempt.\"},\"GatheredContext\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatheredContext.json\",\"type\":\"object\",\"description\":\"Context gathered for a gather.* call \u2014 consumed by yield.* (generation) and the matcher. A shared base (graph, semanticContext, metadata, inferredRelationshipSummary) plus a discriminated `focus` that names the anchor: an annotation or a whole resource.\",\"properties\":{\"focus\":{\"description\":\"The gather anchor. Discriminated on `kind`.\",\"oneOf\":[{\"type\":\"object\",\"description\":\"Annotation-anchored focus.\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"annotation\"]},\"annotation\":{\"$ref\":\"https://xynolog.org/protocol/Annotation.json\",\"description\":\"The annotation this context was gathered for\"},\"sourceResource\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\",\"description\":\"The resource containing the annotation\"},\"selected\":{\"type\":\"object\",\"description\":\"Text context around the annotation target\",\"properties\":{\"before\":{\"type\":\"string\",\"description\":\"Text appearing before the selected passage\"},\"text\":{\"type\":\"string\",\"description\":\"The selected text passage (the annotation target)\"},\"after\":{\"type\":\"string\",\"description\":\"Text appearing after the selected passage\"}},\"required\":[\"text\"]},\"userHint\":{\"type\":\"string\",\"description\":\"User-provided hint to supplement or replace the selected text for search and generation\"},\"targetResource\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\",\"description\":\"The resource the annotation links to, if it is a resolved reference. Dormant capability \u2014 produced/exposed but not yet consumed.\"},\"targetContext\":{\"type\":\"object\",\"description\":\"Context about the annotation's link target. Dormant \u2014 produced/exposed but not yet consumed.\",\"properties\":{\"content\":{\"type\":\"string\"},\"summary\":{\"type\":\"string\"}},\"required\":[\"content\"]}},\"required\":[\"kind\",\"annotation\",\"sourceResource\"]},{\"type\":\"object\",\"description\":\"Whole-resource focus.\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"resource\"]},\"resource\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\",\"description\":\"The resource this context was gathered for\"},\"summary\":{\"type\":\"string\"},\"suggestedReferences\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"content\":{\"type\":\"object\",\"description\":\"Resource content (included when requested)\",\"properties\":{\"main\":{\"type\":\"string\",\"description\":\"Content of the focal resource\"},\"related\":{\"type\":\"object\",\"additionalProperties\":{\"type\":\"string\"},\"description\":\"Map of related resource IDs to their content\"}}}},\"required\":[\"kind\",\"resource\"]}]},\"graph\":{\"$ref\":\"https://xynolog.org/protocol/KnowledgeGraph.json\",\"description\":\"Knowledge graph backbone \u2014 resources AND annotations as typed nodes. The flattened views (connections, citedBy, siblings) are derived from this.\"},\"semanticContext\":{\"type\":\"object\",\"description\":\"Semantically similar passages from across the knowledge base, found via vector search\",\"properties\":{\"similar\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/SemanticMatch.json\"},\"description\":\"Passages ranked by cosine similarity to the focal text\"},\"excludedEntityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity types excluded from this recall \u2014 a record of how `similar` was filtered (e.g. ['Question'] so answer-generation never surfaces prior questions). Absent when no exclusion was applied.\"}},\"required\":[\"similar\"]},\"metadata\":{\"type\":\"object\",\"description\":\"Context metadata about the focal anchor and its source\",\"properties\":{\"resourceType\":{\"type\":\"string\",\"description\":\"Type of source resource (e.g., 'document', 'image', 'video')\"},\"language\":{\"type\":\"string\",\"description\":\"BCP 47 language tag of source content\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity types associated with the focal anchor\"},\"entityTypeFrequencies\":{\"type\":\"object\",\"description\":\"Global frequency counts for entity types (for IDF-like weighting). A KB-wide statistic, not a neighborhood property \u2014 kept here rather than on the graph.\",\"additionalProperties\":{\"type\":\"integer\"}}}},\"inferredRelationshipSummary\":{\"type\":\"string\",\"description\":\"LLM-generated summary of the focal anchor's relationships in the knowledge graph\"}},\"required\":[\"focus\",\"graph\",\"metadata\"]},\"GenerationJobParams\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GenerationJobParams.json\",\"description\":\"The parameters of a `yield` job: what it is asked to make (GenerationJobRequest) and the gathered context it is made from. The job's resource is derived from `context.focus` by the dispatcher (resource focus \u2192 focus.resource; annotation focus \u2192 focus.sourceResource, with the worker binding to focus.annotation), and the dispatcher refuses a parameter this schema does not name.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/GenerationJobRequest.json\"},{\"type\":\"object\",\"properties\":{\"context\":{\"$ref\":\"https://xynolog.org/protocol/GatheredContext.json\",\"description\":\"The gathered context that grounds the generation. Its `focus` names the anchor: the DISPATCHER derives the job's resourceId from it (resource focus \u2192 focus.resource; annotation focus \u2192 focus.sourceResource, with the worker auto-binding to focus.annotation) and REJECTS a caller-supplied id \u2014 the context is authoritative. Under `cite`, the ids its embedding carries are the only valid citation targets.\"}},\"required\":[\"context\"]}]},\"GetAnnotationHistoryResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetAnnotationHistoryResponse.json\",\"type\":\"object\",\"properties\":{\"events\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/AttributedEvent.json\"}},\"total\":{\"type\":\"number\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"events\",\"total\",\"annotationId\",\"resourceId\"]},\"GetAnnotationResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetAnnotationResponse.json\",\"type\":\"object\",\"properties\":{\"annotation\":{\"$ref\":\"https://xynolog.org/protocol/Annotation.json\"},\"resource\":{\"anyOf\":[{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"},{\"type\":\"null\"}]},\"resolvedResource\":{\"anyOf\":[{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"},{\"type\":\"null\"}]}},\"required\":[\"annotation\",\"resource\",\"resolvedResource\"]},\"GetAnnotationsResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetAnnotationsResponse.json\",\"type\":\"object\",\"properties\":{\"annotations\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/Annotation.json\"}},\"total\":{\"type\":\"number\",\"description\":\"Total number of annotations\"},\"motivation\":{\"anyOf\":[{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\"},{\"type\":\"null\"}],\"description\":\"Motivation filter applied (if any)\"}},\"required\":[\"annotations\",\"total\"]},\"GetEntityTypesResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetEntityTypesResponse.json\",\"type\":\"object\",\"properties\":{\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}},\"required\":[\"entityTypes\"]},\"GetEventsResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetEventsResponse.json\",\"type\":\"object\",\"properties\":{\"events\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/AttributedEvent.json\"}},\"total\":{\"type\":\"number\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"events\",\"total\",\"resourceId\"]},\"GetReferencedByResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetReferencedByResponse.json\",\"type\":\"object\",\"properties\":{\"referencedBy\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/GetReferencedByResponseReferencedByItem.json\"}}},\"required\":[\"referencedBy\"]},\"GetReferencedByResponseReferencedByItem\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetReferencedByResponseReferencedByItem.json\",\"type\":\"object\",\"properties\":{\"id\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Reference annotation ID\"},\"resourceName\":{\"type\":\"string\",\"minLength\":1,\"description\":\"Name of the resource containing the reference. Absent where no description of that resource is held, and where its name is empty.\"},\"target\":{\"type\":\"object\",\"properties\":{\"source\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"ID of resource containing the reference\"},\"selector\":{\"type\":\"object\",\"properties\":{\"exact\":{\"type\":\"string\",\"description\":\"The selected text that references this resource\"}},\"required\":[\"exact\"]}},\"required\":[\"source\",\"selector\"]}},\"required\":[\"id\",\"target\"]},\"GetResourceByTokenResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetResourceByTokenResponse.json\",\"type\":\"object\",\"properties\":{\"sourceResource\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"},\"expiresAt\":{\"type\":\"string\",\"description\":\"ISO 8601 timestamp when token expires\"}},\"required\":[\"sourceResource\",\"expiresAt\"]},\"GetResourceResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetResourceResponse.json\",\"type\":\"object\",\"properties\":{\"resource\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"},\"annotations\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/Annotation.json\"},\"description\":\"All annotations for the resource (highlights, references, assessments, etc.)\"}},\"required\":[\"resource\",\"annotations\"]},\"GetTagSchemasResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GetTagSchemasResponse.json\",\"type\":\"object\",\"properties\":{\"tagSchemas\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/TagSchema.json\"}}},\"required\":[\"tagSchemas\"]},\"HealthResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/HealthResponse.json\",\"type\":\"object\",\"properties\":{\"status\":{\"type\":\"string\"},\"message\":{\"type\":\"string\"},\"version\":{\"type\":\"string\"},\"timestamp\":{\"type\":\"string\"}},\"required\":[\"status\",\"message\",\"version\",\"timestamp\"],\"description\":\"Liveness: the process is up and serving. It asks nothing of the Archivist or the broker \u2014 a gateway that cannot reach them refuses to start, so one that answers here got past both at boot.\"},\"InferenceLimits\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/InferenceLimits.json\",\"type\":\"object\",\"description\":\"A provider's actual ceilings for a model, discovered from the provider itself (Anthropic Models API; Ollama /api/show) \u2014 never hand-maintained constants. Semantics differ by provider shape: Anthropic reports maximum input tokens in contextTokens with a separate output ceiling in maxOutputTokens; Ollama reports the shared input+output window and mirrors it into both fields (there is no separate output ceiling), so maxOutputTokens === contextTokens signals a shared window.\",\"properties\":{\"contextTokens\":{\"type\":\"number\",\"description\":\"The context window in tokens. Anthropic: maximum input tokens (output has its own ceiling). Ollama: the shared input+output window.\"},\"maxOutputTokens\":{\"type\":\"number\",\"description\":\"Maximum output tokens per generation. Equal to contextTokens when the provider has a single shared window.\"},\"acceptsTemperature\":{\"type\":\"boolean\",\"description\":\"Whether this engine accepts a caller-supplied sampling temperature, measured against the provider (Anthropic: an active probe at discovery, because some models reject the parameter outright and the Models API does not say; Ollama: always true). Consumers treat only an explicit false as 'hide temperature controls' \u2014 absence means no claim.\"}},\"required\":[\"contextTokens\",\"maxOutputTokens\"]},\"InferenceLimitsRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/InferenceLimitsRequest.json\",\"type\":\"object\",\"description\":\"Request for the inference limits of the engines one service holds a client for. Answered on job:limits-requested by the worker, and on gather:limits-requested and match:limits-requested by the librarian: each service that holds an inference credential reports for its own engines, so no other service needs one.\",\"properties\":{}},\"InferenceLimitsResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/InferenceLimitsResult.json\",\"type\":\"object\",\"description\":\"The inference limits one service discovered for the engines it holds a client for. An engine whose discovery is currently unavailable is absent.\",\"properties\":{\"response\":{\"type\":\"object\",\"properties\":{\"limits\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/EngineLimits.json\"}}},\"required\":[\"limits\"]}},\"required\":[\"response\"]},\"EngineLimits\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/EngineLimits.json\",\"type\":\"object\",\"description\":\"The discovered limits of one engine.\",\"properties\":{\"engine\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"limits\":{\"$ref\":\"https://xynolog.org/protocol/InferenceLimits.json\"}},\"required\":[\"engine\",\"limits\"],\"additionalProperties\":false},\"GraphAnnotationNode\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GraphAnnotationNode.json\",\"type\":\"object\",\"description\":\"An annotation's graph presence. The node IS the annotation, so the full W3C object is required \u2014 selectors and body included, which is what lets a client place context annotations without a second fetch. Citations ride here too: an inbound reference is its linking annotation, anchored by an `annotation-of` edge to the resource it lives on and a `cites` edge to the focal resource.\",\"properties\":{\"id\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"The AnnotationId \u2014 the same value as annotation.id\"},\"type\":{\"type\":\"string\",\"enum\":[\"annotation\"]},\"label\":{\"type\":\"string\",\"description\":\"The annotation's motivation, as a display label\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity types carried by the annotation\"},\"annotation\":{\"$ref\":\"https://xynolog.org/protocol/Annotation.json\"},\"metadata\":{\"type\":\"object\",\"additionalProperties\":{}}},\"required\":[\"id\",\"type\",\"label\",\"annotation\"]},\"GraphResourceNode\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GraphResourceNode.json\",\"type\":\"object\",\"description\":\"A resource's presence in the gathered knowledge graph.\",\"properties\":{\"id\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource's ResourceId\"},\"type\":{\"type\":\"string\",\"enum\":[\"resource\"]},\"label\":{\"type\":\"string\",\"description\":\"The resource's display name \u2014 its raw id when the resource's view was missing at build time\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity types on the resource\"},\"metadata\":{\"type\":\"object\",\"additionalProperties\":{}}},\"required\":[\"id\",\"type\",\"label\"]},\"JobCancelRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCancelRequest.json\",\"type\":\"object\",\"description\":\"Request to cancel one job, named by its id. A pending job is cancelled immediately by the dispatcher. A running job is cancelled only by the worker that holds it: the worker stops its work and settles the job with `job:cancel` (JobCancelCommand). The queue is never made to yank a running job out from under a live worker.\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"}},\"required\":[\"jobId\"]},\"JobCancelCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCancelCommand.json\",\"type\":\"object\",\"description\":\"A worker's settling of a running job it holds whose work it has stopped for a cancellation \u2014 the queue moves the job to cancelled/. Distinct from JobCancelRequest (the client\u2192worker REQUEST to stop): this is the worker announcing it did, so the running job is never yanked to cancelled/ out from under a live worker (the roach-motel race).\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Annotation this job is attached to, when applicable. Lets the UI route cancellation feedback to a specific annotation.\"},\"completedUnits\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The units the worker had finished when it stopped. Recorded on the cancelled job's metadata so the work already done stays visible.\"},\"unitCursors\":{\"type\":\"object\",\"additionalProperties\":{\"$ref\":\"https://xynolog.org/protocol/UnitCursor.json\"},\"description\":\"The furthest each unit begun got, keyed by unit, with what it had counted there \u2014 the grain `completedUnits` cannot express. A unit named in `completedUnits` is stated here too, by the cursor it ended at: a later attempt skips it whole and counts it by that cursor. A cursor never says a unit is finished; only `completedUnits` does. Merged monotonically per unit, finished or not: a stale snapshot must never move a cursor backward.\"}},\"required\":[\"resourceId\",\"jobId\",\"jobType\"]},\"JobClaimCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobClaimCommand.json\",\"type\":\"object\",\"description\":\"Claim the NEXT pending job that matches one of `accepts` (atomic: pending \u2192 running). A job:queued announcement is a WAKE-UP, not a reservation: the claimed job may differ from the announced one, and two claims after one announcement both succeed on different jobs instead of racing for one. job:claimed carries the claimed job; job:claim-failed reports that nothing matching is pending.\",\"properties\":{\"accepts\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/JobFilter.json\"},\"minItems\":1,\"description\":\"The jobs this claim takes. A job is handed over when it matches any one of them.\"},\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated claimant's DID, injected by the /bus/emit gateway. Clients do not set this. The dispatcher records it as the holder on job:assigned.\"},\"_roles\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The claimant's capabilities (the token's `roles`), injected by the /bus/emit gateway. Clients do not set this. The dispatcher authorizes the claim by capability \u2014 it admits the claim only when this carries the worker role \u2014 so a claimant that is not a worker for this knowledge base is refused before the queue is consulted.\"}},\"required\":[\"accepts\"]},\"JobCompleteCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCompleteCommand.json\",\"description\":\"A job's worker says the job is complete. The result it carries is its verb's: a `mark` job's counts or the resource a `yield` job made, or a decline from either. A completion whose result is the other verb's is refused where the command is admitted.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/MarkJobCompleteCommand.json\"},{\"$ref\":\"https://xynolog.org/protocol/YieldJobCompleteCommand.json\"}],\"discriminator\":{\"propertyName\":\"jobType\",\"mapping\":{\"mark\":\"https://xynolog.org/protocol/MarkJobCompleteCommand.json\",\"yield\":\"https://xynolog.org/protocol/YieldJobCompleteCommand.json\"}}},\"JobCompletedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCompletedPayload.json\",\"type\":\"object\",\"description\":\"Payload for job:completed domain event\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"attempt\":{\"type\":\"integer\",\"description\":\"Which attempt produced this event, 1-based (a first run is 1). ALWAYS present: the queue re-runs a failed job silently, so an operator reading progress or a terminal record has no other way to tell a re-run from a first run \u2014 and provider spend, already counted in xynolog_inference_tokens_total, cannot be attributed to a repeated document without it. Stated rather than inferred from absence, because 'attempt 1' is a fact the emitter always knows.\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Annotation this job was attached to, when applicable\"},\"totalSteps\":{\"type\":\"integer\"},\"foundCount\":{\"type\":\"integer\",\"description\":\"For detection: total entities found\"},\"resultResourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"For generation: ID of generated resource\"},\"annotationUri\":{\"type\":\"string\",\"description\":\"For generation: URI of annotation that triggered generation\"},\"result\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"Full result object for extensibility\"},\"durability\":{\"$ref\":\"https://xynolog.org/protocol/DurabilityEvidence.json\"}},\"required\":[\"jobId\",\"jobType\"]},\"JobCreateCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCreateCommand.json\",\"description\":\"Create a job. A job description is its `jobType` and enough parameters to be well formed: a `mark` job names its resource and, in its parameters, its motivation; a `yield` job names its context.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/MarkJobCreateCommand.json\"},{\"$ref\":\"https://xynolog.org/protocol/YieldJobCreateCommand.json\"}],\"discriminator\":{\"propertyName\":\"jobType\",\"mapping\":{\"mark\":\"https://xynolog.org/protocol/MarkJobCreateCommand.json\",\"yield\":\"https://xynolog.org/protocol/YieldJobCreateCommand.json\"}}},\"JobCreatedResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCreatedResult.json\",\"type\":\"object\",\"description\":\"Result of a job:create command\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/JobCreatedResultResponse.json\"}},\"required\":[\"response\"]},\"JobCreatedResultResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCreatedResultResponse.json\",\"type\":\"object\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"}},\"required\":[\"jobId\"]},\"JobFailCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobFailCommand.json\",\"type\":\"object\",\"description\":\"Command to mark a job as failed\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"attempt\":{\"type\":\"integer\",\"description\":\"Which attempt produced this event, 1-based (a first run is 1). ALWAYS present: the queue re-runs a failed job silently, so an operator reading progress or a terminal record has no other way to tell a re-run from a first run \u2014 and provider spend, already counted in xynolog_inference_tokens_total, cannot be attributed to a repeated document without it. Stated rather than inferred from absence, because 'attempt 1' is a fact the emitter always knows.\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Annotation this job is attached to, when applicable. Lets the UI route failure feedback (error toast, revert state) to a specific annotation.\"},\"error\":{\"type\":\"string\"},\"completedUnits\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity-type units whose annotations were fully emitted before this failure (checkpointed resume). The queue records them on the retried job's metadata; a retried claim skips them so completed work is neither redone nor duplicated.\"},\"unitCursors\":{\"type\":\"object\",\"additionalProperties\":{\"$ref\":\"https://xynolog.org/protocol/UnitCursor.json\"},\"description\":\"The furthest each unit begun got, keyed by unit, with what it had counted there \u2014 the grain `completedUnits` cannot express. A unit named in `completedUnits` is stated here too, by the cursor it ended at: a later attempt skips it whole and counts it by that cursor. A cursor never says a unit is finished; only `completedUnits` does. Merged monotonically per unit, finished or not: a stale snapshot must never move a cursor backward.\"},\"failureClass\":{\"$ref\":\"https://xynolog.org/protocol/FailureClass.json\"},\"willRetry\":{\"type\":\"boolean\",\"description\":\"Whether the queue will re-queue this job for another attempt. Computed by the worker from the SAME rule the queue applies when it takes the failure (specs/src/jobs/retry-cases.json, which every SDK and the dispatcher run) using the retry budget carried on the claimed record. FALSE (or absent) means this failure is TERMINAL: a client's job-watch stream ends here. TRUE means the work continues on a fresh attempt \u2014 the failure is an event, not the end, and a stream that terminated on it would report a recovering run as a failed one.\"},\"durability\":{\"$ref\":\"https://xynolog.org/protocol/DurabilityEvidence.json\"}},\"required\":[\"resourceId\",\"jobId\",\"jobType\",\"error\"]},\"JobCheckpointCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCheckpointCommand.json\",\"type\":\"object\",\"description\":\"Command to persist a running job's completed-unit checkpoint AT unit completion. Distinct from JobFailCommand's checkpoint, which lands only on a clean failure: a worker that dies (crash/OOM/kill) never emits job:fail, so this durable, unthrottled write is what lets the janitor's stale-running recovery resume a dead worker's job rather than redo its finished units.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"completedUnits\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity-type units whose annotations have been fully emitted so far. Unioned into the running job's metadata checkpoint; a retry after recovery skips them.\"},\"unitCursors\":{\"type\":\"object\",\"additionalProperties\":{\"$ref\":\"https://xynolog.org/protocol/UnitCursor.json\"},\"description\":\"The furthest each unit begun got, keyed by unit, with what it had counted there \u2014 the grain `completedUnits` cannot express. A unit named in `completedUnits` is stated here too, by the cursor it ended at: a later attempt skips it whole and counts it by that cursor. A cursor never says a unit is finished; only `completedUnits` does. Merged monotonically per unit, finished or not: a stale snapshot must never move a cursor backward.\"}},\"required\":[\"jobId\",\"completedUnits\"]},\"ResourceId\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceId.json\",\"type\":\"string\",\"description\":\"A resource's id: a name, never the resource's URI or a path. 1 to 128 of the letters `A`\u2013`Z` and `a`\u2013`z`, the digits, `_` and `-`. It is one segment of a URL and one name in a file system, and it is held to that wherever it enters: a gateway refuses a payload that carries anything else. How one is made is no part of the rule. `__system__` is the one that names no resource: the scope events about the knowledge base itself are logged under.\",\"pattern\":\"^[A-Za-z0-9_-]{1,128}$\"},\"UnitCursor\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/UnitCursor.json\",\"type\":\"object\",\"description\":\"The furthest a single unit got, and what it had counted when it got there. A unit left partway is resumed from its cursor rather than redone. A finished unit keeps its cursor: `next` at the length of the text, `size` the size its last piece was cut at, and its final `found`, `emitted` and `errors`, so that an attempt that skips the unit still counts it. A cursor never says a unit is finished, wherever it stands: `completedUnits` does. A unit is an entity type for a linking job, a category for a tagging job, and the job's own motivation for every other \u2014 which is why a unit-grain checkpoint alone is too coarse: those three have exactly one unit, so nothing could be recorded until the whole document was done.\\n\\nMERGE IS MONOTONE PER UNIT, not a union. `completedUnits` is a set and converges under concurrent snapshots because a set only grows; a cursor converges only if a stale snapshot can never move it backward.\\n\\nIT CARRIES THE UNIT'S RUNNING TALLIES TOO, and they are required. A resumed unit counts only the chunks it actually runs, so without them a retry's terminal record reports the remainder of the document as if it were the whole \u2014 measured at a `found` of 19 where the document yielded 25. The position and the tallies are ONE observation of the same committed chunk; splitting them would let a resume take the saving and still report a number nobody can trust.\",\"properties\":{\"next\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Unicode code points of the text consumed once the last COMMITTED chunk completed \u2014 the resume position, and the length of the text for a unit whose last chunk it was. Deliberately the chunk's `next`, never its `at`: the checkpoint must not lead the log, so it records where a chunk that is already durable ended, not where the in-flight one began. Recording `at` would make a resume re-run the chunk it already paid for.\"},\"size\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The token size that last committed chunk was cut at \u2014 the calibration the attempt paid for over the chunks before it. A resume seeds from this and then takes ONE adaptive step, as if the last outcome were a failure, which it was: the job died. Seeding alone would re-cut the failing piece identically; opening at the default would discard the calibration.\"},\"found\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Items detection has returned for this unit through the last committed chunk \u2014 the numerator a resumed attempt continues from rather than restarting at zero. Counts what the model reported, before dedupe.\"},\"emitted\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Annotations actually committed for this unit through the last committed chunk, after dedupe. With `found` and `errors` it is what the job's terminal result reports, so a resumed unit seeds all three and its record describes the whole document rather than one attempt's share.\"},\"errors\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Items detection returned for this unit through the last committed chunk that could not be anchored in the text. Carried with the other two tallies so that a resumed job reports the whole document's, and not only its last attempt's.\"}},\"required\":[\"next\",\"size\",\"found\",\"emitted\",\"errors\"]},\"JobDeclined\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobDeclined.json\",\"type\":\"object\",\"description\":\"Result of a job that completed without doing its work because the resource could not be read. Distinct from a failure: nothing went wrong, there was simply no text to work with \u2014 an encrypted or damaged PDF, a scan whose text could not be recognized, or a document that yielded nothing. The reasons are the extraction vocabulary the Smelter reports on `smelt:settled`, MINUS `no-extractor`: a media type that can never yield text (a zip, an image) is a bad request rather than a decline, so a worker asked to detect over one throws and the job reports `job:fail`. Everything here is a resource-specific outcome \u2014 the same media type would have succeeded on a different document.\",\"properties\":{\"declined\":{\"type\":\"boolean\",\"enum\":[true],\"description\":\"Always true. It is what tells a decline from the result of a job that did its work, which never carries it.\"},\"reason\":{\"type\":\"string\",\"enum\":[\"no-text-layer\",\"encrypted\",\"corrupt\",\"too-large\",\"empty\"],\"description\":\"Why the resource could not be read. A CODE, not a sentence: the client owns the wording, so a browser renders it in the user's language and the CLI renders English terminal copy from the same value. A prose `message` composed server-side would be English everywhere.\"}},\"required\":[\"declined\",\"reason\"],\"additionalProperties\":false},\"JobFailedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobFailedPayload.json\",\"type\":\"object\",\"description\":\"Payload for the job:failed domain event \u2014 a permanent fact of the resource, not operational state. It carries the judgments the worker COMPUTED, not just its message: at the log they are otherwise unrecoverable, the only remaining witness being a flattened English string.\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"attempt\":{\"type\":\"integer\",\"description\":\"Which attempt produced this event, 1-based (a first run is 1). ALWAYS present: the queue re-runs a failed job silently, so an operator reading progress or a terminal record has no other way to tell a re-run from a first run \u2014 and provider spend, already counted in xynolog_inference_tokens_total, cannot be attributed to a repeated document without it. Stated rather than inferred from absence, because 'attempt 1' is a fact the emitter always knows.\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Annotation this job was attached to, when applicable\"},\"error\":{\"type\":\"string\"},\"failureClass\":{\"$ref\":\"https://xynolog.org/protocol/FailureClass.json\"},\"willRetry\":{\"type\":\"boolean\",\"description\":\"Whether the worker computed that the queue would re-queue this job (same predicate the queue applies, `willRetryAfter`). Absent means the worker stated nothing. Without it a reader of the log cannot tell a run recovering across several job:failed events from that many dead jobs.\"},\"durability\":{\"$ref\":\"https://xynolog.org/protocol/DurabilityEvidence.json\"}},\"required\":[\"jobId\",\"jobType\",\"error\"]},\"YieldJobDone\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldJobDone.json\",\"type\":\"object\",\"description\":\"What a `yield` job reports when it has made its resource. The worker creates the resource first (the create round trip returns its id), then emits job:complete carrying it, so resourceId is always present on the wire.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"ID of the generated resource, obtained by the worker from the create round-trip before job:complete is emitted\"},\"resourceName\":{\"type\":\"string\",\"description\":\"Name of the generated resource\"},\"truncated\":{\"type\":\"boolean\",\"description\":\"True when the model stopped at the maxTokens ceiling \u2014 the artifact is cut off, not complete. Derived at the producer from the provider's stopReason ('max_tokens' \u2192 true); required because the worker always knows.\"}},\"required\":[\"resourceId\",\"resourceName\",\"truncated\"],\"additionalProperties\":false},\"JobProgress\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgress.json\",\"type\":\"object\",\"description\":\"Progress report from a running job. The required field is `percentage`; `message` carries the coded phase and the rest are optional job-shape fields. This is the single progress shape for every job type \u2014 annotation workers and generation alike. Terminality is signalled on `job:complete` / `job:fail`, not here. A flow that iterates a user-chosen list (entity types for references, categories for tags) reports its position as one `current`/`processed`/`total` triple, the same shape for both, so a client never needs to know which flow it is drawing.\",\"properties\":{\"percentage\":{\"type\":\"number\",\"description\":\"Completion percentage (0-100)\"},\"message\":{\"$ref\":\"https://xynolog.org/protocol/JobProgressMessage.json\",\"description\":\"What the job is doing right now, as a code plus typed params; the client renders the sentence. Optional: pure percentage heartbeats carry none, and consumers render nothing message-shaped when it is absent.\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Annotation this job is attached to, when applicable. Echoed inside JobProgress (in addition to the outer command envelope) so consumers that only see the inner progress object (e.g. what `yield.delegate` returns) can still route visual feedback to a specific annotation.\"},\"current\":{\"type\":\"object\",\"description\":\"What the run is working on right now. `kind` is a CODE the client renders a localized name for; `value` is KB data (an entity type, a tag category) shown verbatim \u2014 the same split as `requestParams`. Absent on flows that iterate nothing, such as generation.\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"entity-type\",\"category\"],\"description\":\"What sort of thing `value` is. Adding a variant means adding client copy for it in every locale.\"},\"value\":{\"type\":\"string\",\"description\":\"The item itself, shown verbatim and never translated.\"}},\"required\":[\"kind\",\"value\"]},\"processed\":{\"type\":\"integer\",\"description\":\"Items completed so far, zero-based \u2014 the item in `current` is the one after these. Paired with `total`.\"},\"total\":{\"type\":\"integer\",\"description\":\"Items this run will process in all.\"},\"entitiesFound\":{\"type\":\"integer\",\"description\":\"Entities found so far (a linking job)\"},\"entitiesExpected\":{\"type\":\"integer\",\"description\":\"Cumulative mentions the count-verifier priced across the pieces accepted so far \u2014 the denominator for a real progress bar (found of ~expected). Approximate by nature (the count saturates on very large pieces) and monotonically growing within a run. ABSENT when the provider does not verify detection yield, or before any piece has been priced: no claim, never zero.\"},\"entitiesEmitted\":{\"type\":\"integer\",\"description\":\"Annotations emitted so far (a linking job)\"},\"completedItems\":{\"type\":\"array\",\"description\":\"Per-item results for the items already finished, for the UI's completed log. Generic across flows for the same reason `current` is.\",\"items\":{\"type\":\"object\",\"properties\":{\"value\":{\"type\":\"string\",\"description\":\"The item, shown verbatim.\"},\"foundCount\":{\"type\":\"integer\",\"description\":\"Annotations found for it.\"},\"persistedCount\":{\"type\":\"integer\",\"description\":\"Annotations actually persisted for it \u2014 post-dedupe and post-durability-acknowledgement, so it counts what the event log holds, not what the model proposed. Beside foundCount this is the per-unit yield the sizing work is judged by. Present on flows whose units persist as they complete (a linking job); the tagging flow reports the same fact as byCategory on its result, because its annotations are built after the per-category loop.\"},\"underReported\":{\"type\":\"object\",\"description\":\"Present only when pieces of this unit were accepted at the subdivision floor while a count call said more was present. The unit completed, but incompletely \u2014 this carries the EVIDENCE (found vs counted, over how many pieces), never a judgment against any expected yield. Absent means complete: genuinely absent, not defaulted.\",\"properties\":{\"pieces\":{\"type\":\"integer\",\"description\":\"Floor-accepted pieces in this unit.\"},\"found\":{\"type\":\"integer\",\"description\":\"Annotations extraction did find on those pieces \u2014 every span write-time-verified.\"},\"counted\":{\"type\":\"integer\",\"description\":\"Mentions the count calls reported across those pieces (approximate by nature).\"}},\"required\":[\"pieces\",\"found\",\"counted\"]}},\"required\":[\"value\",\"foundCount\"]}},\"requestParams\":{\"type\":\"array\",\"description\":\"Echoed job parameters for display in the progress UI. `label` is a CODE, not a sentence \u2014 the client owns the wording, same rule as the progress message. `value` is the user's own input (an entity-type list, their instructions) and is deliberately NOT translated: it is their words, not ours.\",\"items\":{\"type\":\"object\",\"properties\":{\"label\":{\"type\":\"string\",\"enum\":[\"entity-types\",\"instructions\",\"tone\",\"density\"],\"description\":\"Which parameter this is. The client renders a localized name for it.\"},\"value\":{\"type\":\"string\",\"description\":\"The user's own input, shown verbatim.\"}},\"required\":[\"label\",\"value\"]}}},\"required\":[\"percentage\"]},\"JobProgressMessage\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressMessage.json\",\"description\":\"What a running job is doing right now, as a code plus typed params \u2014 never a prose sentence. The producer reports what happened; each client renders it in the user's language (react-ui from its translations, the Go launcher from its English map). One named schema per code, discriminated on `code`, so generated clients get typed variants and copy-map completeness is statically checkable. The vocabulary is every report Xynolog's worker makes (contract/WORKER-SERVICE.md, D16 to D19 and Y8); extending it means adding a named variant here and copy in every client, gated by the locale-completeness check.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/JobProgressLoading.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobProgressAnalyzing.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobProgressAnalyzingTags.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobProgressGeneratingResource.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobProgressCreatingResource.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobProgressCompleteGenerated.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobProgressDetectingEntities.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobProgressCreatingAnnotations.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobProgressCreatingTagAnnotations.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobProgressCompleteCreated.json\"}],\"discriminator\":{\"propertyName\":\"code\",\"mapping\":{\"loading\":\"https://xynolog.org/protocol/JobProgressLoading.json\",\"analyzing\":\"https://xynolog.org/protocol/JobProgressAnalyzing.json\",\"analyzing-tags\":\"https://xynolog.org/protocol/JobProgressAnalyzingTags.json\",\"generating-resource\":\"https://xynolog.org/protocol/JobProgressGeneratingResource.json\",\"creating-resource\":\"https://xynolog.org/protocol/JobProgressCreatingResource.json\",\"complete-generated\":\"https://xynolog.org/protocol/JobProgressCompleteGenerated.json\",\"detecting-entities\":\"https://xynolog.org/protocol/JobProgressDetectingEntities.json\",\"creating-annotations\":\"https://xynolog.org/protocol/JobProgressCreatingAnnotations.json\",\"creating-tag-annotations\":\"https://xynolog.org/protocol/JobProgressCreatingTagAnnotations.json\",\"complete-created\":\"https://xynolog.org/protocol/JobProgressCompleteCreated.json\"}}},\"JobProgressAnalyzing\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressAnalyzing.json\",\"type\":\"object\",\"description\":\"Analyzing the content.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"analyzing\"]}},\"required\":[\"code\"]},\"JobProgressAnalyzingTags\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressAnalyzingTags.json\",\"type\":\"object\",\"description\":\"Analyzing the content against the tag schema.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"analyzing-tags\"]}},\"required\":[\"code\"]},\"JobProgressCompleteCreated\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressCompleteCreated.json\",\"type\":\"object\",\"description\":\"Terminal success summary.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"complete-created\"]},\"count\":{\"type\":\"integer\",\"description\":\"How many annotations were created\"},\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\",\"description\":\"The motivation of the job, and so of what it created. A client words it in its own language.\"}},\"required\":[\"code\",\"count\",\"motivation\"]},\"JobProgressCompleteGenerated\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressCompleteGenerated.json\",\"type\":\"object\",\"description\":\"Generation's terminal success. Deliberately generic \u2014 the client already holds the title it typed, and the outcome (name + resource link) travels on job:complete, not on progress. `truncated` qualifies the completion: the same bit `YieldJobDone.truncated` carries, so the two surfaces cannot drift.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"complete-generated\"]},\"truncated\":{\"type\":\"boolean\",\"description\":\"True when the model stopped at the maxTokens ceiling \u2014 the artifact is cut off, not complete.\"}},\"required\":[\"code\",\"truncated\"]},\"JobProgressCreatingAnnotations\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressCreatingAnnotations.json\",\"type\":\"object\",\"description\":\"Writing detected annotations back to the resource.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"creating-annotations\"]},\"count\":{\"type\":\"integer\",\"description\":\"How many annotations are being created\"}},\"required\":[\"code\",\"count\"]},\"JobProgressCreatingResource\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressCreatingResource.json\",\"type\":\"object\",\"description\":\"Writing the generated resource.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"creating-resource\"]}},\"required\":[\"code\"]},\"JobProgressCreatingTagAnnotations\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressCreatingTagAnnotations.json\",\"type\":\"object\",\"description\":\"Writing detected tag annotations back to the resource.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"creating-tag-annotations\"]},\"count\":{\"type\":\"integer\",\"description\":\"How many annotations are being created\"}},\"required\":[\"code\",\"count\"]},\"JobProgressDetectingEntities\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressDetectingEntities.json\",\"type\":\"object\",\"description\":\"Entity detection, one entity type at a time.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"detecting-entities\"]},\"entityType\":{\"type\":\"string\",\"description\":\"Entity type currently being detected\"}},\"required\":[\"code\",\"entityType\"]},\"JobProgressGeneratingResource\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressGeneratingResource.json\",\"type\":\"object\",\"description\":\"The model is generating the resource.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"generating-resource\"]}},\"required\":[\"code\"]},\"JobProgressLoading\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobProgressLoading.json\",\"type\":\"object\",\"description\":\"Loading the resource content.\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"loading\"]}},\"required\":[\"code\"]},\"JobQueuedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobQueuedEvent.json\",\"description\":\"A pending job, announced when it is created and again at each tick while it waits. It carries the job description less the job's input, so that a party deciding whether to claim reads here what its claim would be matched against. It is a wake-up and not an offer of this job: a claim is answered with the next pending job it matches.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/MarkJobQueuedEvent.json\"},{\"$ref\":\"https://xynolog.org/protocol/YieldJobQueuedEvent.json\"}],\"discriminator\":{\"propertyName\":\"jobType\",\"mapping\":{\"mark\":\"https://xynolog.org/protocol/MarkJobQueuedEvent.json\",\"yield\":\"https://xynolog.org/protocol/YieldJobQueuedEvent.json\"}}},\"MarkJobDone\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkJobDone.json\",\"type\":\"object\",\"description\":\"What a `mark` job reports when it has done its work, whatever its motivation.\",\"properties\":{\"found\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"What the model proposed, before anything was checked against the text.\"},\"persisted\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"What the log holds: the annotations committed, after the ones that could not be anchored were dropped and repeats were collapsed.\"},\"errors\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"How many of the proposed could not be anchored in the text. Absent means none.\"},\"byCategory\":{\"type\":\"object\",\"additionalProperties\":{\"type\":\"integer\"},\"description\":\"The annotations persisted per category. A tagging job's; absent from every other.\"},\"underReportedPieces\":{\"type\":\"integer\",\"description\":\"Total floor-accepted under-reported pieces across the job's units. Absent means none \u2014 the per-unit evidence rides the terminal progress frame's completedItems; this keeps the result self-describing without the progress stream.\"},\"uncheckedPieces\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"Pieces whose yield was to be checked against a count and was not: the count failed, was cut off, or answered no count. What they found was kept unchecked. Absent means none: every piece that was to be checked was. A job whose provider checks no yield has none.\"}},\"required\":[\"found\",\"persisted\"],\"additionalProperties\":false},\"JobReportProgressCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobReportProgressCommand.json\",\"type\":\"object\",\"description\":\"Command to report progress on a job\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"attempt\":{\"type\":\"integer\",\"description\":\"Which attempt produced this event, 1-based (a first run is 1). ALWAYS present: the queue re-runs a failed job silently, so an operator reading progress or a terminal record has no other way to tell a re-run from a first run \u2014 and provider spend, already counted in xynolog_inference_tokens_total, cannot be attributed to a repeated document without it. Stated rather than inferred from absence, because 'attempt 1' is a fact the emitter always knows.\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Annotation this job is attached to, when applicable. Lets the UI attach progress visuals to a specific annotation (e.g. a reference whose generation is running).\"},\"percentage\":{\"type\":\"number\"},\"progress\":{\"$ref\":\"https://xynolog.org/protocol/JobProgress.json\"}},\"required\":[\"resourceId\",\"jobId\",\"jobType\",\"percentage\"]},\"JobResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobResult.json\",\"description\":\"What a job reports when it concludes without failing: a `mark` job's counts, the resource a `yield` job made, or a decline from either. A result has no discriminant of its own: the job description beside it says which job it answers, and the three share no member, so each is told from the others by what it alone carries.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/MarkJobDone.json\"},{\"$ref\":\"https://xynolog.org/protocol/YieldJobDone.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobDeclined.json\"}]},\"JobStartCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobStartCommand.json\",\"type\":\"object\",\"description\":\"Command to start a job\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Annotation this job is attached to, when applicable. Set for annotation-scoped jobs like generation (from a specific reference). Unset for resource-scoped jobs like bulk reference/tag/highlight detection.\"},\"attempt\":{\"type\":\"integer\",\"description\":\"Which attempt produced this event, 1-based (a first run is 1). ALWAYS present: the queue re-runs a failed job silently, so an operator reading progress or a terminal record has no other way to tell a re-run from a first run \u2014 and provider spend, already counted in xynolog_inference_tokens_total, cannot be attributed to a repeated document without it. Stated rather than inferred from absence, because 'attempt 1' is a fact the emitter always knows.\"}},\"required\":[\"resourceId\",\"jobId\",\"jobType\"]},\"JobAssignCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobAssignCommand.json\",\"type\":\"object\",\"description\":\"Bus command the dispatcher emits, under its own service identity, immediately after it accepts a job:claim \u2014 the correlated job:claimed reply is unchanged. The Stower persists it as job:assigned. It is the one fact only the dispatcher can vouch for: which holder took which job, and who requested it. A later write citing `jobId` is checked against the holder and its `creator` derived from the requester by reading the resource's own log, with nothing outside the record.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"The dispatcher's service DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The job's resource \u2014 for a generation, the source it generates from. The assignment is persisted on this resource's log.\"},\"holder\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"DID of the claimant whose claim was accepted \u2014 the `_userId` the gateway stamped on the job:claim, restated by the dispatcher.\"},\"requester\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"DID of the emitter of the job:create that produced this job \u2014 the `_userId` the gateway stamped on that create, restated by the dispatcher.\"}},\"required\":[\"jobId\",\"jobType\",\"resourceId\",\"holder\",\"requester\"]},\"JobStartedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobStartedPayload.json\",\"type\":\"object\",\"description\":\"Payload for job:started domain event\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Annotation this job is attached to, when applicable\"},\"totalSteps\":{\"type\":\"integer\"}},\"required\":[\"jobId\",\"jobType\"]},\"JobAssignedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobAssignedPayload.json\",\"type\":\"object\",\"description\":\"Payload for job:assigned \u2014 the dispatcher's own record that it accepted a claim. Emitted by the dispatcher under its service identity after a successful job:claim (the correlated job:claimed reply is unchanged). This is the one fact only the dispatcher can vouch for: which holder took which job, and who requested it. The Stower persists it beside job:started so that a write citing `jobId` can be checked against the holder and its `creator` derived from the requester with no read outside the event log.\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The job's resource \u2014 for a generation, the source it generates from. Job events are scoped here.\"},\"holder\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"DID of the emitter whose claim the dispatcher accepted. The bus stamped it on the job:claim as `_userId`; the dispatcher restates it here under its own identity.\"},\"requester\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"DID of the emitter of the job:create that produced this job. The dispatcher restates the `_userId` the gateway stamped on that create.\"}},\"required\":[\"jobId\",\"jobType\",\"resourceId\",\"holder\",\"requester\"]},\"PrincipalProfileCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/PrincipalProfileCommand.json\",\"type\":\"object\",\"description\":\"Bus command saying what a principal is called. The gateway emits it when a principal ACTS, carrying the display name it just verified on its token; a principal may also emit it itself, for itself, which is how an agent, whose token carries no name, says what it is called. Either way the gateway stamps `_userId` with the sender's verified DID, so a principal names only itself. The Stower persists it as principal:profiled, and only when the name differs from the latest one recorded for that DID \u2014 so the log holds one line per name a principal has had, not one per act. A name is a fact ABOUT an identity, never part of the record of an act: no artifact carries it, and readers resolve it from the profiles projection. Emitted for a person and for an agent alike; never for a request that merely reads.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"The principal's DID, injected by the /bus/emit gateway from the verified token. Clients do not set this.\"},\"name\":{\"type\":\"string\",\"description\":\"The display name: from the issuer's `name` claim, as verified on the token that carried an act, or what the principal said of itself. A token with no name produces no command from the gateway \u2014 the issuer is where a person's name is set, and absence is recorded as absence.\"}},\"required\":[\"name\"]},\"PrincipalProfiledPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/PrincipalProfiledPayload.json\",\"type\":\"object\",\"description\":\"Payload for principal:profiled \u2014 what this principal is called, as the issuer's verified `name` claim said or as the principal said of itself, recorded once per change (system-level, no resourceId). The event's `userId` is the principal's DID; this payload is the fact about it. Provenance never reads it: every artifact joins on the DID alone, and this is projected into profiles.json for readers to resolve against. Two lines for one DID mean the name changed, and the timestamps say when \u2014 which is why no artifact ever had to freeze a copy.\",\"properties\":{\"name\":{\"type\":\"string\",\"description\":\"The display name as of this event: from the issuer's verified `name` claim, or what the principal said of itself.\"}},\"required\":[\"name\"]},\"JobStatusRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobStatusRequest.json\",\"type\":\"object\",\"description\":\"Request to check the status of a job\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"}},\"required\":[\"jobId\"]},\"JobStatusResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobStatusResponse.json\",\"type\":\"object\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"type\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"status\":{\"type\":\"string\",\"enum\":[\"pending\",\"running\",\"complete\",\"failed\",\"cancelled\"]},\"userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\"},\"created\":{\"type\":\"string\"},\"startedAt\":{\"type\":\"string\"},\"completedAt\":{\"type\":\"string\"},\"error\":{\"type\":\"string\"},\"failureClass\":{\"$ref\":\"https://xynolog.org/protocol/FailureClass.json\"},\"progress\":{\"$ref\":\"https://xynolog.org/protocol/JobStoredProgress.json\"},\"result\":{\"$ref\":\"https://xynolog.org/protocol/JobStoredResult.json\"}},\"required\":[\"jobId\",\"type\",\"status\",\"userId\",\"created\"]},\"JobStatusResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobStatusResult.json\",\"type\":\"object\",\"description\":\"Result of a job status request\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/JobStatusResponse.json\"}},\"required\":[\"response\"]},\"JobType\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobType.json\",\"type\":\"string\",\"description\":\"What a job does, as the verb that asks for it: `mark` annotates a resource, `yield` makes one. A job description is its `jobType` and the parameters that verb takes; a `mark` job's parameters state its motivation.\",\"enum\":[\"mark\",\"yield\"]},\"KbDescription\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/KbDescription.json\",\"type\":\"object\",\"description\":\"What a knowledge base says about itself, answered by the Archivist from the committed .xynolog/config.yaml and the working tree it holds. The only source clients use for a knowledge base's name and domain.\",\"properties\":{\"name\":{\"type\":\"string\",\"description\":\"The committed project.name, or the knowledge base directory's name when it commits no .xynolog/config.yaml.\"},\"domain\":{\"type\":\"string\",\"description\":\"The committed site.domain: the knowledge base's permanent identity. Its did is 'did:web:' + this domain (kbDid in @xynolog/core). It names WHICH knowledge base this is, not which running copy: a local clone and a codespace of one repo report the same domain, so use it to verify what you connected to, never to select among copies. A knowledge base that commits no .xynolog/config.yaml declares none, and is refused with browse:kb-failed.\"},\"gitBranch\":{\"type\":\"string\",\"description\":\"The working tree's current git branch. Absent when the knowledge base does not sync git (`git.sync` in its committed .xynolog/config.yaml), and when its tree is not a git checkout.\"}},\"required\":[\"name\",\"domain\"]},\"HttpEndpoint\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/HttpEndpoint.json\",\"type\":\"object\",\"description\":\"A knowledge base reached through its gateway, over HTTP. The gateway's origin is the protocol, the host in lowercase and the port; a host that is not a host's name is refused before it is put into a URL (specs/src/session/gateway-url-cases.json).\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"http\"],\"description\":\"Discriminant: the endpoint is a gateway reached over HTTP.\"},\"host\":{\"type\":\"string\",\"description\":\"The gateway's host, as a person or a discovery document gave it.\"},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The gateway's port.\"},\"protocol\":{\"type\":\"string\",\"enum\":[\"http\",\"https\"],\"description\":\"What the gateway is reached over.\"}},\"required\":[\"kind\",\"host\",\"port\",\"protocol\"]},\"KbEndpoint\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/KbEndpoint.json\",\"description\":\"How a knowledge base is reached: a gateway over HTTP, or a knowledge base the host process has loaded. Told apart by `kind`. Only what builds a transport, or signs in at an issuer, reads it.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/HttpEndpoint.json\"},{\"$ref\":\"https://xynolog.org/protocol/LocalEndpoint.json\"}],\"discriminator\":{\"propertyName\":\"kind\",\"mapping\":{\"http\":\"https://xynolog.org/protocol/HttpEndpoint.json\",\"local\":\"https://xynolog.org/protocol/LocalEndpoint.json\"}}},\"KbRead\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/KbRead.json\",\"type\":\"object\",\"description\":\"When a knowledge base last described itself, and what it said beyond its name. A client shows it as current only while a session to the knowledge base is live, and as of `at` otherwise.\",\"properties\":{\"at\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"When the description arrived.\"},\"gitBranch\":{\"type\":\"string\",\"description\":\"The branch of the knowledge base's working tree then. Absent when the working tree was not a git checkout.\"}},\"required\":[\"at\"]},\"KbTarget\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/KbTarget.json\",\"type\":\"object\",\"description\":\"Where to connect to a knowledge base: an endpoint, and the labels a client keeps of it. It carries no identity: which knowledge base answers at an address is known only once it has been reached with a token and asked, so a target is what every caller can build before then, and a session's whole input. A client keeps it locally; it is never sent.\",\"properties\":{\"id\":{\"type\":\"string\",\"description\":\"The key the client stores a session's credentials under. Two sessions that share one storage have two ids, or each overwrites the other's tokens. Whoever builds the target chooses it; none is made up.\"},\"label\":{\"type\":\"string\",\"description\":\"What a person reads the knowledge base as. Once the knowledge base has described itself, its own name.\"},\"endpoint\":{\"$ref\":\"https://xynolog.org/protocol/KbEndpoint.json\"}},\"required\":[\"id\",\"label\",\"endpoint\"]},\"KnowledgeBase\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/KnowledgeBase.json\",\"description\":\"A registered knowledge base: a target, and what registering it took, the identity the knowledge base reported of itself when it was reached (`did`) among it. What a client's list of knowledge bases holds. A did says which knowledge base, not which running copy: a clone and a codespace of one repository are one knowledge base at two addresses and report one did. So an entry is looked up by its endpoint, and its did is what an answer is verified against; nothing selects by did. Its `label` and `lastRead` are written only from an answer that carried its did.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/KbTarget.json\"},{\"$ref\":\"https://xynolog.org/protocol/NewKnowledgeBase.json\"}]},\"LocalEndpoint\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/LocalEndpoint.json\",\"type\":\"object\",\"description\":\"A knowledge base the host process has loaded and reaches through a transport with no wire.\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"local\"],\"description\":\"Discriminant: the endpoint is in the host process.\"},\"kbId\":{\"type\":\"string\",\"description\":\"Which loaded knowledge base, named by an id that means something to the host process alone.\"}},\"required\":[\"kind\",\"kbId\"]},\"NewKnowledgeBase\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/NewKnowledgeBase.json\",\"type\":\"object\",\"description\":\"What registering a knowledge base takes: everything a registered one holds but its id, which the client's list makes. It has a did, because registering follows a sign-in: the knowledge base has already said what it is.\",\"properties\":{\"label\":{\"type\":\"string\",\"description\":\"What a person reads the knowledge base as. Once the knowledge base has described itself, its own name.\"},\"endpoint\":{\"$ref\":\"https://xynolog.org/protocol/KbEndpoint.json\"},\"did\":{\"type\":\"string\",\"description\":\"The did the knowledge base reported of itself.\"},\"lastRead\":{\"$ref\":\"https://xynolog.org/protocol/KbRead.json\",\"description\":\"The last time the knowledge base described itself. Absent until it has, in an answer that carried this entry's did.\"}},\"required\":[\"label\",\"endpoint\",\"did\"]},\"KnowledgeGraph\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/KnowledgeGraph.json\",\"type\":\"object\",\"description\":\"Knowledge graph gathered for an LLM context \u2014 a shared backbone in which resources AND annotations are typed nodes, connected by typed (optionally bidirectional) edges. Flattened views the matcher/generation read (connections, citedBy, siblings) are derived from these nodes/edges.\",\"properties\":{\"nodes\":{\"type\":\"array\",\"items\":{\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/GraphResourceNode.json\"},{\"$ref\":\"https://xynolog.org/protocol/GraphAnnotationNode.json\"}],\"discriminator\":{\"propertyName\":\"type\",\"mapping\":{\"resource\":\"https://xynolog.org/protocol/GraphResourceNode.json\",\"annotation\":\"https://xynolog.org/protocol/GraphAnnotationNode.json\"}}}},\"edges\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"source\":{\"type\":\"string\"},\"target\":{\"type\":\"string\"},\"type\":{\"type\":\"string\",\"description\":\"Edge kind: `annotation-of` (an annotation \u2192 the resource it lives on), `cites` (a citing linking annotation \u2192 the focal resource), or `link` (a resource \u2192 a resource it links to)\"},\"bidirectional\":{\"type\":\"boolean\",\"description\":\"Whether the connection goes both ways. Absent on a `link` edge found through what cites a resource, which says nothing of the way back\"},\"metadata\":{\"type\":\"object\",\"additionalProperties\":{}}},\"required\":[\"source\",\"target\",\"type\"]}},\"truncated\":{\"type\":\"boolean\",\"description\":\"Whether the graph stopped taking resources at its ceiling of 200 resource nodes, so that a resource within the depth asked for is not in it. Present, and true, only then\"}},\"required\":[\"nodes\",\"edges\"]},\"ListResourcesResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ListResourcesResponse.json\",\"type\":\"object\",\"properties\":{\"resources\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"}},\"total\":{\"type\":\"number\"},\"offset\":{\"type\":\"number\"},\"limit\":{\"type\":\"number\"}},\"required\":[\"resources\",\"total\",\"offset\",\"limit\"]},\"MarkArchiveCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkArchiveCommand.json\",\"type\":\"object\",\"description\":\"Bus command to archive a resource and optionally remove its file.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"storageUri\":{\"type\":\"string\",\"description\":\"Optional: where the resource's bytes live, so the archive can act on the file. An instruction to this handler, not a copy of the stored fact (that lives on the primary Representation). Working-tree URI, only file:// is supported.\"},\"keepFile\":{\"type\":\"boolean\"}},\"required\":[\"resourceId\"]},\"MarkCreateOk\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkCreateOk.json\",\"type\":\"object\",\"description\":\"Success reply after creating an annotation, matched to the originating command by correlationId.\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/MarkCreateOkResponse.json\"}},\"required\":[\"response\"]},\"MarkCreateOkResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkCreateOkResponse.json\",\"type\":\"object\",\"description\":\"The created annotation's identity.\",\"properties\":{\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"}},\"required\":[\"annotationId\"]},\"MarkCommitCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkCommitCommand.json\",\"type\":\"object\",\"description\":\"Bus command to persist a detection unit's annotations as one acknowledged batch. It is answered only after every annotation is in the event log, so a worker can gate unit completion on durability rather than on emission. The batch is the unit: a partial commit is reported as a failure, and the worker retries the whole unit, which is safe because annotation ids are deterministic: content-addressed, so re-emitting one is a no-op.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"_roles\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The emitter's capabilities (the token's `roles`), injected by the /bus/emit gateway. Clients do not set this. An emitter carrying the worker role must cite the job this batch fulfils in `jobId`; the Stower refuses the batch otherwise.\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\",\"description\":\"The job this batch fulfils. Required when the emitter carries the worker role; absent for self-initiated work (a person, or an agent acting on its own). The knowledge base derives who requested these annotations from the cited job's own events \u2014 the emitter never says who the work was for.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Resource every annotation in this batch targets.\"},\"annotations\":{\"type\":\"array\",\"description\":\"The unit's annotations, already built with deterministic ids. Re-committing an identical batch is a no-op rather than a duplicate.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/Annotation.json\"}}},\"required\":[\"resourceId\",\"annotations\"]},\"MarkCommitOk\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkCommitOk.json\",\"type\":\"object\",\"description\":\"Durability acknowledgement for a mark:commit batch: every annotation named by the command is in the event log at the moment this is emitted.\",\"properties\":{\"response\":{\"type\":\"object\",\"description\":\"What the commit persisted.\",\"properties\":{\"persisted\":{\"type\":\"integer\",\"description\":\"Annotations the command named that are durable in the event log. Equals the batch size on success, on a first commit and on a retry alike \u2014 the commit appends only what the resource does not already hold, so a wholly-redundant retry has still succeeded and says so. Not an append tally: a caller must never have to read a 0 as 'all good'.\"},\"annotationIds\":{\"type\":\"array\",\"description\":\"Ids the batch covers, whether appended now or already present.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"}}},\"required\":[\"persisted\",\"annotationIds\"]}},\"required\":[\"response\"]},\"MarkCreateRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkCreateRequest.json\",\"type\":\"object\",\"description\":\"Raw annotation creation intent \u2014 bus handler assembles the W3C annotation\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"request\":{\"$ref\":\"https://xynolog.org/protocol/CreateAnnotationRequest.json\"}},\"required\":[\"resourceId\",\"request\"]},\"MarkDeleteCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkDeleteCommand.json\",\"type\":\"object\",\"description\":\"Bus command to delete an annotation.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"annotationId\"]},\"MarkDeleteOk\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkDeleteOk.json\",\"type\":\"object\",\"description\":\"Success reply after deleting an annotation, matched to the originating command by correlationId.\",\"properties\":{\"response\":{\"type\":\"object\",\"description\":\"The deleted annotation's identity.\",\"properties\":{\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"}},\"required\":[\"annotationId\"]}},\"required\":[\"response\"]},\"MarkRequestedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkRequestedEvent.json\",\"type\":\"object\",\"description\":\"Emitted when the user requests a new mark (annotation) on a resource\",\"properties\":{\"source\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The '@id' of the resource the mark belongs to (W3C target.source). Routes the event to the right viewer/state unit when a host mounts many viewers on one session.\"},\"selector\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationSelector.json\",\"description\":\"One or more W3C selectors\"},\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\"}},\"required\":[\"source\",\"selector\",\"motivation\"]},\"MarkSubmitEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkSubmitEvent.json\",\"type\":\"object\",\"description\":\"Emitted when a mark is submitted with its annotation body\",\"properties\":{\"source\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The '@id' of the resource the mark belongs to (W3C target.source). Routes the submit to the state unit bound to that resource \u2014 without it, N mounted units each create the annotation (N copies on N resources).\"},\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\"},\"selector\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationSelector.json\",\"description\":\"One or more W3C selectors\"},\"body\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationBodies.json\",\"description\":\"Optional body. Omit for annotations whose motivation alone is meaningful (e.g. highlighting) or whose user-supplied content is empty (e.g. an assessing annotation saved without comment text). Shape matches Annotation.body.\"}},\"required\":[\"source\",\"motivation\",\"selector\"]},\"MarkUnarchiveCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkUnarchiveCommand.json\",\"type\":\"object\",\"description\":\"Bus command to unarchive a previously archived resource.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"storageUri\":{\"type\":\"string\",\"description\":\"Optional: where the resource's bytes are expected to be. When present the handler VERIFIES the file exists and fails loudly if it does not, rather than succeeding as a no-op. An instruction, not a copy of the stored fact (that lives on the primary Representation). Working-tree URI, only file:// is supported.\"}},\"required\":[\"resourceId\"]},\"MarkUpdateBodyCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkUpdateBodyCommand.json\",\"type\":\"object\",\"description\":\"Bus command to update an annotation's body with patch operations.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"operations\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/BodyOperation.json\"}}},\"required\":[\"annotationId\",\"resourceId\",\"operations\"]},\"MarkUpdateEntityTypesCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkUpdateEntityTypesCommand.json\",\"type\":\"object\",\"description\":\"Bus command to replace the entity types on a resource.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"currentEntityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"updatedEntityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}},\"required\":[\"resourceId\",\"currentEntityTypes\",\"updatedEntityTypes\"]},\"MatchSearchFailed\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MatchSearchFailed.json\",\"description\":\"The payload of `match:search-failed`: a CommandError that names the reference whose candidates could not be searched for.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/CommandError.json\"},{\"type\":\"object\",\"properties\":{\"referenceId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"The reference the search was asked for.\"}},\"required\":[\"referenceId\"]}]},\"MatchSearchRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MatchSearchRequest.json\",\"type\":\"object\",\"description\":\"Request payload sent on the match:search-request bus channel to find candidate matches.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Resource ID the reference annotation belongs to. Used to scope result events on the EventBus so the events-stream delivers them to participants viewing this resource.\"},\"referenceId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Annotation ID of the reference to search candidates for\"},\"context\":{\"$ref\":\"https://xynolog.org/protocol/GatheredContext.json\",\"description\":\"Gathered context for the reference annotation\"},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":200,\"description\":\"Maximum number of candidate results to return\"},\"useSemanticScoring\":{\"type\":\"boolean\",\"description\":\"Enable semantic similarity scoring in addition to keyword matching\"}},\"required\":[\"resourceId\",\"referenceId\",\"context\"]},\"MatchSearchResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MatchSearchResult.json\",\"type\":\"object\",\"description\":\"Search results payload emitted on match:search-results SSE channel.\",\"properties\":{\"referenceId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"},\"response\":{\"type\":\"array\",\"description\":\"The scored candidates, best first.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/ScoredResource.json\"}}},\"required\":[\"referenceId\",\"response\"]},\"MatchResourcesRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MatchResourcesRequest.json\",\"type\":\"object\",\"description\":\"Request to search the knowledge base's resources by text. The Librarian answers: it matches the text lexically, and when nothing matches, by meaning.\",\"properties\":{\"search\":{\"type\":\"string\",\"description\":\"The text to search for.\"},\"archived\":{\"type\":\"boolean\"},\"entityType\":{\"type\":\"string\"},\"offset\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many of the resources the search finds are passed over before the page begins.\"},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":200,\"description\":\"The most resources a page has.\"}},\"required\":[\"search\"]},\"MatchResourcesResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MatchResourcesResponse.json\",\"type\":\"object\",\"description\":\"One page of the resources a text search found, and which kind of answer it is.\",\"properties\":{\"resources\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"}},\"total\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many resources the search found in all, and not only on this page.\"},\"offset\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many of the resources the search found were passed over before this page, as the request stated.\"},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The limit the search was made with.\"},\"matchKind\":{\"type\":\"string\",\"enum\":[\"lexical\",\"semantic\"],\"description\":\"What kind of answer this is: 'lexical' \u2014 the resources matched the query text; 'semantic' \u2014 no lexical match existed, and these resources discuss the query per the vector index. Required so every producer labels its answer; a UI can render semantic results as a different kind of page ('no title matches, but these documents discuss it').\"}},\"required\":[\"resources\",\"total\",\"offset\",\"limit\",\"matchKind\"]},\"MatchResourcesResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MatchResourcesResult.json\",\"type\":\"object\",\"description\":\"Result of searching resources by text\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/MatchResourcesResponse.json\"}},\"required\":[\"response\"]},\"MediaTokenRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MediaTokenRequest.json\",\"type\":\"object\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource ID to generate a media token for\"}},\"required\":[\"resourceId\"]},\"MediaTokenResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MediaTokenResponse.json\",\"type\":\"object\",\"properties\":{\"token\":{\"type\":\"string\",\"description\":\"Short-lived media token for use as ?token= query parameter on resource URLs\"}},\"required\":[\"token\"]},\"Motivation\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/Motivation.json\",\"type\":\"string\",\"enum\":[\"assessing\",\"commenting\",\"highlighting\",\"linking\",\"tagging\"],\"description\":\"Xynolog-supported W3C Web Annotation motivations - https://www.w3.org/TR/annotation-vocab/#motivation\"},\"ProtectedResourceMetadata\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ProtectedResourceMetadata.json\",\"type\":\"object\",\"description\":\"OAuth 2.0 Protected Resource Metadata (RFC 9728): which authorization server this knowledge base trusts, served at /.well-known/oauth-protected-resource so a client \u2014 the Browser, an MCP client \u2014 learns where to send a user to sign in without configuration. A 401 from any protected route points here in its WWW-Authenticate challenge.\",\"properties\":{\"resource\":{\"type\":\"string\",\"description\":\"This knowledge base's resource identifier: its did:web identity resolved to an https URL (did:web:example.github.io:my-kb identifies https://example.github.io/my-kb). This is the exact value a token's aud claim must carry. It is an identifier, not an address \u2014 nothing dereferences it, and a knowledge base reached over http in local development still names itself by the https form, which is what makes the value stable across every host, port and proxy it is reached through.\"},\"authorization_servers\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Issuer identifiers whose tokens this resource accepts \u2014 the configured identity issuer.\"},\"bearer_methods_supported\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"enum\":[\"header\"]},\"description\":\"How a bearer token reaches this resource: the Authorization header only.\"},\"resource_name\":{\"type\":\"string\",\"description\":\"The knowledge base's name, for a client's sign-in prompt.\"}},\"required\":[\"resource\",\"authorization_servers\",\"bearer_methods_supported\"],\"additionalProperties\":false},\"Representation\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/Representation.json\",\"type\":\"object\",\"description\":\"A specific, byte-addressable rendition of a resource (file/asset/variant).\",\"required\":[\"mediaType\"],\"additionalProperties\":true,\"properties\":{\"@id\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"Stable ID for this representation.\"},\"@type\":{\"description\":\"Type(s), e.g., schema:MediaObject.\",\"$ref\":\"https://xynolog.org/protocol/OneOrMoreStrings.json\"},\"mediaType\":{\"type\":\"string\",\"description\":\"MIME/media type (e.g., text/markdown, image/png).\"},\"storageUri\":{\"type\":\"string\",\"description\":\"Working-tree URI identifying where this rendition's bytes live. Only file:// is supported (e.g. file://docs/overview.md). The single home of the storage location: maintained across moves (yield:moved relocates it), absent when the resource has no stored bytes.\"},\"filename\":{\"type\":\"string\"},\"byteSize\":{\"description\":\"Size of the payload in bytes.\",\"type\":\"integer\",\"minimum\":0},\"checksum\":{\"description\":\"The SHA-256 of the bytes, as 64 lower-case hexadecimal digits with nothing before them. Whatever compares the checksums of two representations compares this text.\",\"type\":\"string\"},\"encoding\":{\"type\":\"string\",\"description\":\"Compression/transfer encoding if applicable.\"},\"language\":{\"type\":\"string\",\"description\":\"IETF BCP 47 language tag (e.g., en, es-ES).\"},\"width\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Pixels (images/video).\"},\"height\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Pixels (images/video).\"},\"duration\":{\"type\":\"number\",\"minimum\":0,\"description\":\"Seconds (audio/video).\"},\"created\":{\"type\":\"string\",\"format\":\"date-time\"},\"modified\":{\"type\":\"string\",\"format\":\"date-time\"},\"conformsTo\":{\"description\":\"Profile/shape the bytes conform to (e.g., a JSON profile or SVG profile).\",\"$ref\":\"https://xynolog.org/protocol/OneOrMoreUris.json\"},\"tags\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"rel\":{\"description\":\"Semantics of this rendition relative to the resource (e.g., original, thumbnail, preview, derived).\",\"type\":\"string\",\"enum\":[\"original\",\"thumbnail\",\"preview\",\"optimized\",\"derived\",\"other\"]}}},\"OneOrMoreStrings\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/OneOrMoreStrings.json\",\"oneOf\":[{\"type\":\"string\"},{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"minItems\":1}],\"description\":\"One string, or a non-empty list of them: a JSON-LD term that may take one value or several.\"},\"OneOrMoreUris\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/OneOrMoreUris.json\",\"oneOf\":[{\"type\":\"string\",\"format\":\"uri\"},{\"type\":\"array\",\"items\":{\"type\":\"string\",\"format\":\"uri\"},\"minItems\":1}],\"description\":\"One URI, or a non-empty list of them: a JSON-LD term that may name one resource or several.\"},\"RepresentationAddedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/RepresentationAddedPayload.json\",\"type\":\"object\",\"description\":\"Payload for yield:representation-added domain event\",\"properties\":{\"representation\":{\"$ref\":\"https://xynolog.org/protocol/Representation.json\"}},\"required\":[\"representation\"]},\"RepresentationRemovedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/RepresentationRemovedPayload.json\",\"type\":\"object\",\"description\":\"Payload for yield:representation-removed domain event\",\"properties\":{\"checksum\":{\"type\":\"string\",\"description\":\"Checksum of the representation to remove\"}},\"required\":[\"checksum\"]},\"ResourceArchivedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceArchivedPayload.json\",\"type\":\"object\",\"description\":\"Payload for mark:archived domain event\",\"properties\":{\"reason\":{\"type\":\"string\"}}},\"ResourceClonedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceClonedPayload.json\",\"type\":\"object\",\"description\":\"Payload for yield:cloned domain event\",\"properties\":{\"name\":{\"type\":\"string\"},\"format\":{\"$ref\":\"https://xynolog.org/protocol/ContentFormat.json\"},\"contentChecksum\":{\"type\":\"string\"},\"contentByteSize\":{\"type\":\"integer\"},\"storageUri\":{\"type\":\"string\",\"description\":\"Where the clone's bytes are, on the resource's primary Representation \u2014 the same single home `yield:created` writes to.\"},\"parentResourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"language\":{\"type\":\"string\"},\"creator\":{\"$ref\":\"https://xynolog.org/protocol/Agent.json\",\"description\":\"Who made the clone \u2014 the emitter, derived at write time. A clone is never job-fulfilling. Absent on events written before derivation existed, whose emitter was their only party.\"},\"wasAttributedTo\":{\"$ref\":\"https://xynolog.org/protocol/OneOrMoreAgents.json\",\"description\":\"PROV-O wasAttributedTo, derived at write time: the cloner alone. The value the resource view carries.\"}},\"required\":[\"name\",\"format\",\"contentChecksum\",\"parentResourceId\"]},\"ResourceCreatedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceCreatedPayload.json\",\"type\":\"object\",\"description\":\"Payload for yield:created domain event\",\"properties\":{\"name\":{\"type\":\"string\"},\"format\":{\"$ref\":\"https://xynolog.org/protocol/ContentFormat.json\"},\"contentChecksum\":{\"type\":\"string\",\"description\":\"SHA-256 of content\"},\"contentByteSize\":{\"type\":\"integer\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"storageUri\":{\"type\":\"string\",\"description\":\"The creating instruction's URI, recorded on the event. Append-only, so this value never changes \u2014 the LOCATION the projection serves is maintained across moves and lives on the resource's primary Representation, relocated by yield:moved. Optional: a resource may have no bytes. Working-tree URI, only file:// is supported (e.g. file://docs/overview.md).\"},\"language\":{\"type\":\"string\"},\"isDraft\":{\"type\":\"boolean\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\",\"description\":\"The job this resource was made in fulfilment of, when its create cited one. A write that cites the same job on this resource, by the one who made it, is attributed to that job's requester: the `creator` here.\"},\"generatedFrom\":{\"type\":\"object\",\"description\":\"What this resource was generated from: the resource, and the annotation on it when the generation was for one. The resource's descriptor names the resource as `wasDerivedFrom`.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"}},\"required\":[\"resourceId\"]},\"generationPrompt\":{\"type\":\"string\"},\"generator\":{\"$ref\":\"https://xynolog.org/protocol/OneOrMoreAgents.json\"},\"creator\":{\"$ref\":\"https://xynolog.org/protocol/Agent.json\",\"description\":\"Who requested this resource \u2014 derived by the knowledge base at write time, never sent by the emitter. For a resource created in fulfilment of a job, the requester recorded on that job's job:assigned; otherwise the emitter itself. Absent on events written before derivation existed, whose emitter was their only party.\"},\"wasAttributedTo\":{\"$ref\":\"https://xynolog.org/protocol/OneOrMoreAgents.json\",\"description\":\"PROV-O wasAttributedTo, derived at write time from `creator` and the executor: both parties when they differ, one when they are the same. The value the resource view carries; readers do not re-derive it.\"}},\"required\":[\"name\",\"format\",\"contentChecksum\"]},\"ResourceDescriptor\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceDescriptor.json\",\"type\":\"object\",\"description\":\"Metadata about a resource (1:1 with its URI). JSON-LD subject is @id. Link to concrete bytes via representations.\",\"required\":[\"@context\",\"@id\",\"name\",\"representations\"],\"additionalProperties\":true,\"properties\":{\"@context\":{\"description\":\"JSON-LD context; URI, object, or array of these.\",\"oneOf\":[{\"type\":\"string\",\"format\":\"uri\"},{\"type\":\"object\",\"additionalProperties\":true},{\"type\":\"array\",\"items\":{\"oneOf\":[{\"type\":\"string\",\"format\":\"uri\"},{\"type\":\"object\",\"additionalProperties\":true}]}}]},\"@id\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The id of the resource being described.\"},\"@type\":{\"$ref\":\"https://xynolog.org/protocol/OneOrMoreStrings.json\",\"description\":\"Type(s) of the resource (IRIs/CURIEs via @context).\"},\"name\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"identifier\":{\"description\":\"Persistent identifiers (e.g., DOI, URN).\",\"oneOf\":[{\"type\":\"string\"},{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"minItems\":1},{\"type\":\"object\",\"properties\":{\"@id\":{\"type\":\"string\",\"format\":\"uri\"},\"value\":{\"type\":\"string\"},\"scheme\":{\"type\":\"string\"}},\"additionalProperties\":true}]},\"about\":{\"$ref\":\"https://xynolog.org/protocol/OneOrMoreStrings.json\",\"description\":\"Topics (IRIs or strings).\"},\"sameAs\":{\"description\":\"Equivalent/authoritative references.\",\"type\":\"array\",\"items\":{\"type\":\"string\",\"format\":\"uri\"}},\"isPartOf\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"format\":\"uri\"}},\"hasPart\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"format\":\"uri\"}},\"license\":{\"type\":\"string\",\"format\":\"uri\"},\"version\":{\"type\":\"string\"},\"dateCreated\":{\"type\":\"string\",\"format\":\"date-time\"},\"dateModified\":{\"type\":\"string\",\"format\":\"date-time\"},\"wasDerivedFrom\":{\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}}],\"description\":\"W3C PROV: the resource, or resources, this one was derived from, each by its id\"},\"wasAttributedTo\":{\"$ref\":\"https://xynolog.org/protocol/OneOrMoreAgents.json\",\"description\":\"W3C PROV \u2014 every party responsible for this resource, derived by the knowledge base at creation from verified identities: `[requester, generator]` for a resource a job produced, collapsed to the one agent when the requester produced it. Never accepted from an emitter.\"},\"generator\":{\"$ref\":\"https://xynolog.org/protocol/OneOrMoreAgents.json\",\"description\":\"Software peer that produced this resource (W3C Web Annotation model). Its identity is the verified emitter of the create; the parameters are the producer's to state.\"},\"conformsTo\":{\"$ref\":\"https://xynolog.org/protocol/OneOrMoreUris.json\",\"description\":\"Profile/shape URI this resource description conforms to.\"},\"availableFormats\":{\"description\":\"Convenience set summarizing media types across representations.\",\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"representations\":{\"description\":\"Managed or referenced byte-level renditions of this resource.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/Representation.json\"},{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/Representation.json\"}}]},\"archived\":{\"type\":\"boolean\",\"description\":\"Application-specific: Whether this resource is archived\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Application-specific: Entity types for this resource\"},\"isDraft\":{\"type\":\"boolean\",\"description\":\"Application-specific: Whether this resource is a draft\"},\"sourceAnnotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Application-specific: ID of annotation that triggered generation\"},\"sourceResourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Application-specific: ID of source resource for clones/derivatives\"},\"originatedFrom\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"Original URI from a source knowledge base when this resource was imported\"}}},\"ResourceMovedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceMovedPayload.json\",\"type\":\"object\",\"description\":\"Payload for yield:moved domain event\",\"properties\":{\"fromUri\":{\"type\":\"string\",\"description\":\"Previous file:// URI\"},\"toUri\":{\"type\":\"string\",\"description\":\"New file:// URI\"}},\"required\":[\"fromUri\",\"toUri\"]},\"ResourceUnarchivedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceUnarchivedPayload.json\",\"type\":\"object\",\"description\":\"Payload for mark:unarchived domain event (empty payload)\"},\"ResourceUpdatedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceUpdatedPayload.json\",\"type\":\"object\",\"description\":\"Payload for yield:updated domain event\",\"properties\":{\"contentChecksum\":{\"type\":\"string\",\"description\":\"SHA-256 of new content\"},\"contentByteSize\":{\"type\":\"integer\"}},\"required\":[\"contentChecksum\"]},\"ScoredResource\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ScoredResource.json\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"},{\"type\":\"object\",\"properties\":{\"score\":{\"type\":\"number\",\"description\":\"Relevance score assigned by the matcher; higher is a better candidate.\"},\"matchReason\":{\"type\":\"string\",\"description\":\"Human-readable reason for the match.\"}}}],\"description\":\"A resource returned by a search, carrying its relevance score and the reason it matched.\"},\"SemanticMatch\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SemanticMatch.json\",\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\",\"description\":\"The chunk text that matched\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Source resource ID\"},\"resourceName\":{\"type\":\"string\",\"description\":\"The source resource's display name, resolved from its view at gather time. Required: a match card must name its source, and corpus matches routinely come from outside the graph neighborhood, so there is no node to borrow a name from. A match whose source no longer resolves to a view is dropped by the producer rather than served nameless.\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"Source annotation ID, if the match is from an annotation\"},\"score\":{\"type\":\"number\",\"description\":\"Cosine similarity score (0-1)\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity types on the matched passage\"},\"machineRead\":{\"type\":\"boolean\",\"description\":\"True when this passage's text was recognized from pixels (OCR of a scanned page) rather than read from the document. Absent means read directly \u2014 the common case \u2014 so the flag is only present where it changes how the text should be trusted. It travels with the passage because a consumer receives the chunk with no document attached and cannot recompute how the text was obtained.\"}},\"required\":[\"text\",\"resourceId\",\"resourceName\",\"score\"]},\"SessionJoinedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SessionJoinedEvent.json\",\"type\":\"object\",\"description\":\"A participant opened a live connection to this KB \u2014 an SSE stream on /bus/subscribe. Presence is CONNECTION lifecycle, not login: a token can be minted and sit unused, so what this reports is that someone is WATCHING. One person with two tabs produces two of these, which is why connectionId is required \u2014 the DID alone cannot tell two connections apart, and a consumer that counts DIDs will undercount viewers.\",\"properties\":{\"participant\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"DID of the authenticated principal on that connection. A person or a software agent \u2014 the bus does not distinguish.\"},\"connectionId\":{\"type\":\"string\",\"description\":\"Identifies this connection for its lifetime. The matching session:left carries the same value.\"}},\"required\":[\"participant\",\"connectionId\"]},\"SessionLeftEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SessionLeftEvent.json\",\"type\":\"object\",\"description\":\"A participant's live connection to this KB ended \u2014 the SSE stream aborted. Carries the same connectionId as the session:joined that opened it, so a consumer tracking who is present can retire the right connection rather than assuming one per participant.\",\"properties\":{\"participant\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"DID of the authenticated principal on that connection.\"},\"connectionId\":{\"type\":\"string\",\"description\":\"The connectionId announced by the matching session:joined.\"}},\"required\":[\"participant\",\"connectionId\"]},\"SettingsHoverDelayChangedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SettingsHoverDelayChangedEvent.json\",\"type\":\"object\",\"description\":\"Emitted when the hover delay setting changes\",\"properties\":{\"hoverDelayMs\":{\"type\":\"integer\"}},\"required\":[\"hoverDelayMs\"]},\"SettingsLocaleChangedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SettingsLocaleChangedEvent.json\",\"type\":\"object\",\"description\":\"Emitted when the UI locale setting changes\",\"properties\":{\"locale\":{\"type\":\"string\"}},\"required\":[\"locale\"]},\"SettingsThemeChangedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SettingsThemeChangedEvent.json\",\"type\":\"object\",\"description\":\"Emitted when the UI theme setting changes\",\"properties\":{\"theme\":{\"type\":\"string\",\"enum\":[\"light\",\"dark\",\"system\"]}},\"required\":[\"theme\"]},\"SpecificResource\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SpecificResource.json\",\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"SpecificResource\"]},\"source\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The id of the resource this body leads to\"},\"purpose\":{\"$ref\":\"https://xynolog.org/protocol/BodyPurpose.json\",\"description\":\"Why this body is included\"}},\"required\":[\"type\",\"source\"]},\"StatusResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/StatusResponse.json\",\"type\":\"object\",\"properties\":{\"status\":{\"type\":\"string\"},\"version\":{\"type\":\"string\"},\"features\":{\"type\":\"object\",\"properties\":{\"semanticContent\":{\"type\":\"string\"},\"collaboration\":{\"type\":\"string\"}},\"required\":[\"semanticContent\",\"collaboration\"]},\"message\":{\"type\":\"string\"},\"authenticatedAs\":{\"type\":\"string\"}},\"required\":[\"status\",\"version\",\"features\",\"message\"]},\"StoredEventResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/StoredEventResponse.json\",\"type\":\"object\",\"description\":\"A persisted domain event with metadata. Flat shape \u2014 event fields and metadata are peers.\",\"properties\":{\"id\":{\"type\":\"string\",\"description\":\"Unique event ID (UUID)\"},\"type\":{\"type\":\"string\",\"description\":\"Event type (flow verb name, e.g. mark:added)\"},\"timestamp\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"When the event occurred\"},\"userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"DID of the user who triggered the event\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Resource this event affects (absent for system events)\"},\"version\":{\"type\":\"integer\",\"description\":\"Event schema version\"},\"payload\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"Event-type-specific payload\"},\"metadata\":{\"$ref\":\"https://xynolog.org/protocol/EventMetadata.json\"}},\"required\":[\"id\",\"type\",\"timestamp\",\"userId\",\"version\",\"payload\",\"metadata\"]},\"SupportedMediaType\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SupportedMediaType.json\",\"type\":\"string\",\"description\":\"Base MIME types (no parameters) admitted by Xynolog. Membership is the create/yield gate \u2014 every member is storable, nameable, and uploadable. What more the system can do with a type (render, annotate, extract text, author) is curated per type in @xynolog/core's media-type registry, which is keyed by this enum.\",\"enum\":[\"text/plain\",\"text/markdown\",\"text/html\",\"text/css\",\"text/csv\",\"text/xml\",\"application/json\",\"application/xml\",\"application/yaml\",\"application/x-yaml\",\"application/pdf\",\"application/msword\",\"application/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"application/vnd.ms-excel\",\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\",\"application/vnd.ms-powerpoint\",\"application/vnd.openxmlformats-officedocument.presentationml.presentation\",\"application/zip\",\"application/gzip\",\"application/x-tar\",\"application/x-7z-compressed\",\"application/octet-stream\",\"application/wasm\",\"image/png\",\"image/jpeg\",\"image/gif\",\"image/webp\",\"image/svg+xml\",\"image/bmp\",\"image/tiff\",\"image/x-icon\",\"video/mp4\",\"video/mpeg\",\"video/webm\",\"video/ogg\",\"video/quicktime\",\"video/x-msvideo\",\"audio/mpeg\",\"audio/wav\",\"audio/ogg\",\"audio/webm\",\"audio/aac\",\"audio/flac\",\"text/javascript\",\"application/javascript\",\"text/x-typescript\",\"application/typescript\",\"text/x-python\",\"text/x-java\",\"text/x-c\",\"text/x-c++\",\"text/x-csharp\",\"text/x-go\",\"text/x-rust\",\"text/x-ruby\",\"text/x-php\",\"text/x-swift\",\"text/x-kotlin\",\"text/x-shell\",\"font/woff\",\"font/woff2\",\"font/ttf\",\"font/otf\"]},\"Selector\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/Selector.json\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/TextPositionSelector.json\"},{\"$ref\":\"https://xynolog.org/protocol/TextQuoteSelector.json\"},{\"$ref\":\"https://xynolog.org/protocol/SvgSelector.json\"},{\"$ref\":\"https://xynolog.org/protocol/FragmentSelector.json\"}],\"discriminator\":{\"propertyName\":\"type\",\"mapping\":{\"TextPositionSelector\":\"https://xynolog.org/protocol/TextPositionSelector.json\",\"TextQuoteSelector\":\"https://xynolog.org/protocol/TextQuoteSelector.json\",\"SvgSelector\":\"https://xynolog.org/protocol/SvgSelector.json\",\"FragmentSelector\":\"https://xynolog.org/protocol/FragmentSelector.json\"}},\"description\":\"One W3C selector: a way of finding a segment of a resource. Tell them apart by `type`, which is required on each and single-valued.\"},\"SvgSelector\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SvgSelector.json\",\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"SvgSelector\"]},\"value\":{\"type\":\"string\",\"description\":\"SVG markup defining the region (must include xmlns attribute)\"}},\"required\":[\"type\",\"value\"]},\"TagCategory\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/TagCategory.json\",\"type\":\"object\",\"description\":\"A single category within a tag schema (e.g. 'Issue' in IRAC, 'distinguished' in legal-citation-treatment). Each category carries methodology-bound semantics: a name, a description, and examples used in the LLM prompt.\",\"properties\":{\"name\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"examples\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}},\"required\":[\"name\",\"description\",\"examples\"]},\"TagSchema\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/TagSchema.json\",\"type\":\"object\",\"description\":\"A structural-analysis schema (e.g. legal-irac, scientific-imrad, argument-toulmin). Defines a methodology framework as an id, name, description, domain hint, and an ordered list of categories. KBs and their skills register schemas with the runtime registry via `frame.addTagSchema(...)` at session start.\",\"properties\":{\"id\":{\"type\":\"string\"},\"name\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"domain\":{\"type\":\"string\",\"description\":\"Free-form domain hint (e.g. 'legal', 'scientific', 'general'). Used in the LLM prompt to tune the model's analysis voice. KB authors choose.\"},\"tags\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/TagCategory.json\"}}},\"required\":[\"id\",\"name\",\"description\",\"domain\",\"tags\"]},\"TagSchemaAddedPayload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/TagSchemaAddedPayload.json\",\"type\":\"object\",\"description\":\"Payload for frame:tag-schema-added domain event (system-level, no resourceId \u2014 fan-out is global to the KB).\",\"properties\":{\"schema\":{\"$ref\":\"https://xynolog.org/protocol/TagSchema.json\"}},\"required\":[\"schema\"]},\"TextPositionSelector\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/TextPositionSelector.json\",\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"TextPositionSelector\"]},\"start\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Offset into the resource's decoded text, exactly as decoded, in Unicode code points from its start: where the selected text starts.\"},\"end\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Offset into the resource's decoded text, exactly as decoded, in Unicode code points from its start: just past where the selected text ends.\"}},\"required\":[\"type\",\"start\",\"end\"]},\"TextQuoteSelector\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/TextQuoteSelector.json\",\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"TextQuoteSelector\"]},\"exact\":{\"type\":\"string\"},\"prefix\":{\"type\":\"string\"},\"suffix\":{\"type\":\"string\"}},\"required\":[\"type\",\"exact\"]},\"TextualBody\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/TextualBody.json\",\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"TextualBody\"]},\"value\":{\"type\":\"string\",\"description\":\"The text content (e.g., entity type name)\"},\"purpose\":{\"$ref\":\"https://xynolog.org/protocol/BodyPurpose.json\",\"description\":\"Why this body is included\"},\"format\":{\"type\":\"string\",\"description\":\"MIME type (defaults to text/plain)\"},\"language\":{\"type\":\"string\",\"description\":\"BCP 47 language tag\"}},\"required\":[\"type\",\"value\"]},\"UpdateAnnotationBodyRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/UpdateAnnotationBodyRequest.json\",\"type\":\"object\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Resource ID containing the annotation (required for O(1) Layer 3 lookup)\"},\"operations\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/BodyOperation.json\"},\"minItems\":1,\"description\":\"Array of body modification operations to apply\"}},\"required\":[\"resourceId\",\"operations\"]},\"UserId\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/UserId.json\",\"type\":\"string\",\"description\":\"The identity of whoever did something, a person or a software agent alike: a DID (`did:web:<domain>:users:<subject>`, `did:web:<domain>:agents:<subject>`), with no whitespace in it. Never a name, an address, or a row in a table. What follows `did:` is not constrained further: a subject is the issuer's, percent-encoded, and that encoding leaves some punctuation as it is.\",\"pattern\":\"^did:\\\\S+$\"},\"UserResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/UserResponse.json\",\"type\":\"object\",\"description\":\"The authenticated principal, as this knowledge base names it.\\n\\nThe `did` is the identity: it is what the bus stamps on every event, what resource creation is attributed to, and what a client must compare against to recognise its own work in the data. It is the only identifier: a row id would appear nowhere else in the system and correlate with nothing.\\n\\nThe remaining fields exist to be displayed, and all of them come from the token's own claims.\",\"properties\":{\"did\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"The authenticated principal's DID: `did:web:<domain>:agents:<subject>` for an agent, whose token's `kind` claim is `agent`, and `did:web:<domain>:users:<subject>` for a person, where the subject is the issuer claim the knowledge base names its principals by (`identity.subjectClaim`).\"},\"email\":{\"type\":[\"string\",\"null\"],\"description\":\"The address the token carries, when it carries one: an agent's account need not have one.\"},\"name\":{\"type\":[\"string\",\"null\"]},\"image\":{\"type\":[\"string\",\"null\"]},\"domain\":{\"type\":\"string\",\"description\":\"The knowledge base's domain: the authority the principal is named under.\"}},\"required\":[\"did\",\"email\",\"name\",\"image\",\"domain\"]},\"SmeltRebuildAnchorsCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SmeltRebuildAnchorsCommand.json\",\"type\":\"object\",\"description\":\"Bus command to rebuild anchored-text artifacts by re-running extraction \u2014 every geometry-capable resource when resourceId is absent, one resource when present. Served by the Smelter, serialized (each unit can be a multi-second OCR pass), and never destructive: nothing is deleted first, stale entries are simply overwritten. Re-anchoring makes zero embedding calls \u2014 the vectors are already correct; only the derived map is re-made. Partial completion replies failed, with counts: a rebuild that quietly skipped resources would present exactly like a document with no text.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"When present, re-anchor only this resource; otherwise every geometry-capable resource in the catalog.\"},\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"}}},\"WeaveRebuildCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/WeaveRebuildCommand.json\",\"type\":\"object\",\"description\":\"Bus command to rebuild the graph projection from the event log \u2014 the whole graph when resourceId is absent, one resource when present. Served by the Weaver; replaces direct rebuild access, which does not survive the Weaver's container split.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"When present, rebuild only this resource; otherwise clear and rebuild the entire graph.\"},\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"}}},\"YieldCloneCreateCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldCloneCreateCommand.json\",\"type\":\"object\",\"description\":\"Bus command to create a cloned resource from a clone token. Bytes are stored by the upload path BEFORE this command is emitted, because bytes travel over HTTP and never over the bus \u2014 the command carries the storage coordinates, never content.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"token\":{\"type\":\"string\"},\"name\":{\"type\":\"string\"},\"storageUri\":{\"type\":\"string\",\"description\":\"Where the caller already wrote the clone's bytes \u2014 an instruction, not a copy of the stored fact (that lives on the primary Representation). Bytes are stored through the byte door BEFORE this command is sent, so this names an existing file. Working-tree URI, only file:// is supported.\"},\"contentChecksum\":{\"type\":\"string\"},\"byteSize\":{\"type\":\"integer\"},\"format\":{\"$ref\":\"https://xynolog.org/protocol/ContentFormat.json\"},\"archiveOriginal\":{\"type\":\"boolean\"}},\"required\":[\"token\",\"name\",\"storageUri\",\"contentChecksum\",\"byteSize\",\"format\"]},\"YieldCloneCreated\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldCloneCreated.json\",\"type\":\"object\",\"description\":\"Success response after creating a cloned resource.\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/YieldedResource.json\"}},\"required\":[\"response\"]},\"YieldCloneResourceRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldCloneResourceRequest.json\",\"type\":\"object\",\"description\":\"Bus command to request cloning a resource using a clone token.\",\"properties\":{\"token\":{\"type\":\"string\"}},\"required\":[\"token\"]},\"YieldCloneTokenRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldCloneTokenRequest.json\",\"type\":\"object\",\"description\":\"Bus command to request a clone token for a resource.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"resourceId\"]},\"YieldCreateCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldCreateCommand.json\",\"type\":\"object\",\"description\":\"Bus command to create a yielded resource in the knowledge base.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"_roles\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The emitter's capabilities (the token's `roles`), injected by the /bus/emit gateway. Clients do not set this. An emitter carrying the worker role must cite the job this resource fulfils in `jobId`; the Stower refuses the create otherwise.\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\",\"description\":\"The job this resource fulfils. Required when the emitter carries the worker role; absent for self-initiated work (a person, or an agent acting on its own). The knowledge base derives who requested this resource from the cited job's own events \u2014 the emitter never says who the work was for.\"},\"name\":{\"type\":\"string\"},\"storageUri\":{\"type\":\"string\",\"description\":\"The caller's instruction for WHERE the bytes are \u2014 not a copy of the stored fact. The stored location lives on the resource's primary Representation (`Representation.storageUri`), which is its single home; this field is the message that puts it there. Working-tree URI, only file:// is supported (e.g. file://docs/overview.md).\"},\"contentChecksum\":{\"type\":\"string\"},\"byteSize\":{\"type\":\"integer\"},\"format\":{\"$ref\":\"https://xynolog.org/protocol/ContentFormat.json\"},\"language\":{\"type\":\"string\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"isDraft\":{\"type\":\"boolean\"},\"generatedFrom\":{\"type\":\"object\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\"}}},\"generationPrompt\":{\"type\":\"string\"},\"generator\":{\"$ref\":\"https://xynolog.org/protocol/OneOrMoreAgents.json\",\"description\":\"The Software peer that produced the content, when software did. Its identity must be the emitter's own \u2014 the knowledge base refuses a generator naming anyone else, and supplies it from the verified emitter when omitted. `creator` and `wasAttributedTo` are never sent; the knowledge base derives them from the emitter and the cited job.\"}},\"required\":[\"name\",\"storageUri\",\"contentChecksum\",\"byteSize\",\"format\"]},\"YieldClonePersistCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldClonePersistCommand.json\",\"type\":\"object\",\"description\":\"Command: stow an already-uploaded clone's bytes and append `yield:cloned`.\\n\\nThe INNER half of the clone flow. `yield:clone-create` reaches the CloneTokenManager, which alone can validate the token and read the source's entity types; it then emits this so the Stower \u2014 the only appendEvent caller \u2014 writes the domain event.\\n\\nDistinct from `yield:create` because a clone is a distinct operation, not a creation with an extra field. It REQUIRES a parent, and that requirement is what a separate command expresses: an optional `parentResourceId` on the create command could not say that a clone without a parent is not a clone. `ResourceClonedPayload` requires it for the same reason.\\n\\nGenerated resources are NOT clones: they carry provenance in `generatedFrom` and stay on `yield:create`.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Injected by the gateway from the authenticated principal; never supplied by a wire caller.\"},\"name\":{\"type\":\"string\"},\"storageUri\":{\"type\":\"string\",\"description\":\"The caller's instruction for WHERE the bytes are \u2014 the uploader wrote them before emitting this. The stored location lives on the clone's primary Representation, the one home of a storage URI.\"},\"contentChecksum\":{\"type\":\"string\"},\"byteSize\":{\"type\":\"integer\"},\"format\":{\"$ref\":\"https://xynolog.org/protocol/ContentFormat.json\"},\"language\":{\"type\":\"string\"},\"entityTypes\":{\"type\":\"array\",\"description\":\"Inherited from the source resource by the CloneTokenManager, which is the only party that knows the token is valid.\",\"items\":{\"type\":\"string\"}},\"parentResourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource this one is cloned FROM. Required: it is what makes this a clone rather than a creation.\"}},\"required\":[\"name\",\"storageUri\",\"contentChecksum\",\"byteSize\",\"format\",\"parentResourceId\"]},\"YieldCreateOk\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldCreateOk.json\",\"type\":\"object\",\"description\":\"Success reply after creating a yielded resource, matched to the originating command by correlationId.\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/YieldedResource.json\",\"description\":\"The created resource's identity.\"}},\"required\":[\"response\"]},\"YieldClonePersistOk\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldClonePersistOk.json\",\"type\":\"object\",\"description\":\"Success reply after cloning a resource, matched to the originating command by correlationId.\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/YieldedResource.json\",\"description\":\"The clone's identity \u2014 a new resource, distinct from its parent.\"}},\"required\":[\"response\"]},\"YieldUpdateCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldUpdateCommand.json\",\"type\":\"object\",\"description\":\"Bus command to update a yielded resource's storage content.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"storageUri\":{\"type\":\"string\",\"description\":\"The caller's instruction for WHERE the bytes are \u2014 not a copy of the stored fact. The stored location lives on the resource's primary Representation (`Representation.storageUri`), which is its single home; this field is the message that puts it there. Working-tree URI, only file:// is supported (e.g. file://docs/overview.md).\"},\"contentChecksum\":{\"type\":\"string\"},\"byteSize\":{\"type\":\"integer\"}},\"required\":[\"resourceId\",\"storageUri\",\"contentChecksum\",\"byteSize\"]},\"YieldUpdateOk\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldUpdateOk.json\",\"type\":\"object\",\"description\":\"Success reply after updating a yielded resource, matched to the originating command by correlationId.\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/YieldedResource.json\",\"description\":\"The updated resource's identity.\"}},\"required\":[\"response\"]},\"YieldedResource\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldedResource.json\",\"type\":\"object\",\"description\":\"The resource a yield command wrote, by its id.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"resourceId\"]},\"BusEventMessage\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BusEventMessage.json\",\"type\":\"object\",\"description\":\"A bus frame on the stream: `event: bus-event`, an `id:` line, and one `data:` line holding the JSON-serialised BusFrame. This schema describes the message with `data` already parsed.\",\"properties\":{\"event\":{\"type\":\"string\",\"enum\":[\"bus-event\"]},\"id\":{\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/PersistedEventId.json\"},{\"$ref\":\"https://xynolog.org/protocol/ReplyEventId.json\"},{\"$ref\":\"https://xynolog.org/protocol/EphemeralEventId.json\"}]},\"data\":{\"$ref\":\"https://xynolog.org/protocol/BusFrame.json\"}},\"required\":[\"event\",\"id\",\"data\"],\"additionalProperties\":false},\"BusFrame\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BusFrame.json\",\"type\":\"object\",\"description\":\"One frame of the bus stream, as the `data` line of a `bus-event` message carries it (JSON-serialised on one line). `payload` is the channel's payload as its registry entry declares it. A frame on a scoped subscription carries the scope it was published on; a correlated reply carries the `correlationId` of the request it answers.\",\"properties\":{\"channel\":{\"type\":\"string\",\"minLength\":1,\"description\":\"A channel of the bus registry (specs/src/bus/registry.json).\"},\"correlationId\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The request this frame answers. Present on correlated replies; absent otherwise.\"},\"payload\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"The channel's payload. A replayed persisted event is the stored event itself, whose `metadata.sequenceNumber` the message id carries.\"},\"scope\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource scope the frame was published on. Present exactly when it arrived through a `scoped` entry of the subscription.\"}},\"required\":[\"channel\",\"payload\"],\"additionalProperties\":false},\"BusPingMessage\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BusPingMessage.json\",\"type\":\"object\",\"description\":\"The heartbeat: `event: ping` with an empty `data:` line. The first is written once the stream has caught up (after any replay), then one every `x-xynolog-limits.heartbeatSeconds`. It carries no id, so it never disturbs a client's last-seen ids.\",\"properties\":{\"event\":{\"type\":\"string\",\"enum\":[\"ping\"]},\"data\":{\"type\":\"string\",\"maxLength\":0}},\"required\":[\"event\",\"data\"],\"additionalProperties\":false},\"BusResumeGap\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BusResumeGap.json\",\"type\":\"object\",\"description\":\"The payload of `bus:resume-gap`: a scope's `lastEventId` could not be honoured, so the client cannot trust that it has every persisted event of that scope and must refetch what it caches for it. Written by the gateway, never by a participant.\",\"properties\":{\"scope\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The scope of the subscription entry whose watermark failed.\"},\"lastSeenId\":{\"type\":\"string\",\"description\":\"The watermark the entry carried.\"},\"reason\":{\"type\":\"string\",\"enum\":[\"unparseable-last-event-id\",\"scope-mismatch\",\"retention-exceeded\",\"query-error\"],\"description\":\"`unparseable-last-event-id`: the watermark is not a PersistedEventId. `scope-mismatch`: it names another scope. `retention-exceeded`: the record no longer holds the events after it (what it still holds is replayed first). `query-error`: the record could not be read.\"}},\"required\":[\"scope\",\"lastSeenId\",\"reason\"],\"additionalProperties\":false},\"BusStreamMessage\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BusStreamMessage.json\",\"description\":\"Every message the bus stream carries. A client ignores an `event` it does not know; the gateway writes no other.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/BusEventMessage.json\"},{\"$ref\":\"https://xynolog.org/protocol/BusPingMessage.json\"}]},\"EphemeralEventId\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/EphemeralEventId.json\",\"type\":\"string\",\"description\":\"`e-<publishId>` \u2014 the id of any other frame, given once when the frame is published: the same on every connection that carries it, through every replica, so a copy arriving on two connections (a reconnect overlap) dedups. Never a resumption watermark.\",\"pattern\":\"^e-[^:]+$\"},\"PersistedEventId\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/PersistedEventId.json\",\"type\":\"string\",\"description\":\"`p-<scope>-<sequenceNumber>` \u2014 the id of a persisted event delivered on a scoped subscription. Resumable: send it back as that scope's `lastEventId`. Stable across connections, so a client dedups by it.\",\"pattern\":\"^p-.+-[0-9]+$\"},\"ReplyEventId\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ReplyEventId.json\",\"type\":\"string\",\"description\":\"`e-<channel>:<correlationId>` \u2014 the id of a frame that carries a correlationId. Deterministic: the same reply has the same id on every connection, so a copy arriving on two connections (a reconnect overlap, or a replay of a retained reply) dedups. Never a resumption watermark.\",\"pattern\":\"^e-[^:]+:[^:]+:.+$\"},\"KbIdentity\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/KbIdentity.json\",\"type\":\"object\",\"description\":\"A knowledge base's committed identity (`project.name` and `site.domain` in its .xynolog/config.yaml), as a service's document names the knowledge base it serves. Its telemetry names it by its DID (`xynolog.kb`, specs/src/service-telemetry/telemetry.json).\",\"properties\":{\"name\":{\"type\":\"string\",\"minLength\":1,\"description\":\"Its name. The gateway publishes it as its resource metadata's `resource_name`.\"},\"domain\":{\"type\":\"string\",\"minLength\":1,\"pattern\":\"^\\\\S+$\",\"description\":\"Its did:web domain: its permanent identity, the source of the audience its tokens must carry, and the authority its people and agents are named under.\"}},\"required\":[\"name\",\"domain\"],\"additionalProperties\":false},\"ResourceUpload\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceUpload.json\",\"type\":\"object\",\"description\":\"The multipart upload that creates a resource. A client sends it to the gateway's `POST /resources`; the gateway forwards it untouched to the Archivist's `POST /resources`, which stores the bytes and records the resource. One body, two hops.\",\"properties\":{\"name\":{\"type\":\"string\",\"description\":\"Human-readable resource name\"},\"file\":{\"type\":\"string\",\"format\":\"binary\",\"description\":\"Binary content\"},\"format\":{\"type\":\"string\",\"description\":\"Media type of the content (e.g. text/plain, text/markdown, image/png)\"},\"storageUri\":{\"type\":\"string\",\"description\":\"Where the content lives (file://... for local). Required \u2014 the client names the location; the server does not derive one.\"},\"language\":{\"type\":\"string\",\"description\":\"ISO 639-1 language code\"},\"entityTypes\":{\"type\":\"string\",\"description\":\"JSON-stringified array of entity type names\"},\"sourceAnnotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"For AI-generated resources: the annotation that triggered generation. Nested into generatedFrom.annotationId on the persisted event.\"},\"sourceResourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"For AI-generated resources: the source resource the generating annotation lives on. Nested into generatedFrom.resourceId on the persisted event.\"},\"generationPrompt\":{\"type\":\"string\",\"description\":\"For AI-generated resources: the prompt that drove generation\"},\"generator\":{\"type\":\"string\",\"description\":\"For AI-generated resources: JSON-stringified Agent naming the model/worker that produced the content. Its identity must be the uploading agent's own \u2014 the knowledge base refuses a generator naming anyone else. `creator` and `wasAttributedTo` are never sent; the knowledge base derives them from the cited job.\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\",\"description\":\"The job this resource fulfils, when a worker is creating it. Forwarded onto yield:create; the knowledge base derives who requested the resource from the cited job's own events, and refuses a worker-role create that cites none. Absent for a person's own upload.\"},\"isDraft\":{\"type\":\"string\",\"description\":\"'true' or 'false' \u2014 whether the resource is a draft\"},\"cloneToken\":{\"type\":\"string\",\"description\":\"A clone token from `yield:clone-token-requested`. With it, the resource is created as a clone of the token's source, inheriting its entity types; `language`, `entityTypes` and the generation fields are then not read.\"},\"archiveOriginal\":{\"type\":\"string\",\"description\":\"With `cloneToken`: 'true' archives the source once the clone exists.\"}},\"required\":[\"name\",\"file\",\"format\",\"storageUri\"]},\"LimitRefusal\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/LimitRefusal.json\",\"description\":\"An ErrorResponse that names, in `code`, the limit the request met.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/ErrorResponse.json\"},{\"type\":\"object\",\"required\":[\"code\"],\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"streams\",\"emit-rate\",\"unanswered-requests\",\"capacity\",\"refusal-rate\"],\"description\":\"`streams`: the principal already holds as many streams as its coefficient of `x-xynolog-limits.streamsPerPrincipal` allows. `emit-rate`: the principal's emits have used its bucket, whose rate and burst are its coefficient of `x-xynolog-limits.emitsPerPrincipal`, per gateway process. `unanswered-requests`: the client already awaits as many replies as `BusSubscribeRequest.pendingReplies` may name. `capacity`: the gateway holds as many queued bytes as it can. `refusal-rate`: the request's credential was refused, and the requests its holder has had refused have used their allowance; it answers only a request whose token has already failed verification, so it says what a 401 says, and a client that can renew its token renews it and sends the request again rather than waiting (contract/TRANSPORT-CONTRACT.md \u00A7 A refused credential).\"}}}]},\"JobMetadata\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobMetadata.json\",\"type\":\"object\",\"description\":\"What the dispatcher records about a job beside its parameters. `completedUnits` and `unitCursors` appear once a worker has checkpointed. `retryCount` counts the times the queue has put the job back to pending after a failure it classes as transient.\",\"properties\":{\"id\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\",\"description\":\"The job's id: `job-` followed by a version 4 UUID written as 32 lowercase hex digits, without dashes.\"},\"type\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"The DID of the principal whose `job:create` created the job.\"},\"created\":{\"type\":\"string\",\"description\":\"When the job was created, as an ISO 8601 timestamp.\"},\"retryCount\":{\"type\":\"integer\",\"minimum\":0},\"maxRetries\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many transient failures the queue retries: 0 for generation, whose re-run produces different content; 1 for every other type.\"},\"completedUnits\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The units a worker has finished, merged across checkpoints and failures as a set.\"},\"unitCursors\":{\"type\":\"object\",\"additionalProperties\":{\"$ref\":\"https://xynolog.org/protocol/UnitCursor.json\"},\"description\":\"The furthest each unit begun got, keyed by unit, with what it had counted there. A finished unit keeps its cursor: where it ended, and its final counts.\"}},\"required\":[\"id\",\"type\",\"userId\",\"created\",\"retryCount\",\"maxRetries\"],\"additionalProperties\":false},\"JobParams\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobParams.json\",\"type\":\"object\",\"description\":\"A job's parameters as the Dispatcher holds them: the `params` of its `job:create`, and what the Dispatcher adds. It adds `resourceId`, the resource the job is about: a `mark` job's own, and for a `yield` job the one its context focuses on. For a tagging job it adds `schema`, the tag schema its `schemaId` names, so that whoever holds the job needs no registry. Nothing the caller sent is changed or removed.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"schema\":{\"$ref\":\"https://xynolog.org/protocol/TagSchema.json\",\"description\":\"The tag schema a tagging job's `schemaId` names, as the knowledge base registered it when the job was created. On a tagging job, and on no other.\"}},\"required\":[\"resourceId\"],\"additionalProperties\":true},\"MarkJobParams\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkJobParams.json\",\"description\":\"The parameters of a `mark` job, told apart by `motivation`. Each motivation takes its own parameters and no others: a parameter a job does not take is refused where the job is created.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/HighlightingJobParams.json\"},{\"$ref\":\"https://xynolog.org/protocol/CommentingJobParams.json\"},{\"$ref\":\"https://xynolog.org/protocol/AssessingJobParams.json\"},{\"$ref\":\"https://xynolog.org/protocol/LinkingJobParams.json\"},{\"$ref\":\"https://xynolog.org/protocol/TaggingJobParams.json\"}],\"discriminator\":{\"propertyName\":\"motivation\",\"mapping\":{\"highlighting\":\"https://xynolog.org/protocol/HighlightingJobParams.json\",\"commenting\":\"https://xynolog.org/protocol/CommentingJobParams.json\",\"assessing\":\"https://xynolog.org/protocol/AssessingJobParams.json\",\"linking\":\"https://xynolog.org/protocol/LinkingJobParams.json\",\"tagging\":\"https://xynolog.org/protocol/TaggingJobParams.json\"}}},\"HighlightingJobParams\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/HighlightingJobParams.json\",\"type\":\"object\",\"description\":\"What a highlighting job takes: passages of the resource worth a reader's attention are marked, with no text of the job's own.\",\"properties\":{\"motivation\":{\"type\":\"string\",\"enum\":[\"highlighting\"]},\"instructions\":{\"type\":\"string\",\"description\":\"What to look for, in the caller's words. Added to the prompt.\"},\"density\":{\"type\":\"number\",\"description\":\"How many annotations to aim for per 2000 words of the resource.\"},\"sourceLanguage\":{\"type\":\"string\",\"description\":\"The language of the resource being read. BCP 47.\"}},\"required\":[\"motivation\"],\"additionalProperties\":false},\"CommentingJobParams\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/CommentingJobParams.json\",\"type\":\"object\",\"description\":\"What a commenting job takes: passages of the resource are marked, each with a comment the model writes.\",\"properties\":{\"motivation\":{\"type\":\"string\",\"enum\":[\"commenting\"]},\"instructions\":{\"type\":\"string\",\"description\":\"What to look for, in the caller's words. Added to the prompt.\"},\"tone\":{\"type\":\"string\",\"enum\":[\"scholarly\",\"explanatory\",\"conversational\",\"technical\"],\"description\":\"The voice the comments are written in.\"},\"density\":{\"type\":\"number\",\"description\":\"How many annotations to aim for per 2000 words of the resource.\"},\"language\":{\"type\":\"string\",\"description\":\"The language the annotations' own text is written in. BCP 47.\"},\"sourceLanguage\":{\"type\":\"string\",\"description\":\"The language of the resource being read. BCP 47.\"}},\"required\":[\"motivation\"],\"additionalProperties\":false},\"AssessingJobParams\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AssessingJobParams.json\",\"type\":\"object\",\"description\":\"What an assessing job takes: passages of the resource are marked, each with an assessment the model writes.\",\"properties\":{\"motivation\":{\"type\":\"string\",\"enum\":[\"assessing\"]},\"instructions\":{\"type\":\"string\",\"description\":\"What to look for, in the caller's words. Added to the prompt.\"},\"tone\":{\"type\":\"string\",\"enum\":[\"analytical\",\"critical\",\"balanced\",\"constructive\"],\"description\":\"The stance the assessments are written from.\"},\"density\":{\"type\":\"number\",\"description\":\"How many annotations to aim for per 2000 words of the resource.\"},\"language\":{\"type\":\"string\",\"description\":\"The language the annotations' own text is written in. BCP 47.\"},\"sourceLanguage\":{\"type\":\"string\",\"description\":\"The language of the resource being read. BCP 47.\"}},\"required\":[\"motivation\"],\"additionalProperties\":false},\"LinkingJobParams\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/LinkingJobParams.json\",\"type\":\"object\",\"description\":\"What a linking job takes: mentions of the named entity types are marked as references, each unresolved until it is bound to a resource.\",\"properties\":{\"motivation\":{\"type\":\"string\",\"enum\":[\"linking\"]},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"minItems\":1,\"description\":\"The entity types to find mentions of. Each is one the knowledge base registers.\"},\"includeDescriptiveReferences\":{\"type\":\"boolean\",\"description\":\"Whether a description that stands for an entity (\\\"the wily hero\\\") counts as a mention of it, beside its name.\"},\"language\":{\"type\":\"string\",\"description\":\"The language the annotations' own text is written in. BCP 47.\"},\"sourceLanguage\":{\"type\":\"string\",\"description\":\"The language of the resource being read. BCP 47.\"}},\"required\":[\"motivation\",\"entityTypes\"],\"additionalProperties\":false},\"TaggingJobParams\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/TaggingJobParams.json\",\"type\":\"object\",\"description\":\"What a tagging job takes: passages of the resource are marked with categories of one tag schema.\",\"properties\":{\"motivation\":{\"type\":\"string\",\"enum\":[\"tagging\"]},\"schemaId\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The tag schema to tag by. It is one the knowledge base registers.\"},\"categories\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"minItems\":1,\"description\":\"The categories of that schema to tag with.\"},\"language\":{\"type\":\"string\",\"description\":\"The language the annotations' own text is written in. BCP 47.\"},\"sourceLanguage\":{\"type\":\"string\",\"description\":\"The language of the resource being read. BCP 47.\"}},\"required\":[\"motivation\",\"schemaId\",\"categories\"],\"additionalProperties\":false},\"GenerationJobRequest\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GenerationJobRequest.json\",\"type\":\"object\",\"description\":\"What a `yield` job is asked to make: every parameter of GenerationJobParams but its `context`, the input the resource is made from. It is what an announcement of the job carries.\",\"properties\":{\"title\":{\"type\":\"string\",\"description\":\"Title of the generated resource. Not empty: the gateway refuses a `job:create` whose title is.\",\"minLength\":1},\"storageUri\":{\"type\":\"string\",\"description\":\"Storage URI for the generated resource's content \u2014 AUTHORITATIVE: the worker writes exactly here and never derives a location from the title. Not empty, and there is no fallback: the gateway refuses a `job:create` whose storageUri is.\",\"minLength\":1},\"prompt\":{\"type\":\"string\",\"description\":\"Refining instruction, composed with `task` (task = what, prompt = how).\"},\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Entity-type tags to stamp on the synthesized resource. Used both as a prompt bias for the generation worker and as the `entityTypes` set on the resulting resource.\"},\"language\":{\"type\":\"string\",\"description\":\"Annotation/resource body locale \u2014 language the generated resource is written in (typically the user's UI locale). BCP-47.\"},\"sourceLanguage\":{\"type\":\"string\",\"description\":\"Source-resource locale \u2014 language of the resource being referenced, used in the prompt so the LLM understands embedded source-context snippets when source \u2260 target language. BCP-47.\"},\"temperature\":{\"type\":\"number\",\"description\":\"Sampling temperature forwarded to the model.\"},\"maxTokens\":{\"type\":\"number\",\"description\":\"Output token budget forwarded to the model. Length never determines structure.\"},\"outputMediaType\":{\"$ref\":\"https://xynolog.org/protocol/SupportedMediaType.json\",\"description\":\"Requested media type of the generated resource's content. Default `text/markdown` at the worker, which validates it against its supported output set and FAILS the job for anything it can't write \u2014 not a silent fallback.\"},\"task\":{\"type\":\"string\",\"description\":\"What the model is asked to produce \u2014 the prompt's framing verb. Canonical values ('resource', 'answer', 'summary') map to the worker's tested framings; any other string is used VERBATIM as the framing instruction (loud degrade: the worker warns, never silently falls back). Unset \u21D2 'resource' (article framing).\"},\"structure\":{\"type\":\"string\",\"description\":\"How the output is internally segmented \u2014 shape for text-bearing media, subordinate to `outputMediaType` (never its peer). Canonical values: 'prose' (flowing paragraphs), 'sections' (titled sections + title), 'chat' (speaker-labeled turns); any other string becomes a freeform \\\"organize as: \u2026\\\" directive (loud degrade). Unset \u21D2 NO structure directive at all \u2014 the task framing and the model determine shape.\"},\"cite\":{\"type\":\"boolean\",\"description\":\"Ask the model to cite its sources, by the ids the gathered context labels its passages with. The model wraps the words a source supports as `[[<id>: <claim>]]`, the ids of several sources separated by commas; a bare `[[<id>]]` is replaced by the source's name. The worker checks every id against the gathered context (an id it did not show is dropped, with a warning), takes every token out of the stored content, and mints a W3C linking annotation on the new resource over exactly the words each token cites.\"}},\"required\":[\"title\",\"storageUri\"]},\"MarkJobCreateCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkJobCreateCommand.json\",\"type\":\"object\",\"description\":\"Create a `mark` job: annotate one resource for one motivation.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"The emitter's verified DID, injected by the gateway. Clients do not set this.\"},\"_roles\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The emitter's roles, injected by the gateway when it has any. Clients do not set this.\"},\"jobType\":{\"type\":\"string\",\"enum\":[\"mark\"]},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource to annotate.\"},\"params\":{\"$ref\":\"https://xynolog.org/protocol/MarkJobParams.json\"}},\"required\":[\"jobType\",\"resourceId\",\"params\"],\"additionalProperties\":false},\"YieldJobCreateCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldJobCreateCommand.json\",\"type\":\"object\",\"description\":\"Create a `yield` job: make a resource from a gathered context. It names no resource of its own: the job is about the resource its context focuses on, which the Dispatcher reads from `params.context.focus`.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"The emitter's verified DID, injected by the gateway. Clients do not set this.\"},\"_roles\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The emitter's roles, injected by the gateway when it has any. Clients do not set this.\"},\"jobType\":{\"type\":\"string\",\"enum\":[\"yield\"]},\"params\":{\"$ref\":\"https://xynolog.org/protocol/GenerationJobParams.json\"}},\"required\":[\"jobType\",\"params\"],\"additionalProperties\":false},\"MarkJobQueuedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkJobQueuedEvent.json\",\"type\":\"object\",\"description\":\"A pending `mark` job, announced with its parameters as it was created.\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"type\":\"string\",\"enum\":[\"mark\"]},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource the job is about.\"},\"userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"The DID of the principal whose `job:create` created the job.\"},\"params\":{\"$ref\":\"https://xynolog.org/protocol/MarkJobParams.json\"}},\"required\":[\"jobId\",\"jobType\",\"resourceId\",\"userId\",\"params\"]},\"YieldJobQueuedEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldJobQueuedEvent.json\",\"type\":\"object\",\"description\":\"A pending `yield` job, announced with what it is asked to make and without its `context`.\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"type\":\"string\",\"enum\":[\"yield\"]},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource the job is about.\"},\"userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"The DID of the principal whose `job:create` created the job.\"},\"params\":{\"$ref\":\"https://xynolog.org/protocol/GenerationJobRequest.json\"}},\"required\":[\"jobId\",\"jobType\",\"resourceId\",\"userId\",\"params\"]},\"MarkJobResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkJobResult.json\",\"description\":\"What a `mark` job reports when it concludes without failing: its counts, or a decline. Neither names its kind: a decline is the one with `declined`.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/MarkJobDone.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobDeclined.json\"}]},\"YieldJobResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldJobResult.json\",\"description\":\"What a `yield` job reports when it concludes without failing: the resource it made, or a decline. Neither names its kind: a decline is the one with `declined`.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/YieldJobDone.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobDeclined.json\"}]},\"MarkJobCompleteCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkJobCompleteCommand.json\",\"type\":\"object\",\"description\":\"A `mark` job's worker says the job is complete, with what a `mark` job reports.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"type\":\"string\",\"enum\":[\"mark\"]},\"attempt\":{\"type\":\"integer\",\"description\":\"Which attempt produced this event, 1-based (a first run is 1). ALWAYS present: the queue re-runs a failed job silently, so an operator reading progress or a terminal record has no other way to tell a re-run from a first run \u2014 and provider spend, already counted in xynolog_inference_tokens_total, cannot be attributed to a repeated document without it. Stated rather than inferred from absence, because 'attempt 1' is a fact the emitter always knows.\"},\"result\":{\"$ref\":\"https://xynolog.org/protocol/MarkJobResult.json\"},\"durability\":{\"$ref\":\"https://xynolog.org/protocol/DurabilityEvidence.json\"}},\"required\":[\"resourceId\",\"jobId\",\"jobType\"]},\"YieldJobCompleteCommand\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldJobCompleteCommand.json\",\"type\":\"object\",\"description\":\"A `yield` job's worker says the job is complete, with what a `yield` job reports.\",\"properties\":{\"_userId\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"Authenticated user's DID, injected by the /bus/emit gateway. Clients do not set this.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"jobType\":{\"type\":\"string\",\"enum\":[\"yield\"]},\"attempt\":{\"type\":\"integer\",\"description\":\"Which attempt produced this event, 1-based (a first run is 1). ALWAYS present: the queue re-runs a failed job silently, so an operator reading progress or a terminal record has no other way to tell a re-run from a first run \u2014 and provider spend, already counted in xynolog_inference_tokens_total, cannot be attributed to a repeated document without it. Stated rather than inferred from absence, because 'attempt 1' is a fact the emitter always knows.\"},\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"The annotation the job's context was focused on, when it was focused on one. Lets a client route the completion to that annotation.\"},\"result\":{\"$ref\":\"https://xynolog.org/protocol/YieldJobResult.json\"},\"durability\":{\"$ref\":\"https://xynolog.org/protocol/DurabilityEvidence.json\"}},\"required\":[\"resourceId\",\"jobId\",\"jobType\"]},\"JobFilter\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobFilter.json\",\"description\":\"Some jobs, named by fields of the job description: a partial description, at the description's own paths. A job matches when every field stated here equals the job's. A `mark` filter always states its motivation.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/MarkJobFilter.json\"},{\"$ref\":\"https://xynolog.org/protocol/YieldJobFilter.json\"}],\"discriminator\":{\"propertyName\":\"jobType\",\"mapping\":{\"mark\":\"https://xynolog.org/protocol/MarkJobFilter.json\",\"yield\":\"https://xynolog.org/protocol/YieldJobFilter.json\"}}},\"MarkJobFilter\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkJobFilter.json\",\"type\":\"object\",\"description\":\"`mark` jobs of one motivation.\",\"properties\":{\"jobType\":{\"type\":\"string\",\"enum\":[\"mark\"]},\"params\":{\"type\":\"object\",\"properties\":{\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\"}},\"required\":[\"motivation\"],\"additionalProperties\":false}},\"required\":[\"jobType\",\"params\"],\"additionalProperties\":false},\"YieldJobFilter\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/YieldJobFilter.json\",\"type\":\"object\",\"description\":\"`yield` jobs.\",\"properties\":{\"jobType\":{\"type\":\"string\",\"enum\":[\"yield\"]}},\"required\":[\"jobType\"],\"additionalProperties\":false},\"JobPending\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobPending.json\",\"type\":\"object\",\"description\":\"A job waiting for a worker to claim it.\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"pending\"]},\"metadata\":{\"$ref\":\"https://xynolog.org/protocol/JobMetadata.json\"},\"params\":{\"$ref\":\"https://xynolog.org/protocol/JobParams.json\"}},\"required\":[\"status\",\"metadata\",\"params\"],\"additionalProperties\":false},\"JobStoredProgress\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobStoredProgress.json\",\"description\":\"A running job's progress as the dispatcher stores it: the last JobProgress its worker reported with `job:report-progress`, or an empty object before the first report.\",\"anyOf\":[{\"$ref\":\"https://xynolog.org/protocol/JobProgress.json\"},{\"type\":\"object\",\"maxProperties\":0}]},\"JobStoredResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobStoredResult.json\",\"description\":\"A completed job's result as the dispatcher stores it: the result its worker reported with `job:complete`, or an empty object when it reported none.\",\"anyOf\":[{\"$ref\":\"https://xynolog.org/protocol/JobResult.json\"},{\"type\":\"object\",\"maxProperties\":0}]},\"JobRunning\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobRunning.json\",\"type\":\"object\",\"description\":\"A job a worker has claimed and not yet concluded.\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"running\"]},\"metadata\":{\"$ref\":\"https://xynolog.org/protocol/JobMetadata.json\"},\"params\":{\"$ref\":\"https://xynolog.org/protocol/JobParams.json\"},\"startedAt\":{\"type\":\"string\",\"description\":\"When the claim that holds it was made, as an ISO 8601 timestamp.\"},\"progress\":{\"$ref\":\"https://xynolog.org/protocol/JobStoredProgress.json\"}},\"required\":[\"status\",\"metadata\",\"params\",\"startedAt\",\"progress\"],\"additionalProperties\":false},\"JobComplete\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobComplete.json\",\"type\":\"object\",\"description\":\"A job its worker completed.\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"complete\"]},\"metadata\":{\"$ref\":\"https://xynolog.org/protocol/JobMetadata.json\"},\"params\":{\"$ref\":\"https://xynolog.org/protocol/JobParams.json\"},\"startedAt\":{\"type\":\"string\",\"description\":\"When the claim that completed it was made.\"},\"completedAt\":{\"type\":\"string\",\"description\":\"When it completed.\"},\"result\":{\"$ref\":\"https://xynolog.org/protocol/JobStoredResult.json\"}},\"required\":[\"status\",\"metadata\",\"params\",\"startedAt\",\"completedAt\",\"result\"],\"additionalProperties\":false},\"JobFailed\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobFailed.json\",\"type\":\"object\",\"description\":\"A job that failed and will not be retried.\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"failed\"]},\"metadata\":{\"$ref\":\"https://xynolog.org/protocol/JobMetadata.json\"},\"params\":{\"$ref\":\"https://xynolog.org/protocol/JobParams.json\"},\"startedAt\":{\"type\":\"string\",\"description\":\"When the last claim was made; absent when it failed without one.\"},\"completedAt\":{\"type\":\"string\",\"description\":\"When it failed.\"},\"error\":{\"type\":\"string\",\"description\":\"The failure's message.\"},\"failureClass\":{\"$ref\":\"https://xynolog.org/protocol/FailureClass.json\"}},\"required\":[\"status\",\"metadata\",\"params\",\"completedAt\",\"error\"],\"additionalProperties\":false},\"JobCancelled\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCancelled.json\",\"type\":\"object\",\"description\":\"A job cancelled before it concluded.\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"cancelled\"]},\"metadata\":{\"$ref\":\"https://xynolog.org/protocol/JobMetadata.json\"},\"params\":{\"$ref\":\"https://xynolog.org/protocol/JobParams.json\"},\"startedAt\":{\"type\":\"string\",\"description\":\"When its claim was made; absent when it was cancelled while pending.\"},\"completedAt\":{\"type\":\"string\",\"description\":\"When it was cancelled.\"}},\"required\":[\"status\",\"metadata\",\"params\",\"completedAt\"],\"additionalProperties\":false},\"Job\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/Job.json\",\"description\":\"A job as the dispatcher holds it. Its `status` decides which timestamps and outcome fields it carries. It is what a claim returns (`job:claimed`, always `running`) and what the queue stores, inside a JobRecord.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/JobPending.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobRunning.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobComplete.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobFailed.json\"},{\"$ref\":\"https://xynolog.org/protocol/JobCancelled.json\"}],\"discriminator\":{\"propertyName\":\"status\",\"mapping\":{\"pending\":\"https://xynolog.org/protocol/JobPending.json\",\"running\":\"https://xynolog.org/protocol/JobRunning.json\",\"complete\":\"https://xynolog.org/protocol/JobComplete.json\",\"failed\":\"https://xynolog.org/protocol/JobFailed.json\",\"cancelled\":\"https://xynolog.org/protocol/JobCancelled.json\"}}},\"JobRecord\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobRecord.json\",\"type\":\"object\",\"description\":\"One job as the queue stores it: the job, and when it last showed life. The dead-worker sweep reads `lastProgressAt`: a running job whose worker has reported nothing for the configured interval is presumed dead. Where the queue keeps these records is the job storage layout, specs/src/jobs/storage.json.\",\"properties\":{\"job\":{\"$ref\":\"https://xynolog.org/protocol/Job.json\"},\"lastProgressAt\":{\"type\":\"string\",\"description\":\"When the job was created, claimed, checkpointed or last reported progress, as an ISO 8601 timestamp.\"}},\"required\":[\"job\",\"lastProgressAt\"],\"additionalProperties\":false},\"JobClaimedResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobClaimedResult.json\",\"type\":\"object\",\"description\":\"The reply to a successful `job:claim`: the claimed job, now running under the claimant.\",\"properties\":{\"response\":{\"$ref\":\"https://xynolog.org/protocol/JobRunning.json\"}},\"required\":[\"response\"],\"additionalProperties\":false},\"LogLevel\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/LogLevel.json\",\"type\":\"string\",\"enum\":[\"error\",\"warn\",\"info\",\"http\",\"debug\"],\"description\":\"How much a service logs: the least severe level it writes, from error, the most severe, to debug.\"},\"LogFormat\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/LogFormat.json\",\"type\":\"string\",\"enum\":[\"json\",\"simple\"],\"description\":\"How each log line is written to stdout (service-telemetry/log-lines.json): `json`, one JSON object per line; or `simple`, a line of words followed by any metadata as JSON.\"},\"CursorsPath\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/CursorsPath.json\",\"type\":\"string\",\"minLength\":1,\"description\":\"The file a follower of the record keeps its cursors in: for each log of the record it follows, the sequence number of the last event of it taken (contract/TRANSPORT-CONTRACT.md \u00A7 What repairs a passing frame). A file of the service's own disk, never of the knowledge base: a service that finds none starts each log as it starts one with no cursor, so losing it costs time and never correctness.\"},\"ServiceIdentity\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ServiceIdentity.json\",\"type\":\"object\",\"description\":\"The identity provider a service's account signs in at, by its issuer.\",\"properties\":{\"issuer\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The issuer URL, exactly as tokens carry it in `iss`.\"}},\"required\":[\"issuer\"],\"additionalProperties\":false},\"ServiceAddress\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ServiceAddress.json\",\"type\":\"object\",\"description\":\"The host and port a service listens at.\",\"properties\":{\"host\":{\"type\":\"string\",\"minLength\":1},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535}},\"required\":[\"host\",\"port\"],\"additionalProperties\":false},\"ResourceAnnotations\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceAnnotations.json\",\"type\":\"object\",\"description\":\"The annotations on one resource, as its materialized view holds them.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"annotations\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/Annotation.json\"},\"description\":\"Each annotation as the `mark:added` event that recorded it carried it, with the body changes recorded since applied. In the order they were first recorded.\"},\"version\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many of the resource's events the view has applied.\"},\"updatedAt\":{\"type\":\"string\",\"description\":\"The timestamp of the last event applied; the empty string before any.\"}},\"required\":[\"resourceId\",\"annotations\",\"version\",\"updatedAt\"],\"additionalProperties\":false},\"ResourceView\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceView.json\",\"type\":\"object\",\"description\":\"A resource's materialized view: the file the Archivist writes at `resources/<ab>/<cd>/<resourceId>.json` under the knowledge base's state directory, and every reader of that file reads. It is what the resource's events add up to, and is rebuilt from the event log whenever it is missing. Written as JSON indented by two spaces, by writing a sibling temporary file and renaming it onto the path, so a reader sees a whole document or none.\",\"properties\":{\"resource\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"},\"annotations\":{\"$ref\":\"https://xynolog.org/protocol/ResourceAnnotations.json\"},\"lastSequence\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The sequence number of the last event applied. A graph read that follows a write waits for the graph projection to reach it.\"}},\"required\":[\"resource\",\"annotations\",\"lastSequence\"],\"additionalProperties\":false},\"EntityTypesProjection\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/EntityTypesProjection.json\",\"type\":\"object\",\"description\":\"The knowledge base's entity-type vocabulary: the file `projections/__system__/entitytypes.json` under the state directory, the sum of the `frame:entity-type-added` events. Written as JSON indented by two spaces.\",\"properties\":{\"entityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"uniqueItems\":true,\"description\":\"Every entity type added, each once, sorted.\"}},\"required\":[\"entityTypes\"],\"additionalProperties\":false},\"TagSchemasProjection\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/TagSchemasProjection.json\",\"type\":\"object\",\"description\":\"The knowledge base's tag schemas: the file `projections/__system__/tagschemas.json` under the state directory, the sum of the `frame:tag-schema-added` events. Written as JSON indented by two spaces.\",\"properties\":{\"tagSchemas\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/TagSchema.json\"},\"description\":\"Every tag schema added, sorted by `id`. A schema added again under an `id` replaces the one held.\"}},\"required\":[\"tagSchemas\"],\"additionalProperties\":false},\"ProfilesProjection\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ProfilesProjection.json\",\"type\":\"object\",\"description\":\"What the principals of a knowledge base are called: the file `projections/__system__/profiles.json` under the state directory, the sum of the `principal:profiled` events. The Archivist writes it; the Archivist and the Librarian read it to name the principals a reply mentions. Written as JSON indented by two spaces.\",\"properties\":{\"profiles\":{\"type\":\"object\",\"description\":\"Each principal's current profile, keyed by its DID.\",\"additionalProperties\":{\"$ref\":\"https://xynolog.org/protocol/Profile.json\"}}},\"required\":[\"profiles\"],\"additionalProperties\":false},\"Profile\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/Profile.json\",\"type\":\"object\",\"description\":\"What a principal last said it is called, and when: the profile a `principal:profiled` event gives.\",\"properties\":{\"name\":{\"type\":\"string\",\"description\":\"The name the principal last gave.\"},\"since\":{\"type\":\"string\",\"description\":\"The timestamp of the event that gave it.\"}},\"required\":[\"name\",\"since\"],\"additionalProperties\":false},\"StorageUriEntry\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/StorageUriEntry.json\",\"type\":\"object\",\"description\":\"One entry of the storage-uri index: the file `projections/storage-uri/<ab>/<cd>/<sha256 of the URI, hex>.json` under the state directory. It answers which resource's content is at a place in the working tree. Written as JSON indented by two spaces, `uri` first.\",\"properties\":{\"uri\":{\"type\":\"string\",\"description\":\"The `file://` URI of a place in the working tree, relative to the knowledge base's root.\"},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"uri\",\"resourceId\"],\"additionalProperties\":false},\"ArchivistEngines\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ArchivistEngines.json\",\"type\":\"object\",\"description\":\"The engine for each job and each Librarian actor, behind `browse:engines`: a provider and a model, and no credential. It is the knowledge base's Inference document's `engines` as they stand, with no fallback, so a job or an actor absent here has no engine.\",\"properties\":{\"jobs\":{\"type\":\"object\",\"description\":\"The engine each job is done with when software does it, keyed as a job description is: by `jobType`, and for `mark` by motivation.\",\"properties\":{\"mark\":{\"type\":\"object\",\"description\":\"The engine for `mark` jobs of each motivation.\",\"properties\":{\"highlighting\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"commenting\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"assessing\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"linking\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"tagging\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"}},\"additionalProperties\":false},\"yield\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"}},\"additionalProperties\":false},\"actors\":{\"type\":\"object\",\"description\":\"The engine each Librarian actor that calls a model asks.\",\"properties\":{\"gatherer\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"matcher\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"}},\"additionalProperties\":false}},\"required\":[\"jobs\",\"actors\"],\"additionalProperties\":false},\"Engine\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/Engine.json\",\"type\":\"object\",\"description\":\"An engine: an inference provider and a model, which software does a job or an actor's step with. An engine is not a principal: the principal that used one names it on each write it produced with it (`generator`). A person who does a job uses none.\",\"properties\":{\"provider\":{\"type\":\"string\",\"enum\":[\"anthropic\",\"google\",\"llamacpp\",\"ollama\",\"openai\",\"together\",\"vllm\"],\"description\":\"The inference provider: who serves the model. `anthropic`, `google`, `openai` and `together` are those companies' own APIs. `llamacpp`, `ollama` and `vllm` are servers a deployment runs or reaches, each named for the server's software.\"},\"model\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The model identifier, as the provider names it.\"}},\"required\":[\"provider\",\"model\"],\"additionalProperties\":false},\"GatherFailed\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherFailed.json\",\"description\":\"The payload of `gather:failed`: a CommandError that names the annotation whose context could not be gathered.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/CommandError.json\"},{\"type\":\"object\",\"properties\":{\"annotationId\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationId.json\",\"description\":\"The annotation the gather was asked for.\"}},\"required\":[\"annotationId\"]}]},\"GatherResourceFailed\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatherResourceFailed.json\",\"description\":\"The payload of `gather:resource-failed`: a CommandError that names the resource whose context could not be gathered.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/CommandError.json\"},{\"type\":\"object\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource the gather was asked for.\"}},\"required\":[\"resourceId\"]}]},\"BrowseDirectoryFailed\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BrowseDirectoryFailed.json\",\"description\":\"The payload of `browse:directory-failed`: a CommandError that names the directory that could not be read.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/CommandError.json\"},{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"The path the read was asked for.\"}},\"required\":[\"path\"]}]},\"MarkDelegateTimeoutEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MarkDelegateTimeoutEvent.json\",\"type\":\"object\",\"description\":\"The payload of `mark:delegate-timeout`, a client-local signal: a delegated job went silent past its deadline, with no progress, no completion and no `job:fail`. A real job failure arrives as `job:fail` and never produces this.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource the job was delegated for.\"},\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\"}},\"required\":[\"resourceId\",\"motivation\"]},\"ResourceErrorEvent\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ResourceErrorEvent.json\",\"type\":\"object\",\"description\":\"A client-local notice that a command on a resource failed, for a UI to show: the payload of `mark:create-error`, `mark:delete-error` and `bind:body-error`. Emitted by the caller that awaited the command, which knows whose command failed on which resource. The `*-failed` wire replies are correlation plumbing and are not for this.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource the command addressed.\"},\"message\":{\"type\":\"string\",\"description\":\"Human-readable error message.\"}},\"required\":[\"resourceId\",\"message\"]},\"JobCancelResult\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobCancelResult.json\",\"type\":\"object\",\"description\":\"What a cancel did, in the `response` of `job:cancel-ok`: whether the queue acted on the job it named. A pending job is cancelled outright; a running one is left to its worker, so for it true means accepted, not stopped.\",\"properties\":{\"cancelled\":{\"type\":\"boolean\",\"description\":\"True when the queue acted on the job; false when the job is unknown or already over.\"}},\"required\":[\"cancelled\"]},\"WeaveApplied\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/WeaveApplied.json\",\"type\":\"object\",\"description\":\"The payload of `weave:applied`: the Weaver has applied a resource's events to the graph up to this sequence number. Emitted after applying an event, or a batch's last event.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource whose events were applied.\"},\"sequenceNumber\":{\"type\":\"integer\",\"description\":\"The resource-stream sequence of the last applied event.\"}},\"required\":[\"resourceId\",\"sequenceNumber\"]},\"SmeltSettled\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SmeltSettled.json\",\"type\":\"object\",\"description\":\"The payload of `smelt:settled`: the Smelter's decision for one resource's content, keyed by the checksum of the bytes it inspected. `indexed`: the content is in the vector index. `skipped`: it declined, and `reason` says why.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"The resource whose content was inspected.\"},\"contentChecksum\":{\"type\":\"string\",\"description\":\"The checksum of the bytes inspected.\"},\"outcome\":{\"type\":\"string\",\"enum\":[\"indexed\",\"skipped\"]},\"reason\":{\"type\":\"string\",\"enum\":[\"no-extractor\",\"empty\",\"no-text-layer\",\"encrypted\",\"corrupt\",\"too-large\"],\"description\":\"Why the content was skipped.\"}},\"required\":[\"resourceId\",\"contentChecksum\",\"outcome\"]},\"AnchoredTextDeclinedEntry\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchoredTextDeclinedEntry.json\",\"type\":\"object\",\"description\":\"The bytes were declined: no text is extracted from them.\",\"properties\":{\"v\":{\"type\":\"integer\",\"enum\":[3],\"description\":\"The entry format.\"},\"stamp\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The stamp the entry was derived under: the PDF reader's and the OCR engine's. A reader takes the entry only when it equals the stamp the Smelter last stated.\"},\"declined\":{\"$ref\":\"https://xynolog.org/protocol/ExtractionDeclinedReason.json\",\"description\":\"Why extraction yielded nothing, by class.\"}},\"required\":[\"v\",\"stamp\",\"declined\"],\"additionalProperties\":false},\"AnchoredTextEntries\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchoredTextEntries.json\",\"type\":\"object\",\"description\":\"The keys of the entries the anchored-text store holds under the stamp last stated: one checksum for each set of bytes whose text is stored, in no order.\",\"properties\":{\"checksums\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"pattern\":\"^[0-9a-f]{64}$\",\"description\":\"The SHA-256 of the bytes the text was derived from, as 64 lower-case hexadecimal digits: the key the entry is filed under.\"}}},\"required\":[\"checksums\"],\"additionalProperties\":false},\"AnchoredTextEntry\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchoredTextEntry.json\",\"description\":\"One entry of the anchored-text store: the file `<ab>/<cd>/<key>.json` under the store's directory, where the key is the SHA-256 of the bytes the text was extracted from, in hex. The Smelter derives it and stores it over the Archivist's HTTP surface (`AnchoredTextWrite`); the Archivist writes it, as compact JSON with `v` and `stamp` first, to a sibling temporary file renamed onto the path. The stamp the Smelter states (`AnchoredTextStamp`) is kept, followed by a newline, in the file `STAMP` at the store's root.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/AnchoredTextExtractedEntry.json\"},{\"$ref\":\"https://xynolog.org/protocol/AnchoredTextDeclinedEntry.json\"}]},\"AnchoredTextExtractedEntry\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchoredTextExtractedEntry.json\",\"type\":\"object\",\"description\":\"The text extracted from the bytes, where each word is on the page, and how it was extracted.\",\"properties\":{\"v\":{\"type\":\"integer\",\"enum\":[3],\"description\":\"The entry format.\"},\"stamp\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The stamp the entry was derived under: the PDF reader's and the OCR engine's. A reader takes the entry only when it equals the stamp the Smelter last stated.\"},\"text\":{\"type\":\"string\",\"description\":\"The extracted text.\"},\"lines\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"description\":\"One line of text: the words that share a page, a baseline and a height.\",\"properties\":{\"p\":{\"type\":\"integer\",\"description\":\"The page, counted from 1.\"},\"y\":{\"type\":\"number\",\"description\":\"The line's vertical position in PDF points, from the bottom of the page.\"},\"h\":{\"type\":\"number\",\"description\":\"The line's height in PDF points.\"},\"words\":{\"type\":\"array\",\"description\":\"Each word as `[x, width, start, end]`: its horizontal position and width in PDF points, and the offsets of its text in `text`, which are whole numbers of Unicode code points from the start of `text`.\",\"items\":{\"type\":\"array\",\"items\":{\"type\":\"number\"},\"minItems\":4,\"maxItems\":4}}},\"required\":[\"p\",\"y\",\"h\",\"words\"],\"additionalProperties\":false},\"description\":\"Where each word of `text` is, line by line, in reading order.\"},\"method\":{\"$ref\":\"https://xynolog.org/protocol/ExtractionMethod.json\",\"description\":\"How the text was extracted.\"},\"pdfClass\":{\"$ref\":\"https://xynolog.org/protocol/PdfClass.json\",\"description\":\"PDF classification, when the source was a PDF.\"},\"ocrConfidence\":{\"$ref\":\"https://xynolog.org/protocol/OcrConfidence.json\",\"description\":\"How well the engine read the pixels, when any of this text came from OCR.\"},\"unreadPages\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"description\":\"1-indexed pages this extraction could not read \u2014 present only for partially covered documents (class C).\"}},\"required\":[\"v\",\"stamp\",\"text\",\"lines\",\"method\"],\"additionalProperties\":false},\"AnchoredTextStamp\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchoredTextStamp.json\",\"type\":\"object\",\"description\":\"The stamp an anchored-text store's entries are taken under: which PDF reader and which OCR engine derived them. Its writer states it before it writes or lists an entry; an entry stored under another stamp is answered to no reader.\",\"properties\":{\"stamp\":{\"type\":\"string\",\"minLength\":1,\"pattern\":\"^\\\\S+$\",\"description\":\"The stamp: no white space, since it is held in a file of one line.\"}},\"required\":[\"stamp\"],\"additionalProperties\":false},\"AnchoredTextWrite\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchoredTextWrite.json\",\"type\":\"object\",\"description\":\"A write of an anchored-text entry for the bytes of one resource: what the Smelter derived from them, and their checksum. The Archivist files the entry under the checksum, so every resource whose bytes those are has it, and refuses the write when the resource's first representation has other bytes.\",\"properties\":{\"contentChecksum\":{\"type\":\"string\",\"pattern\":\"^[0-9a-f]{64}$\",\"description\":\"The SHA-256 of the bytes the text was derived from, as 64 lower-case hexadecimal digits: the key the entry is filed under.\"},\"entry\":{\"$ref\":\"https://xynolog.org/protocol/AnchoredTextEntry.json\"}},\"required\":[\"contentChecksum\",\"entry\"],\"additionalProperties\":false},\"ArchivistConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ArchivistConfig.json\",\"type\":\"object\",\"description\":\"Everything the Archivist reads at boot: nothing in it is defaulted by the Archivist. The launcher writes it for the Archivist it starts, from the knowledge base's stack documents, and the Archivist reads it from the path its `--config` flag names (its image passes `/etc/xynolog/archivist.json`). Started without `--config`, or with a path that names no file, the Archivist refuses to start and says which. No secret is a value here. What the knowledge base says of itself is not here either: its name, its `site.domain` and its `git.sync` are read from the committed `.xynolog/config.yaml` of the tree at `root`. The Archivist's other inputs are the environment variables specs/src/service-environment/variables.json lists for it. A document that does not validate is refused at boot, naming each failing field.\",\"properties\":{\"gatewayUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The URL the Archivist reaches the gateway at: its only route to the bus.\"},\"identity\":{\"$ref\":\"https://xynolog.org/protocol/ServiceIdentity.json\",\"description\":\"The issuer the Archivist's service account signs in at, and whose tokens it admits callers of its HTTP surface by.\"},\"root\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The knowledge base's working tree: the directory holding `.xynolog/`. The event log, the content and the committed config are under it.\"},\"stateHome\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The state volume, this knowledge base's alone: the Archivist keeps the knowledge base's views and projections in it, at its top.\"},\"anchoredTextDir\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The anchored-text store, which only the Archivist mounts: the Smelter stores each entry in it over HTTP, and the Archivist serves it.\"},\"engines\":{\"$ref\":\"https://xynolog.org/protocol/ArchivistEngines.json\"},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port the Archivist's HTTP surface answers on, `/health` included.\"},\"skipRebuild\":{\"type\":\"boolean\",\"description\":\"Whether the Archivist serves the views it finds at boot instead of rebuilding them from the event log first.\"},\"staging\":{\"type\":\"object\",\"description\":\"The bounds on how far the staging driver may run behind the working tree, in milliseconds. A knowledge base that does not sync git stages nothing, and reads neither.\",\"properties\":{\"flushMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The quiet period after the last change before pending changes are staged.\"},\"maxWaitMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The longest a change waits to be staged while others keep arriving, measured from the oldest pending change.\"}},\"required\":[\"flushMs\",\"maxWaitMs\"],\"additionalProperties\":false},\"logLevel\":{\"$ref\":\"https://xynolog.org/protocol/LogLevel.json\"},\"logFormat\":{\"$ref\":\"https://xynolog.org/protocol/LogFormat.json\"}},\"required\":[\"gatewayUrl\",\"identity\",\"root\",\"stateHome\",\"anchoredTextDir\",\"engines\",\"port\",\"skipRebuild\",\"staging\",\"logLevel\",\"logFormat\"],\"additionalProperties\":false},\"ArchivistEventsResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ArchivistEventsResponse.json\",\"type\":\"object\",\"description\":\"A page of one stream's events from one sequence number, inclusive, in log order, and the sequence number of the stream's last event: the Archivist's answer to `GET /events/{resourceId}`.\",\"properties\":{\"events\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/StoredEventResponse.json\"}},\"lastSequence\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"The sequence number of the stream's last event when it was read: 0 for a stream with none. More events follow the page while its last event's number is below it.\"}},\"required\":[\"events\",\"lastSequence\"]},\"ArchivistHealth\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ArchivistHealth.json\",\"type\":\"object\",\"description\":\"The Archivist's liveness answer: it serves, and the actors it hosts.\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"ok\"]},\"actors\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"enum\":[\"stower\",\"browser\",\"cloneTokenManager\"]},\"minItems\":3,\"maxItems\":3,\"uniqueItems\":true,\"description\":\"The record actors this process hosts: each of the enum's, once, in the order the enum lists them.\"}},\"required\":[\"status\",\"actors\"]},\"ArchivistStream\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ArchivistStream.json\",\"type\":\"object\",\"description\":\"One stream of the event log, and where it stands: the resource it is of, or `__system__` for the knowledge base's own, and the sequence number of its last event.\",\"properties\":{\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},\"lastSequence\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"The sequence number of the stream's last event when it was read: 0 for a stream with none.\"}},\"required\":[\"resourceId\",\"lastSequence\"],\"additionalProperties\":false},\"ArchivistStreamsResponse\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/ArchivistStreamsResponse.json\",\"type\":\"object\",\"description\":\"Every stream of the event log, `__system__` among them, each with the sequence number of its last event, in no order: the Archivist's answer to `GET /events`.\",\"properties\":{\"streams\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/ArchivistStream.json\"}}},\"required\":[\"streams\"],\"additionalProperties\":false},\"RepresentationNotFound\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/RepresentationNotFound.json\",\"description\":\"The Archivist's 404 for a resource's bytes: an ErrorResponse whose `code` says which half of the lookup failed \u2014 `resource` when the record holds no such resource, `representation` when it holds the resource but not its bytes. Each reader answers the two differently.\",\"allOf\":[{\"$ref\":\"https://xynolog.org/protocol/ErrorResponse.json\"},{\"type\":\"object\",\"properties\":{\"code\":{\"type\":\"string\",\"enum\":[\"resource\",\"representation\"]}},\"required\":[\"code\"]}]},\"DispatcherConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/DispatcherConfig.json\",\"type\":\"object\",\"description\":\"Everything the dispatcher reads at boot: nothing in it is defaulted by the dispatcher. The launcher writes it for the dispatcher it starts, from the knowledge base's stack documents, and the dispatcher reads it from the path its `--config` flag names (its image passes `/etc/xynolog/dispatcher.json`). Started without `--config`, or with a path that names no file, the dispatcher refuses to start and says which. Secrets are never values here: a field that needs one names the environment variable holding it. The dispatcher's other inputs are the environment variables specs/src/service-environment/variables.json lists for it, and the ones this document names. A document that does not validate is refused at boot, naming each failing field.\",\"properties\":{\"kb\":{\"$ref\":\"https://xynolog.org/protocol/KbIdentity.json\"},\"gatewayUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The URL the dispatcher reaches the gateway at: its only route to the bus.\"},\"identity\":{\"$ref\":\"https://xynolog.org/protocol/ServiceIdentity.json\",\"description\":\"The issuer the dispatcher's service account signs in at.\"},\"queue\":{\"type\":\"object\",\"description\":\"The JetStream broker holding the job queue, whose layout is specs/src/jobs/storage.json.\",\"properties\":{\"servers\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The broker's address (`host:port`, or several, comma-separated).\"},\"userEnv\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The environment variable holding the broker user, when the broker requires one.\"},\"passwordEnv\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The environment variable holding the broker password, when the broker requires one.\"}},\"required\":[\"servers\"],\"additionalProperties\":false},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port the dispatcher answers `/health` on.\"},\"timing\":{\"type\":\"object\",\"description\":\"The queue's clocks, in milliseconds. The launcher writes the values a deployment runs with; a test harness shrinks them.\",\"properties\":{\"tickMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"How often the queue re-announces pending jobs and sweeps for dead workers. The re-announcement is insurance against a lost wake-up, not dispatch.\"},\"staleRunningMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"How long a running job may go without progress, a checkpoint or a claim before its worker is presumed dead.\"},\"ackWaitMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"How long the broker waits, after this dispatcher stops renewing a job's lease, before redelivering its message.\"},\"retentionMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"How long a concluded job is kept before it is deleted.\"},\"retentionSweepMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"How often concluded jobs past `retentionMs` are deleted.\"},\"progressWriteIntervalMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The least time between two progress writes for one job; reports closer together than this are not written.\"},\"bootDeadlineMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"How long the dispatcher waits at boot for the broker before it exits, so that a restart policy can retry.\"}},\"required\":[\"tickMs\",\"staleRunningMs\",\"ackWaitMs\",\"retentionMs\",\"retentionSweepMs\",\"progressWriteIntervalMs\",\"bootDeadlineMs\"],\"additionalProperties\":false},\"logLevel\":{\"$ref\":\"https://xynolog.org/protocol/LogLevel.json\"},\"logFormat\":{\"$ref\":\"https://xynolog.org/protocol/LogFormat.json\"}},\"required\":[\"kb\",\"gatewayUrl\",\"identity\",\"queue\",\"port\",\"timing\",\"logLevel\",\"logFormat\"],\"additionalProperties\":false},\"DispatcherHealth\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/DispatcherHealth.json\",\"type\":\"object\",\"description\":\"The dispatcher's liveness answer. It answers only once its queue has connected and its bus pumps are attached, so a 200 means it can take work.\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"ok\"]},\"queue\":{\"type\":\"string\",\"enum\":[\"jetstream\"],\"description\":\"The queue it holds.\"}},\"required\":[\"status\",\"queue\"],\"additionalProperties\":false},\"EmbeddingConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/EmbeddingConfig.json\",\"description\":\"The embedding provider a service asks for vectors, and what that kind of provider needs to be asked: one of the providers `xynolog-vectors` has, told apart by `type`. Two services that share an index name the same provider and the same model: a vector is compared only with vectors of the model that made it. A secret is never a value here: a provider's key is named by the environment variable that holds it.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/OllamaEmbeddingConfig.json\"},{\"$ref\":\"https://xynolog.org/protocol/VoyageEmbeddingConfig.json\"}],\"discriminator\":{\"propertyName\":\"type\",\"mapping\":{\"ollama\":\"https://xynolog.org/protocol/OllamaEmbeddingConfig.json\",\"voyage\":\"https://xynolog.org/protocol/VoyageEmbeddingConfig.json\"}}},\"OllamaEmbeddingConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/OllamaEmbeddingConfig.json\",\"type\":\"object\",\"description\":\"An embedding model served by an Ollama.\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"ollama\"]},\"model\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The model asked for, by the name the Ollama serves it under.\"},\"baseUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The address the Ollama's API is reached at (`http://host:11434`).\"}},\"required\":[\"type\",\"model\",\"baseUrl\"],\"additionalProperties\":false},\"VoyageEmbeddingConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/VoyageEmbeddingConfig.json\",\"type\":\"object\",\"description\":\"An embedding model served by Voyage AI. No service has been run against Voyage itself.\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"voyage\"]},\"model\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The model asked for, by Voyage's name for it.\"},\"endpoint\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The whole address of Voyage's embeddings call (`https://api.voyageai.com/v1/embeddings`).\"},\"apiKeyEnv\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The environment variable holding the Voyage API key. The key is never a value here.\"}},\"required\":[\"type\",\"model\",\"endpoint\",\"apiKeyEnv\"],\"additionalProperties\":false},\"GatewayConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GatewayConfig.json\",\"type\":\"object\",\"description\":\"Everything the gateway reads at boot: nothing in it is defaulted by the gateway. The launcher writes it for the gateway it starts \u2014 from the knowledge base's committed identity and its stack documents \u2014 and a gateway started any other way is given the same document at the path its `--config` flag names (the image passes `/etc/xynolog/gateway.json`). Started without `--config`, or with a path that names no file, the gateway refuses to start and says which. Secrets are never values here: a field that needs one names the environment variable holding it. The gateway's other inputs are the environment variables specs/src/service-environment/variables.json lists for it, and the ones this document names. A document that does not validate is refused at boot \u2014 the gateway exits without serving \u2014 and the refusal names each failing field by its JSON pointer.\",\"properties\":{\"kb\":{\"$ref\":\"https://xynolog.org/protocol/KbIdentity.json\"},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port the gateway listens on, on every address the host has: IPv4 and IPv6.\"},\"publicUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The URL clients reach this gateway at: the `servers` entry of the OpenAPI document it serves.\"},\"identity\":{\"type\":\"object\",\"description\":\"The issuer this knowledge base trusts.\",\"properties\":{\"issuer\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The issuer URL, exactly as tokens carry it in `iss`.\"},\"subjectClaim\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The claim a person's DID is built from: `did:web:<domain>:users:<its value>`.\"}},\"required\":[\"issuer\",\"subjectClaim\"],\"additionalProperties\":false},\"archivist\":{\"$ref\":\"https://xynolog.org/protocol/ServiceAddress.json\",\"description\":\"Where the Archivist listens.\"},\"signal\":{\"type\":\"object\",\"description\":\"The signal plane: `in-process`, one gateway on its own fabric; or `nats`, the fabric every replica on one broker shares, which requires `servers` and a broker with JetStream.\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"in-process\",\"nats\"]},\"servers\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The broker's address (`host:port`, or several, comma-separated). Required for `nats`.\"},\"userEnv\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The environment variable holding the broker user, when the broker requires one.\"},\"passwordEnv\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The environment variable holding the broker password, when the broker requires one.\"}},\"required\":[\"type\"],\"additionalProperties\":false},\"logLevel\":{\"$ref\":\"https://xynolog.org/protocol/LogLevel.json\"},\"logFormat\":{\"$ref\":\"https://xynolog.org/protocol/LogFormat.json\"},\"capacity\":{\"type\":\"object\",\"description\":\"What this gateway process can hold, from the memory its deployment gives it. `queuedBytes`: the bytes queued for all its streams together; at it, a new stream is refused with 503 (`AtCapacity`, code `capacity`) until the queues drain \u2014 each stream's own bound is `x-xynolog-limits.pendingWriteBytes`. `connections`: the connections it holds open at once; one past it is closed unanswered. The launcher derives both from the memory it gives the gateway's container.\",\"properties\":{\"queuedBytes\":{\"type\":\"integer\",\"minimum\":1},\"connections\":{\"type\":\"integer\",\"minimum\":1}},\"required\":[\"queuedBytes\",\"connections\"],\"additionalProperties\":false}},\"required\":[\"kb\",\"port\",\"publicUrl\",\"identity\",\"archivist\",\"signal\",\"logLevel\",\"logFormat\",\"capacity\"],\"additionalProperties\":false},\"GraphConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/GraphConfig.json\",\"description\":\"The graph database a service writes or reads, and what that kind of database needs to be reached: one of the kinds `xynolog-graph` has a store for, told apart by `type`. A secret is never a value here: a database's password is named by the environment variable that holds it.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/Neo4jGraphConfig.json\"},{\"$ref\":\"https://xynolog.org/protocol/JanusGraphConfig.json\"},{\"$ref\":\"https://xynolog.org/protocol/NeptuneGraphConfig.json\"},{\"$ref\":\"https://xynolog.org/protocol/MemoryGraphConfig.json\"}],\"discriminator\":{\"propertyName\":\"type\",\"mapping\":{\"neo4j\":\"https://xynolog.org/protocol/Neo4jGraphConfig.json\",\"janusgraph\":\"https://xynolog.org/protocol/JanusGraphConfig.json\",\"neptune\":\"https://xynolog.org/protocol/NeptuneGraphConfig.json\",\"memory\":\"https://xynolog.org/protocol/MemoryGraphConfig.json\"}}},\"JanusGraphConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JanusGraphConfig.json\",\"type\":\"object\",\"description\":\"A graph kept in a JanusGraph server, asked in Gremlin. No service has been run against one.\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"janusgraph\"]},\"host\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The server's host.\"},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port its Gremlin endpoint listens on.\"}},\"required\":[\"type\",\"host\",\"port\"],\"additionalProperties\":false},\"MemoryGraphConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MemoryGraphConfig.json\",\"type\":\"object\",\"description\":\"A graph held in the memory of the one process that is given it: for a test. It cannot be shared between processes, so a service that writes the graph for another to read, or reads what another wrote, refuses it.\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"memory\"]}},\"required\":[\"type\"],\"additionalProperties\":false},\"Neo4jGraphConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/Neo4jGraphConfig.json\",\"type\":\"object\",\"description\":\"A graph kept in a Neo4j database.\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"neo4j\"]},\"uri\":{\"type\":\"string\",\"minLength\":1,\"description\":\"Where the database is reached (`bolt://host:7687`).\"},\"username\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The user the service connects as.\"},\"passwordEnv\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The environment variable holding that user's password. The password is never a value here.\"},\"database\":{\"type\":\"string\",\"minLength\":1,\"description\":\"Which of the server's databases holds the graph.\"}},\"required\":[\"type\",\"uri\",\"username\",\"passwordEnv\",\"database\"],\"additionalProperties\":false},\"NeptuneGraphConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/NeptuneGraphConfig.json\",\"type\":\"object\",\"description\":\"A graph kept in Amazon Neptune, asked in Gremlin. No service has been run against one.\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"neptune\"]},\"endpoint\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The cluster's endpoint: its host name.\"},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port its Gremlin endpoint listens on.\"}},\"required\":[\"type\",\"endpoint\",\"port\"],\"additionalProperties\":false},\"LibrarianConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/LibrarianConfig.json\",\"type\":\"object\",\"description\":\"Everything a Librarian reads at boot: nothing in it is defaulted by the Librarian. Whoever starts a Librarian writes it, from the knowledge base's stack documents, and the Librarian reads it from the path its `--config` flag names. This schema is the contract, and a Librarian needs no launcher. Started without `--config`, or with a path that names no file, the Librarian refuses to start and says which. No secret is a value here: the graph database's password, an embedding provider's key and a model provider's key are each named by the environment variable that holds it, and the Librarian's own service account is `XYNOLOG_OIDC_CLIENT_ID` and `XYNOLOG_OIDC_CLIENT_SECRET` in its environment. A document that does not validate is refused at boot, naming each failing field.\",\"properties\":{\"kb\":{\"$ref\":\"https://xynolog.org/protocol/KbIdentity.json\"},\"gatewayUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The URL the Librarian reaches the gateway at: its route to the bus.\"},\"identity\":{\"$ref\":\"https://xynolog.org/protocol/ServiceIdentity.json\",\"description\":\"The issuer the Librarian's service account signs in at.\"},\"archivist\":{\"$ref\":\"https://xynolog.org/protocol/ServiceAddress.json\",\"description\":\"Where the Archivist listens. The Librarian reads a resource's bytes from it, as its service account.\"},\"graph\":{\"$ref\":\"https://xynolog.org/protocol/GraphConfig.json\"},\"vectors\":{\"$ref\":\"https://xynolog.org/protocol/VectorsConfig.json\"},\"embedding\":{\"$ref\":\"https://xynolog.org/protocol/EmbeddingConfig.json\"},\"matcher\":{\"$ref\":\"https://xynolog.org/protocol/LibrarianEngineConfig.json\"},\"gatherer\":{\"$ref\":\"https://xynolog.org/protocol/LibrarianEngineConfig.json\"},\"modelCatalogue\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The path of a model catalogue file: what each model of a provider can take, for the providers whose own APIs do not say (`google`, `openai`, `together`). A Librarian whose matcher or gatherer is of one of those providers refuses to start where the file cannot be read, and where it states nothing of that model. A Librarian with no such model does not read it.\"},\"gather\":{\"type\":\"object\",\"description\":\"The bound on a gather.\",\"properties\":{\"settleTimeoutMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"How long a gather around a resource waits for the Smelter's decision on it before answering without similar passages, in milliseconds.\"}},\"required\":[\"settleTimeoutMs\"],\"additionalProperties\":false},\"search\":{\"type\":\"object\",\"description\":\"The bound on a search by meaning.\",\"properties\":{\"semanticFloor\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1,\"description\":\"The least similarity a hit by meaning must have.\"}},\"required\":[\"semanticFloor\"],\"additionalProperties\":false},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port the Librarian answers `/health` on.\"},\"logLevel\":{\"$ref\":\"https://xynolog.org/protocol/LogLevel.json\"},\"logFormat\":{\"$ref\":\"https://xynolog.org/protocol/LogFormat.json\"}},\"required\":[\"kb\",\"gatewayUrl\",\"identity\",\"archivist\",\"graph\",\"vectors\",\"embedding\",\"matcher\",\"gatherer\",\"modelCatalogue\",\"gather\",\"search\",\"port\",\"logLevel\",\"logFormat\"],\"additionalProperties\":false},\"LibrarianEngineConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/LibrarianEngineConfig.json\",\"type\":\"object\",\"description\":\"The engine a Librarian actor asks: which it is, and where its provider is reached.\",\"properties\":{\"engine\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"baseUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The address the provider's API is reached at.\"},\"apiKeyEnv\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The environment variable holding the provider's API key, when the provider requires one.\"}},\"required\":[\"engine\",\"baseUrl\"],\"additionalProperties\":false},\"LibrarianHealth\":{\"type\":\"object\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"ok\"]},\"kb\":{\"type\":\"string\",\"pattern\":\"^did:web:\\\\S+$\"},\"actors\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"enum\":[\"matcher\",\"gatherer\"]},\"minItems\":2,\"uniqueItems\":true}},\"required\":[\"status\",\"kb\",\"actors\"],\"additionalProperties\":false},\"SmelterChunking\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SmelterChunking.json\",\"type\":\"object\",\"description\":\"The two numbers a text is cut by before it is embedded, both in tokens, a token being taken as four code points.\",\"properties\":{\"chunkSize\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The size of a chunk.\"},\"overlap\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How much of a chunk the next one repeats.\"}},\"required\":[\"chunkSize\",\"overlap\"],\"additionalProperties\":false},\"SmelterConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SmelterConfig.json\",\"type\":\"object\",\"description\":\"Everything a Smelter reads at boot: nothing in it is defaulted by the Smelter. Whoever starts a Smelter writes it, from the knowledge base's stack documents, and the Smelter reads it from the path its `--config` flag names. This schema is the contract, and a Smelter needs no launcher. Started without `--config`, or with a path that names no file, the Smelter refuses to start and says which. No secret is a value here: an embedding provider's key is named by the environment variable that holds it, and the Smelter's own service account is `XYNOLOG_OIDC_CLIENT_ID` and `XYNOLOG_OIDC_CLIENT_SECRET` in its environment. A document that does not validate is refused at boot, naming each failing field.\",\"properties\":{\"kb\":{\"$ref\":\"https://xynolog.org/protocol/KbIdentity.json\"},\"gatewayUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The URL the Smelter reaches the gateway at: its route to the bus.\"},\"identity\":{\"$ref\":\"https://xynolog.org/protocol/ServiceIdentity.json\",\"description\":\"The issuer the Smelter's service account signs in at.\"},\"archivist\":{\"$ref\":\"https://xynolog.org/protocol/ServiceAddress.json\",\"description\":\"Where the Archivist listens. The Smelter reads a resource's bytes from it, and keeps the anchored-text store there, as its service account.\"},\"embedding\":{\"$ref\":\"https://xynolog.org/protocol/EmbeddingConfig.json\"},\"vectors\":{\"$ref\":\"https://xynolog.org/protocol/VectorsConfig.json\"},\"chunking\":{\"$ref\":\"https://xynolog.org/protocol/SmelterChunking.json\"},\"pdfsAtOnce\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"How many PDFs the Smelter works on at once. Each one under way holds its bytes, a page of a scan in pixels beside the OCR process reading it, and its text and vectors, so whoever starts a Smelter sizes this with the memory it gives it. Every other resource is indexed beside them.\"},\"cursorsPath\":{\"$ref\":\"https://xynolog.org/protocol/CursorsPath.json\"},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port the Smelter answers `/health` on.\"},\"logLevel\":{\"$ref\":\"https://xynolog.org/protocol/LogLevel.json\"},\"logFormat\":{\"$ref\":\"https://xynolog.org/protocol/LogFormat.json\"}},\"required\":[\"kb\",\"gatewayUrl\",\"identity\",\"archivist\",\"embedding\",\"vectors\",\"chunking\",\"pdfsAtOnce\",\"cursorsPath\",\"port\",\"logLevel\",\"logFormat\"],\"additionalProperties\":false},\"SmelterHealth\":{\"type\":\"object\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"ok\"]},\"kb\":{\"type\":\"string\",\"pattern\":\"^did:web:\\\\S+$\"},\"stream\":{\"type\":\"string\",\"enum\":[\"initial\",\"connecting\",\"open\",\"reconnecting\",\"degraded\",\"unauthenticated\",\"closed\"]},\"following\":{\"type\":\"object\",\"properties\":{\"sweep\":{\"type\":\"string\",\"enum\":[\"pending\",\"running\",\"done\",\"due\"]},\"stopped\":{\"type\":\"integer\",\"minimum\":0.0},\"refused\":{\"type\":\"integer\",\"minimum\":0.0},\"streamDrops\":{\"type\":\"integer\",\"minimum\":0.0}},\"required\":[\"sweep\",\"stopped\",\"refused\",\"streamDrops\"],\"additionalProperties\":false},\"eventsProcessed\":{\"type\":\"integer\",\"minimum\":0.0},\"reconcile\":{\"type\":\"object\",\"properties\":{\"phase\":{\"type\":\"string\",\"enum\":[\"pending\",\"running\",\"done\",\"failed\"]},\"summary\":{\"$ref\":\"https://xynolog.org/protocol/SmelterReconcileSummary.json\"},\"error\":{\"type\":\"string\"}},\"required\":[\"phase\"],\"additionalProperties\":false},\"index\":{\"type\":\"object\",\"properties\":{\"stamp\":{\"type\":\"object\",\"properties\":{\"embedding\":{\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\",\"minLength\":1},\"model\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"type\",\"model\"],\"additionalProperties\":false},\"chunking\":{\"$ref\":\"https://xynolog.org/protocol/SmelterChunking.json\"}},\"required\":[\"embedding\",\"chunking\"],\"additionalProperties\":false},\"madeAnew\":{\"type\":\"boolean\"}},\"required\":[\"stamp\",\"madeAnew\"],\"additionalProperties\":false}},\"required\":[\"status\",\"kb\",\"stream\",\"following\",\"eventsProcessed\",\"reconcile\",\"index\"],\"additionalProperties\":false},\"SmelterReconcileSummary\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SmelterReconcileSummary.json\",\"type\":\"object\",\"description\":\"What a Smelter's reconcile came to (SMELTER.md \u00A7 Reconcile), as its health reports a pass that is done (SmelterHealth's `reconcile.summary`). The first four add up to how many resources it set out to index, less any whose indexing was no longer wanted when its turn came.\",\"properties\":{\"resourcesEmbedded\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many resources it set out to index were indexed.\"},\"resourcesSkipped\":{\"type\":\"object\",\"description\":\"How many were skipped, by the reason each was skipped for: a reason `smelt:settled` carries (SmeltSettled).\",\"additionalProperties\":{\"type\":\"integer\",\"minimum\":0}},\"resourcesUnavailable\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many could not be read.\"},\"resourcesFailed\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many failed.\"},\"resourcesRestamped\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many resources it planned to rewrite the entity types of.\"},\"resourcesReanchored\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many resources it planned to derive the anchored text of again.\"},\"resourceVectorsDeleted\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many resources it planned to take out of the index.\"},\"annotationsEmbedded\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many annotations it planned to index.\"},\"annotationsRestamped\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many annotations it planned to rewrite the entity types of.\"},\"annotationVectorsDeleted\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many annotations it planned to take out of the index.\"},\"resourcesEligible\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many resources of the catalog have text.\"},\"resourcesIndexed\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many resources have points when it ends.\"}},\"required\":[\"resourcesEmbedded\",\"resourcesSkipped\",\"resourcesUnavailable\",\"resourcesFailed\",\"resourcesRestamped\",\"resourcesReanchored\",\"resourceVectorsDeleted\",\"annotationsEmbedded\",\"annotationsRestamped\",\"annotationVectorsDeleted\",\"resourcesEligible\",\"resourcesIndexed\"],\"additionalProperties\":false},\"MemoryVectorsConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MemoryVectorsConfig.json\",\"type\":\"object\",\"description\":\"A vector index held in the memory of the one process that is given it: for a test. It cannot be shared between processes, so a service that writes the index for another to search, or searches what another wrote, refuses it.\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"memory\"]}},\"required\":[\"type\"],\"additionalProperties\":false},\"QdrantVectorsConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/QdrantVectorsConfig.json\",\"type\":\"object\",\"description\":\"A vector index kept in a Qdrant server, asked over its REST API with a token.\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"qdrant\"]},\"host\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The server's host.\"},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port its REST API listens on.\"},\"tokenEnv\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The environment variable holding the token the service presents to the server on every request, which says what of the index it may read and write. The token is never a value here.\"}},\"required\":[\"type\",\"host\",\"port\",\"tokenEnv\"],\"additionalProperties\":false},\"VectorsConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/VectorsConfig.json\",\"description\":\"The vector index a service writes or searches, and what that kind of index needs to be reached: one of the kinds `xynolog-vectors` has a store for, told apart by `type`.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/QdrantVectorsConfig.json\"},{\"$ref\":\"https://xynolog.org/protocol/MemoryVectorsConfig.json\"}],\"discriminator\":{\"propertyName\":\"type\",\"mapping\":{\"qdrant\":\"https://xynolog.org/protocol/QdrantVectorsConfig.json\",\"memory\":\"https://xynolog.org/protocol/MemoryVectorsConfig.json\"}}},\"WeaverConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/WeaverConfig.json\",\"type\":\"object\",\"description\":\"Everything a Weaver reads at boot: nothing in it is defaulted by the Weaver. The launcher writes it for the Weaver it starts, from the knowledge base's stack documents, and the Weaver reads it from the path its `--config` flag names (its image passes `/etc/xynolog/weaver.json`). Whoever starts a Weaver another way writes the same document: this schema is the contract, and a Weaver needs no launcher. Started without `--config`, or with a path that names no file, the Weaver refuses to start and says which. No secret is a value here: the graph database's password is named by the environment variable that holds it, and the Weaver's own service account is `XYNOLOG_OIDC_CLIENT_ID` and `XYNOLOG_OIDC_CLIENT_SECRET` in its environment. A document that does not validate is refused at boot, naming each failing field.\",\"properties\":{\"kb\":{\"$ref\":\"https://xynolog.org/protocol/KbIdentity.json\"},\"gatewayUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The URL the Weaver reaches the gateway at: its route to the bus.\"},\"identity\":{\"$ref\":\"https://xynolog.org/protocol/ServiceIdentity.json\",\"description\":\"The issuer the Weaver's service account signs in at.\"},\"archivist\":{\"$ref\":\"https://xynolog.org/protocol/ServiceAddress.json\",\"description\":\"Where the Archivist listens. The Weaver reads the record by position from it, and a resource's annotations, as its service account.\"},\"graph\":{\"$ref\":\"https://xynolog.org/protocol/GraphConfig.json\"},\"cursorsPath\":{\"$ref\":\"https://xynolog.org/protocol/CursorsPath.json\"},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port the Weaver answers `/health` on.\"},\"logLevel\":{\"$ref\":\"https://xynolog.org/protocol/LogLevel.json\"},\"logFormat\":{\"$ref\":\"https://xynolog.org/protocol/LogFormat.json\"}},\"required\":[\"kb\",\"gatewayUrl\",\"identity\",\"archivist\",\"graph\",\"cursorsPath\",\"port\",\"logLevel\",\"logFormat\"],\"additionalProperties\":false},\"WeaverHealth\":{\"type\":\"object\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"ok\"]},\"kb\":{\"type\":\"string\",\"pattern\":\"^did:web:\\\\S+$\"},\"following\":{\"type\":\"object\",\"properties\":{\"sweep\":{\"type\":\"string\",\"enum\":[\"pending\",\"running\",\"done\",\"due\"]},\"stopped\":{\"type\":\"integer\",\"minimum\":0.0},\"refused\":{\"type\":\"integer\",\"minimum\":0.0},\"streamDrops\":{\"type\":\"integer\",\"minimum\":0.0}},\"required\":[\"sweep\",\"stopped\",\"refused\",\"streamDrops\"],\"additionalProperties\":false},\"reconcile\":{\"type\":\"object\",\"properties\":{\"phase\":{\"type\":\"string\",\"enum\":[\"pending\",\"running\",\"done\",\"failed\"]},\"summary\":{\"type\":\"object\",\"properties\":{\"resourcesChecked\":{\"type\":\"integer\",\"minimum\":0.0},\"divergent\":{\"type\":\"integer\",\"minimum\":0.0},\"healed\":{\"type\":\"integer\",\"minimum\":0.0},\"healFailures\":{\"type\":\"integer\",\"minimum\":0.0},\"orphaned\":{\"type\":\"integer\",\"minimum\":0.0}},\"required\":[\"resourcesChecked\",\"divergent\",\"healed\",\"healFailures\",\"orphaned\"],\"additionalProperties\":false},\"error\":{\"type\":\"string\"}},\"required\":[\"phase\"],\"additionalProperties\":false}},\"required\":[\"status\",\"kb\",\"following\",\"reconcile\"],\"additionalProperties\":false},\"WorkerConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/WorkerConfig.json\",\"type\":\"object\",\"description\":\"Everything a worker reads at boot: nothing in it is defaulted by the worker. The launcher writes it for the machine's worker, from the knowledge bases on that worker's list: each local knowledge base as its start places it, from its stack documents, and each added by `xynolog worker kb add`, offered the engines of the local one it was added from. The worker reads it from the path its `--config` flag names (its image passes `/etc/xynolog/worker.json`). Whoever starts a worker another way writes the same document: this schema is the contract, and a worker needs no launcher. Started without `--config`, or with a path that names no file, the worker refuses to start and says which. No secret is a value here: a provider's key is named by the environment variable that holds it, and the key the worker signs in with at every knowledge base is `XYNOLOG_OIDC_CLIENT_KEY` in its environment, an RSA private key; each knowledge base names the client that holds its public half there. A document that does not validate is refused at boot, naming each failing field.\",\"properties\":{\"knowledgeBases\":{\"type\":\"array\",\"minItems\":1,\"description\":\"The knowledge bases this worker does jobs for. At each it signs in, confirms which knowledge base it reached and claims for its engines, apart from every other: one knowledge base's trouble stops that knowledge base's work alone (`contract/WORKER-SERVICE.md` \u00A7 Knowledge bases). No two name one `domain`, which the worker refuses at boot.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/WorkerKnowledgeBaseConfig.json\"}},\"modelCatalogue\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The path of a model catalogue file: what each model of a provider can take, for the providers whose own APIs do not say (`google`, `openai`, `together`). A worker with an engine of one of those providers refuses to start where the file cannot be read, and where it states nothing of that engine's model. A worker with no such engine does not read it.\"},\"port\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":65535,\"description\":\"The port the worker answers `/health` on.\"},\"logLevel\":{\"$ref\":\"https://xynolog.org/protocol/LogLevel.json\"},\"logFormat\":{\"$ref\":\"https://xynolog.org/protocol/LogFormat.json\"}},\"required\":[\"knowledgeBases\",\"modelCatalogue\",\"port\",\"logLevel\",\"logFormat\"],\"additionalProperties\":false},\"WorkerEngineConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/WorkerEngineConfig.json\",\"type\":\"object\",\"description\":\"One engine a worker runs: which it is, the jobs the worker claims to do with it, and where its provider is reached.\",\"properties\":{\"engine\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"jobs\":{\"type\":\"array\",\"minItems\":1,\"description\":\"The jobs the worker claims to do with this engine, as a claim names them (`job:claim`'s `accepts`): it claims with these filters and no other.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/JobFilter.json\"}},\"baseUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The address the provider's API is reached at.\"},\"apiKeyEnv\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The environment variable holding the provider's API key, when the provider requires one.\"}},\"required\":[\"engine\",\"jobs\",\"baseUrl\"],\"additionalProperties\":false},\"WorkerEngineHealth\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/WorkerEngineHealth.json\",\"type\":\"object\",\"description\":\"One engine at one knowledge base: which it is, the jobs it claims, and what its claims can say of themselves (WORKER-CONTRACT V1).\",\"properties\":{\"engine\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"jobs\":{\"type\":\"array\",\"minItems\":1,\"description\":\"The jobs it claims, as its claims state them.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/JobFilter.json\"}},\"lastQueuedEventAt\":{\"type\":[\"string\",\"null\"],\"format\":\"date-time\",\"description\":\"When a `job:queued` last reached it, or null.\"},\"lastClaimAt\":{\"type\":[\"string\",\"null\"],\"format\":\"date-time\",\"description\":\"When it was last handed a job, or null. A claim answered with none pending is not one.\"},\"lastFinishedAt\":{\"type\":[\"string\",\"null\"],\"format\":\"date-time\",\"description\":\"When a job it held last settled, or null.\"},\"lastActivityAt\":{\"type\":[\"string\",\"null\"],\"format\":\"date-time\",\"description\":\"When it was last active, or null.\"},\"activeJob\":{\"type\":[\"object\",\"null\"],\"description\":\"The job it holds, or null.\",\"properties\":{\"jobId\":{\"$ref\":\"https://xynolog.org/protocol/JobId.json\"},\"type\":{\"$ref\":\"https://xynolog.org/protocol/JobType.json\"},\"since\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"When it was handed the job.\"}},\"required\":[\"jobId\",\"type\",\"since\"],\"additionalProperties\":false},\"jobsCompleted\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many jobs it has completed since the service started.\"}},\"required\":[\"engine\",\"jobs\",\"lastQueuedEventAt\",\"lastClaimAt\",\"lastFinishedAt\",\"lastActivityAt\",\"activeJob\",\"jobsCompleted\"],\"additionalProperties\":false},\"WorkerHealth\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/WorkerHealth.json\",\"type\":\"object\",\"description\":\"The Worker service's health answer (WORKER-SERVICE H1). It answers only once a knowledge base of its document is confirmed, so a 200 means it is working somewhere.\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"ok\"]},\"knowledgeBases\":{\"type\":\"array\",\"minItems\":1,\"description\":\"One entry for each of the document's `knowledgeBases`, in its order.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/WorkerKnowledgeBaseHealth.json\"}}},\"required\":[\"status\",\"knowledgeBases\"],\"additionalProperties\":false},\"WorkerKnowledgeBaseConfig\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/WorkerKnowledgeBaseConfig.json\",\"type\":\"object\",\"description\":\"One knowledge base a worker does jobs for: which it is, where its gateway is, the account the worker signs in as there, and the engines it offers it. The worker signs in, confirms the knowledge base and claims at each knowledge base apart from every other.\",\"properties\":{\"domain\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The knowledge base's did:web domain, as it answers `browse:kb-requested`: which knowledge base this is. The worker confirms it there before it claims, and refuses a knowledge base that answers another domain, or none.\"},\"gatewayUrl\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The URL the worker reaches the knowledge base's gateway at: its route to the bus and to a resource's bytes, and the only address of the knowledge base it holds.\"},\"identity\":{\"type\":\"object\",\"description\":\"Where the worker signs in for this knowledge base, and as which client.\",\"properties\":{\"issuer\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The issuer URL, exactly as tokens carry it in `iss`.\"},\"clientId\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The client the issuer holds the public half of the worker's key on: the worker's account at this knowledge base. It is also what the worker says it is called there (`principal:profile`).\"}},\"required\":[\"issuer\",\"clientId\"],\"additionalProperties\":false},\"engines\":{\"type\":\"array\",\"minItems\":1,\"description\":\"The engines the worker offers this knowledge base, and the jobs it does with each: its own choice, on its own providers' keys. It claims each engine's jobs there for it, so a job no engine here is used for is not claimed at this knowledge base.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/WorkerEngineConfig.json\"}}},\"required\":[\"domain\",\"gatewayUrl\",\"identity\",\"engines\"],\"additionalProperties\":false},\"WorkerKnowledgeBaseHealth\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/WorkerKnowledgeBaseHealth.json\",\"type\":\"object\",\"description\":\"One knowledge base the worker serves, as its health says it. `did` and `engines` are there while it is `working`, and only then.\",\"properties\":{\"domain\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The entry's `domain`.\"},\"state\":{\"type\":\"string\",\"enum\":[\"starting\",\"working\",\"refused\"],\"description\":\"`starting`: signing in, opening its stream, confirming it, or waiting to start again. `working`: confirmed, its engines claiming. `refused`: refused, until the service is started again.\"},\"did\":{\"type\":\"string\",\"minLength\":1,\"description\":\"The agent's DID at this knowledge base, as its gateway named it.\"},\"engines\":{\"type\":\"array\",\"minItems\":1,\"description\":\"One entry for each of the entry's engines, in its order.\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/WorkerEngineHealth.json\"}}},\"required\":[\"domain\",\"state\"],\"additionalProperties\":false},\"SignIn\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SignIn.json\",\"title\":\"SignIn\",\"type\":\"object\",\"description\":\"One sign-in to a running stack's knowledge base, as the sign-in store keeps it: the tokens an issuer issued to the script client, and what a renewal and a sign-out need of that issuer, learned once at sign-in. TOKENS, never a password. An entry of <stateDir>/tokens.json (see README.md).\",\"properties\":{\"token\":{\"type\":\"string\",\"description\":\"The access token: short-lived, sent as a Bearer token.\"},\"refreshToken\":{\"type\":\"string\",\"description\":\"The refresh token: long-lived, and what renews the access token at the issuer without another sign-in. An entry with none cannot be renewed.\"},\"email\":{\"type\":\"string\",\"description\":\"Who signed in: the address the access token named when the sign-in was made, which is the one the gateway answers for it. For display. Absent when the token named none. A writer that renews an entry keeps it as it was.\"},\"obtainedAt\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"When the access token was issued to this machine, RFC 3339 in UTC.\"},\"expiresAt\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"When the access token stops working, RFC 3339 in UTC, so a reader can renew before sending a token it knows is dead. Absent when the issuer named no lifetime: the gateway's refusal is then the signal.\"},\"issuer\":{\"type\":\"string\",\"description\":\"The issuer the sign-in came from: the one the access token named when the sign-in was made. A writer that renews an entry keeps it.\"},\"tokenEndpoint\":{\"type\":\"string\",\"description\":\"The issuer's token endpoint, where the refresh grant is made.\"},\"revocationEndpoint\":{\"type\":\"string\",\"description\":\"The issuer's revocation endpoint (RFC 7009), where a sign-out tells it to forget the refresh token. Absent when the issuer has none.\"}},\"required\":[\"token\",\"obtainedAt\",\"issuer\",\"tokenEndpoint\"]},\"AnchorMethod\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/AnchorMethod.json\",\"title\":\"AnchorMethod\",\"type\":\"string\",\"description\":\"How a quoted selection was found in a text. Which word a span is found by is reconcile's rule (specs/src/annotations/reconcile-cases.json).\",\"enum\":[\"unique-match\",\"context-recovered\",\"first-of-many\",\"fuzzy-match\"]},\"BeginAuthorizationOptions\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/BeginAuthorizationOptions.json\",\"title\":\"BeginAuthorizationOptions\",\"type\":\"object\",\"description\":\"What starting an authorization-code grant is told: the knowledge base to sign in to, where the issuer sends the person back, and, re-authenticating, which registered knowledge base it is and what the person believed they chose.\",\"properties\":{\"target\":{\"$ref\":\"https://xynolog.org/protocol/HttpEndpoint.json\"},\"redirectUri\":{\"type\":\"string\",\"description\":\"Where the issuer sends the person back to.\"},\"kbId\":{\"type\":\"string\",\"description\":\"The registered knowledge base being re-authenticated, rather than a new address connected to.\"},\"expectedDid\":{\"type\":\"string\",\"description\":\"The knowledge base's DID the person believed they chose: verified after, never assumed.\"},\"expectedName\":{\"type\":\"string\",\"description\":\"The knowledge base's name the person believed they chose: verified after, never assumed.\"}},\"required\":[\"target\",\"redirectUri\"],\"additionalProperties\":false},\"ClaimOptions\":{\"type\":\"object\",\"properties\":{\"accepts\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/JobFilter.json\"},\"minItems\":1},\"jobClaimTimeoutMs\":{\"type\":\"integer\",\"minimum\":0.0},\"heldJobStallMs\":{\"type\":\"integer\",\"minimum\":0.0},\"heldJobStallCheckMs\":{\"type\":\"integer\",\"minimum\":0.0},\"markCommitTimeoutMs\":{\"type\":\"integer\",\"minimum\":0.0}},\"required\":[\"accepts\"],\"additionalProperties\":false},\"CreateFromTokenOptions\":{\"type\":\"object\",\"properties\":{\"token\":{\"type\":\"string\"},\"name\":{\"type\":\"string\"},\"content\":{\"type\":\"string\"},\"archiveOriginal\":{\"type\":\"boolean\"}},\"required\":[\"token\",\"name\",\"content\"],\"additionalProperties\":false},\"DeviceCode\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/DeviceCode.json\",\"title\":\"DeviceCode\",\"type\":\"object\",\"description\":\"What a device-authorization grant (RFC 8628) shows the person signing in: the code they enter, and where.\",\"properties\":{\"userCode\":{\"type\":\"string\",\"description\":\"The code the person enters at the issuer.\"},\"verificationUri\":{\"type\":\"string\",\"description\":\"Where the person enters it.\"},\"verificationUriComplete\":{\"type\":\"string\",\"description\":\"Where the person goes to sign in with the code already entered, when the issuer gives one.\"},\"expiresIn\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many seconds the code stays good for.\"}},\"required\":[\"userCode\",\"verificationUri\",\"expiresIn\"],\"additionalProperties\":false},\"FrameRefusalReason\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/FrameRefusalReason.json\",\"title\":\"FrameRefusalReason\",\"type\":\"string\",\"description\":\"Why a reader refused a frame, for its first fault: `lacks`, a member it lacks; `malformed`, a member that is not of its shape. A reader's rule (specs/src/bus/frame-cases.json).\",\"enum\":[\"lacks\",\"malformed\"]},\"GatherResourceOptions\":{\"type\":\"object\",\"properties\":{\"depth\":{\"type\":\"integer\",\"minimum\":1.0,\"maximum\":3.0},\"maxResources\":{\"type\":\"integer\",\"minimum\":1.0,\"maximum\":200.0},\"includeContent\":{\"type\":\"boolean\"},\"includeSummary\":{\"type\":\"boolean\"},\"excludeEntityTypes\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}},\"additionalProperties\":false},\"IssuedTokens\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/IssuedTokens.json\",\"title\":\"IssuedTokens\",\"type\":\"object\",\"description\":\"The tokens an issuer issued at the end of a sign-in.\",\"properties\":{\"access\":{\"type\":\"string\",\"description\":\"The access token: short-lived, sent as a Bearer token.\"},\"refresh\":{\"type\":\"string\",\"description\":\"The refresh token: what renews the access token without another sign-in.\"}},\"required\":[\"access\",\"refresh\"],\"additionalProperties\":false},\"JobPollOptions\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/JobPollOptions.json\",\"title\":\"JobPollOptions\",\"type\":\"object\",\"additionalProperties\":false,\"description\":\"How a job's `pollUntilComplete` asks for the job's status: how long it waits between its asks, and how long it goes on asking. A member left out is client/timing.json's: `jobPollMs` and `jobPollTimeoutMs`.\",\"properties\":{\"everyMs\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How long it waits between one ask and the next, in milliseconds.\"},\"withinMs\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How long it goes on asking, from its first ask, before it fails as timed out, in milliseconds.\"}}},\"MatchQuality\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/MatchQuality.json\",\"title\":\"MatchQuality\",\"type\":\"string\",\"description\":\"Which looser search found a quoted selection, stated of a span whose `anchorMethod` is `fuzzy-match` and only then. Which search finds it is reconcile's rule (specs/src/annotations/reconcile-cases.json).\",\"enum\":[\"normalized\",\"case-insensitive\",\"fuzzy\"]},\"MatchSearchOptions\":{\"type\":\"object\",\"properties\":{\"limit\":{\"type\":\"integer\",\"minimum\":1.0,\"maximum\":200.0},\"useSemanticScoring\":{\"type\":\"boolean\"}},\"additionalProperties\":false},\"PdfCoordinate\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/PdfCoordinate.json\",\"title\":\"PdfCoordinate\",\"type\":\"object\",\"description\":\"A rectangle on a page of a PDF, in PDF points, from the page's bottom-left corner with y increasing upward: what an RFC 3778 fragment selector names.\",\"properties\":{\"page\":{\"type\":\"integer\",\"description\":\"The page the rectangle is on.\"},\"x\":{\"type\":\"number\",\"description\":\"The rectangle's x.\"},\"y\":{\"type\":\"number\",\"description\":\"The rectangle's y.\"},\"width\":{\"type\":\"number\",\"description\":\"The rectangle's width.\"},\"height\":{\"type\":\"number\",\"description\":\"The rectangle's height.\"}},\"required\":[\"page\",\"x\",\"y\",\"width\",\"height\"],\"additionalProperties\":false},\"PendingAnnotation\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/PendingAnnotation.json\",\"title\":\"PendingAnnotation\",\"type\":\"object\",\"description\":\"The annotation a mark state unit is composing, from the selection a request asked for, until it is submitted or cancelled.\",\"properties\":{\"selector\":{\"$ref\":\"https://xynolog.org/protocol/AnnotationSelector.json\"},\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\"}},\"required\":[\"selector\",\"motivation\"],\"additionalProperties\":false},\"QuotedText\":{\"type\":\"object\",\"properties\":{\"exact\":{\"type\":\"string\"},\"prefix\":{\"type\":\"string\"},\"suffix\":{\"type\":\"string\"}},\"required\":[\"exact\"],\"additionalProperties\":false},\"ReconciledSpan\":{\"oneOf\":[{\"type\":\"object\",\"properties\":{\"start\":{\"type\":\"integer\",\"minimum\":0.0},\"end\":{\"type\":\"integer\",\"minimum\":0.0},\"exact\":{\"type\":\"string\"},\"prefix\":{\"type\":\"string\"},\"suffix\":{\"type\":\"string\"},\"anchorMethod\":{\"type\":\"string\",\"enum\":[\"unique-match\"]}},\"required\":[\"start\",\"end\",\"exact\",\"anchorMethod\"],\"additionalProperties\":false},{\"type\":\"object\",\"properties\":{\"start\":{\"type\":\"integer\",\"minimum\":0.0},\"end\":{\"type\":\"integer\",\"minimum\":0.0},\"exact\":{\"type\":\"string\"},\"prefix\":{\"type\":\"string\"},\"suffix\":{\"type\":\"string\"},\"anchorMethod\":{\"type\":\"string\",\"enum\":[\"context-recovered\"]}},\"required\":[\"start\",\"end\",\"exact\",\"anchorMethod\"],\"additionalProperties\":false},{\"type\":\"object\",\"properties\":{\"start\":{\"type\":\"integer\",\"minimum\":0.0},\"end\":{\"type\":\"integer\",\"minimum\":0.0},\"exact\":{\"type\":\"string\"},\"prefix\":{\"type\":\"string\"},\"suffix\":{\"type\":\"string\"},\"anchorMethod\":{\"type\":\"string\",\"enum\":[\"first-of-many\"]}},\"required\":[\"start\",\"end\",\"exact\",\"anchorMethod\"],\"additionalProperties\":false},{\"type\":\"object\",\"properties\":{\"start\":{\"type\":\"integer\",\"minimum\":0.0},\"end\":{\"type\":\"integer\",\"minimum\":0.0},\"exact\":{\"type\":\"string\"},\"prefix\":{\"type\":\"string\"},\"suffix\":{\"type\":\"string\"},\"anchorMethod\":{\"type\":\"string\",\"enum\":[\"fuzzy-match\"]},\"matchQuality\":{\"$ref\":\"https://xynolog.org/protocol/MatchQuality.json\"}},\"required\":[\"start\",\"end\",\"exact\",\"anchorMethod\",\"matchQuality\"],\"additionalProperties\":false}]},\"ResourceSearchFilters\":{\"type\":\"object\",\"properties\":{\"archived\":{\"type\":\"boolean\"},\"entityType\":{\"type\":\"string\"},\"offset\":{\"type\":\"integer\",\"minimum\":0.0},\"limit\":{\"type\":\"integer\",\"minimum\":1.0,\"maximum\":200.0}},\"additionalProperties\":false},\"TextSpan\":{\"type\":\"object\",\"properties\":{\"start\":{\"type\":\"integer\",\"minimum\":0.0},\"end\":{\"type\":\"integer\",\"minimum\":0.0},\"exact\":{\"type\":\"string\"},\"prefix\":{\"type\":\"string\"},\"suffix\":{\"type\":\"string\"}},\"required\":[\"start\",\"end\",\"exact\"],\"additionalProperties\":false},\"UploadProgress\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/UploadProgress.json\",\"title\":\"UploadProgress\",\"description\":\"What an upload reports as it goes, told apart by `phase`: its size first, then the bytes sent so far, then the resource made.\",\"oneOf\":[{\"type\":\"object\",\"description\":\"The upload began.\",\"properties\":{\"phase\":{\"type\":\"string\",\"enum\":[\"started\"]},\"totalBytes\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many bytes the upload is.\"}},\"required\":[\"phase\",\"totalBytes\"],\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"Bytes were sent.\",\"properties\":{\"phase\":{\"type\":\"string\",\"enum\":[\"progress\"]},\"bytesUploaded\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many bytes are sent so far.\"},\"totalBytes\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"How many bytes the upload is.\"}},\"required\":[\"phase\",\"bytesUploaded\",\"totalBytes\"],\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"The upload ended, and the resource is made.\",\"properties\":{\"phase\":{\"type\":\"string\",\"enum\":[\"finished\"]},\"resourceId\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}},\"required\":[\"phase\",\"resourceId\"],\"additionalProperties\":false}],\"discriminator\":{\"propertyName\":\"phase\"}},\"ConnectionIdentity\":{\"title\":\"ConnectionIdentity\",\"type\":\"object\",\"description\":\"Who the knowledge base at an address says it is, asked with a token just issued, before any entry is made for it.\",\"additionalProperties\":false,\"properties\":{\"did\":{\"$ref\":\"https://xynolog.org/protocol/UserId.json\",\"description\":\"The did it reports for itself.\"},\"description\":{\"$ref\":\"https://xynolog.org/protocol/KbDescription.json\",\"description\":\"What it says of itself.\"}},\"required\":[\"did\",\"description\"]},\"SignedIn\":{\"title\":\"SignedIn\",\"type\":\"object\",\"description\":\"What a completed sign-in learned, as a registry is handed it to record: where it was, who the knowledge base there says it is, the tokens, and what the person believed they were signing in to.\",\"additionalProperties\":false,\"properties\":{\"endpoint\":{\"$ref\":\"https://xynolog.org/protocol/KbEndpoint.json\",\"description\":\"Where the sign-in was.\"},\"description\":{\"$ref\":\"https://xynolog.org/protocol/KbDescription.json\",\"description\":\"What the knowledge base said of itself, asked with the new token.\"},\"session\":{\"$ref\":\"StoredSession.json\",\"description\":\"The tokens, as a registry keeps them.\"},\"kbId\":{\"type\":\"string\",\"description\":\"The registered knowledge base the person signed in to again. Absent when it is none.\"},\"expectedDid\":{\"type\":\"string\",\"description\":\"The did of what the person believed they clicked. Absent when they named nothing.\"},\"expectedName\":{\"type\":\"string\",\"description\":\"The name of what the person believed they clicked. Absent when they named nothing.\"}},\"required\":[\"endpoint\",\"description\",\"session\"]},\"Expected\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/Expected.json\",\"title\":\"Expected\",\"type\":\"object\",\"description\":\"What a person believed they were signing in to: the did and the name of the row they clicked, or of the entry they signed in to again.\",\"additionalProperties\":false,\"properties\":{\"did\":{\"type\":\"string\",\"description\":\"The did they believed it has.\"},\"name\":{\"type\":\"string\",\"description\":\"The name they believed it has. Absent when they had none.\"}},\"required\":[\"did\"]},\"SignInOutcome\":{\"title\":\"SignInOutcome\",\"type\":\"object\",\"description\":\"The entry a sign-in landed on, and what the person believed, so a host can set the two against each other and say when they differ. The sign-in stands either way: the knowledge base that answered is the one reached.\",\"additionalProperties\":false,\"properties\":{\"kb\":{\"$ref\":\"https://xynolog.org/protocol/KnowledgeBase.json\",\"description\":\"The entry the sign-in made or signed in to again.\"},\"expected\":{\"$ref\":\"Expected.json\",\"description\":\"What the person believed they were signing in to. Absent when they named nothing.\"}},\"required\":[\"kb\"]},\"KbReadKind\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/KbReadKind.json\",\"title\":\"KbReadKind\",\"type\":\"string\",\"description\":\"What reading the active knowledge base against its entry concluded.\",\"enum\":[\"recorded\",\"conflict\",\"no-verdict\"]},\"KbReadVerdict\":{\"title\":\"KbReadVerdict\",\"description\":\"What a knowledge base said when it was asked to describe itself, read against the entry it was asked as.\",\"discriminator\":{\"propertyName\":\"kind\"},\"oneOf\":[{\"type\":\"object\",\"description\":\"It answered as that entry, and its name and branch are on the entry now.\",\"additionalProperties\":false,\"properties\":{\"kind\":{\"allOf\":[{\"$ref\":\"KbReadKind.json\"}],\"enum\":[\"recorded\"]}},\"required\":[\"kind\"]},{\"type\":\"object\",\"description\":\"A different knowledge base answered. Its did and the name it gave itself are here and nowhere else: the entry is as it was.\",\"additionalProperties\":false,\"properties\":{\"kind\":{\"allOf\":[{\"$ref\":\"KbReadKind.json\"}],\"enum\":[\"conflict\"]},\"observedDid\":{\"type\":\"string\",\"description\":\"The did the knowledge base that answered reported.\"},\"observedName\":{\"type\":\"string\",\"description\":\"The name the knowledge base that answered gave itself.\"}},\"required\":[\"kind\",\"observedDid\",\"observedName\"]},{\"type\":\"object\",\"description\":\"It did not answer, or could not say who it is. Evidence of nothing.\",\"additionalProperties\":false,\"properties\":{\"kind\":{\"allOf\":[{\"$ref\":\"KbReadKind.json\"}],\"enum\":[\"no-verdict\"]}},\"required\":[\"kind\"]}]},\"TabVerdict\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/TabVerdict.json\",\"title\":\"TabVerdict\",\"type\":\"string\",\"description\":\"What checking an open resource against its knowledge base concluded.\",\"enum\":[\"gone\",\"ready\",\"unknown\"]},\"TabCheck\":{\"title\":\"TabCheck\",\"description\":\"What checking one open resource against its knowledge base concluded. `gone` is the only verdict that closes it, and it means the knowledge base said the resource does not exist, not that the check failed: a failed transport, a timeout and a peer that is down are each `unknown`, and an unknown resource stays open.\",\"discriminator\":{\"propertyName\":\"verdict\"},\"oneOf\":[{\"type\":\"object\",\"description\":\"The knowledge base said the resource does not exist.\",\"additionalProperties\":false,\"properties\":{\"verdict\":{\"allOf\":[{\"$ref\":\"TabVerdict.json\"}],\"enum\":[\"gone\"]}},\"required\":[\"verdict\"]},{\"type\":\"object\",\"description\":\"The knowledge base has the resource, and said what it is called now.\",\"additionalProperties\":false,\"properties\":{\"verdict\":{\"allOf\":[{\"$ref\":\"TabVerdict.json\"}],\"enum\":[\"ready\"]},\"name\":{\"type\":\"string\",\"description\":\"The name the knowledge base gave the resource.\"},\"mediaType\":{\"type\":\"string\",\"description\":\"The media type of its primary representation. Absent when it said none.\"}},\"required\":[\"verdict\",\"name\"]},{\"type\":\"object\",\"description\":\"The check found out nothing.\",\"additionalProperties\":false,\"properties\":{\"verdict\":{\"allOf\":[{\"$ref\":\"TabVerdict.json\"}],\"enum\":[\"unknown\"]}},\"required\":[\"verdict\"]}]},\"KbSessionStatus\":{\"title\":\"KbSessionStatus\",\"type\":\"string\",\"description\":\"What the credential stored for a knowledge base says, read without asking anyone: `authenticated`, a token is stored and has not expired; `expired`, a token is stored and has expired; `signed-out`, nothing is stored.\",\"enum\":[\"authenticated\",\"expired\",\"signed-out\"]},\"SessionEnded\":{\"title\":\"SessionEnded\",\"type\":\"object\",\"description\":\"A session ended, and why.\",\"additionalProperties\":false,\"properties\":{\"reason\":{\"$ref\":\"SessionEndReason.json\",\"description\":\"Why it ended.\"}},\"required\":[\"reason\"]},\"PermissionDenied\":{\"title\":\"PermissionDenied\",\"type\":\"object\",\"description\":\"A request was refused for lack of permission.\",\"additionalProperties\":false,\"properties\":{\"detail\":{\"type\":[\"string\",\"null\"],\"description\":\"The refusal's own message, untranslated; null when it gave none.\"}},\"required\":[\"detail\"]},\"KbIdentityConflict\":{\"title\":\"KbIdentityConflict\",\"type\":\"object\",\"description\":\"A different knowledge base answers at a registered address. Both dids, because neither alone says what to do: a person has to recognise which knowledge base they registered and which one answers.\",\"additionalProperties\":false,\"properties\":{\"expectedDid\":{\"type\":\"string\",\"description\":\"The did the entry records.\"},\"observedDid\":{\"type\":\"string\",\"description\":\"The did the knowledge base that answered reported.\"}},\"required\":[\"expectedDid\",\"observedDid\"]},\"SessionEndReason\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/SessionEndReason.json\",\"title\":\"SessionEndReason\",\"type\":\"string\",\"description\":\"Why a session ended: `expired`, the issuer refused to renew its token; `refused`, the gateway refused a token its issuer had just issued.\",\"enum\":[\"expired\",\"refused\"]},\"StoredSession\":{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://xynolog.org/protocol/StoredSession.json\",\"title\":\"StoredSession\",\"type\":\"object\",\"description\":\"What is kept of a sign-in: the tokens an issuer issued, the client they were issued to, and the issuer's endpoints a renewal and a sign-out need, learned once at sign-in so no session asks again. TOKENS, never a password. A stored value that lacks a member it requires is no session.\",\"properties\":{\"access\":{\"type\":\"string\",\"description\":\"The access token: short-lived, sent as a Bearer token.\"},\"refresh\":{\"type\":\"string\",\"description\":\"The refresh token: what renews the access token at the issuer without another sign-in.\"},\"clientId\":{\"type\":\"string\",\"description\":\"The client the tokens were issued to, which a renewal and a revocation name.\"},\"tokenEndpoint\":{\"type\":\"string\",\"description\":\"The issuer's token endpoint, where the refresh grant is made.\"},\"revocationEndpoint\":{\"type\":\"string\",\"description\":\"The issuer's revocation endpoint (RFC 7009), where a sign-out tells it to forget the refresh token. Absent when the issuer has none.\"},\"personKey\":{\"type\":\"string\",\"description\":\"Who the gateway said the sign-in's person is, as the key their caches and stream position are kept under (`lastEventIdKeyPrefix`), never the did itself. Written once the gateway names the person, on the sign-in whose token it was asked about; a renewal keeps it, a new sign-in starts without it, and forgetting the sign-in, however it is forgotten, reads it first to delete what is kept under it. Absent for a sign-in whose gateway has not yet named its person.\"}},\"required\":[\"access\",\"refresh\",\"clientId\",\"tokenEndpoint\"]},\"EmptyBusPayload\":{\"type\":\"object\",\"maxProperties\":0},\"CloneResourceWithTokenResponseBusEnvelope\":{\"type\":\"object\",\"properties\":{\"response\":{\"$ref\":\"CloneResourceWithTokenResponse.json\"}},\"required\":[\"response\"],\"additionalProperties\":false},\"GetResourceByTokenResponseBusEnvelope\":{\"type\":\"object\",\"properties\":{\"response\":{\"$ref\":\"GetResourceByTokenResponse.json\"}},\"required\":[\"response\"],\"additionalProperties\":false},\"ContextualSummaryResponseBusEnvelope\":{\"type\":\"object\",\"properties\":{\"response\":{\"$ref\":\"ContextualSummaryResponse.json\"}},\"required\":[\"response\"],\"additionalProperties\":false},\"JobCancelResultBusEnvelope\":{\"type\":\"object\",\"properties\":{\"response\":{\"$ref\":\"JobCancelResult.json\"}},\"required\":[\"response\"],\"additionalProperties\":false},\"AnchoredTextAbsentKind\":{\"type\":\"string\",\"enum\":[\"not-yet\",\"no-map\",\"unknown\"],\"description\":\"Discriminant, sharing the `kind` field with the ExtractedText/ExtractionDeclined members so the whole answer is one flat union.\\n\\n`not-yet` \u2014 the resource's media type has text that is derived by reading its content, and the store holds no entry for this content: the Smelter has not read it yet, or the entry was lost (a loss the Smelter's reconcile pass re-derives). RETRY.\\n\\n`no-map` \u2014 the resource's media type has no derived text, so no entry exists and none will until the type is given a reader. Decided by the media type alone, and answered at once. TERMINAL.\\n\\n`unknown` \u2014 no content identity to look up: the resource is not in the view store, or its primary representation carries no checksum. TERMINAL.\"},\"AnchoredTextExtractedEntryLinesItem\":{\"type\":\"object\",\"description\":\"One line of text: the words that share a page, a baseline and a height.\",\"properties\":{\"p\":{\"type\":\"integer\",\"description\":\"The page, counted from 1.\"},\"y\":{\"type\":\"number\",\"description\":\"The line's vertical position in PDF points, from the bottom of the page.\"},\"h\":{\"type\":\"number\",\"description\":\"The line's height in PDF points.\"},\"words\":{\"type\":\"array\",\"description\":\"Each word as `[x, width, start, end]`: its horizontal position and width in PDF points, and the offsets of its text in `text`, which are whole numbers of Unicode code points from the start of `text`.\",\"items\":{\"type\":\"array\",\"items\":{\"type\":\"number\"},\"minItems\":4,\"maxItems\":4}}},\"required\":[\"p\",\"y\",\"h\",\"words\"],\"additionalProperties\":false},\"AnnotationTargetValue\":{\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},{\"$ref\":\"https://xynolog.org/protocol/AnnotationTarget.json\"}],\"description\":\"W3C Web Annotation target: the id of the resource annotated, when the whole of it is, or an object with source and optional selector (fragment)\"},\"AnnotationTargetType\":{\"type\":\"string\",\"enum\":[\"SpecificResource\"],\"description\":\"Stated by the annotation of a span: the target is a part of its source, which the selector picks out. An annotation of a resource as a whole states none.\"},\"ArchivistEnginesActors\":{\"type\":\"object\",\"description\":\"The engine each Librarian actor that calls a model asks.\",\"properties\":{\"gatherer\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"matcher\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"}},\"additionalProperties\":false},\"EngineProvider\":{\"type\":\"string\",\"enum\":[\"anthropic\",\"google\",\"llamacpp\",\"ollama\",\"openai\",\"together\",\"vllm\"],\"description\":\"The inference provider: who serves the model. `anthropic`, `google`, `openai` and `together` are those companies' own APIs. `llamacpp`, `ollama` and `vllm` are servers a deployment runs or reaches, each named for the server's software.\"},\"ArchivistEnginesJobs\":{\"type\":\"object\",\"description\":\"The engine each job is done with when software does it, keyed as a job description is: by `jobType`, and for `mark` by motivation.\",\"properties\":{\"mark\":{\"type\":\"object\",\"description\":\"The engine for `mark` jobs of each motivation.\",\"properties\":{\"highlighting\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"commenting\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"assessing\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"linking\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"tagging\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"}},\"additionalProperties\":false},\"yield\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"}},\"additionalProperties\":false},\"ArchivistEnginesJobsMark\":{\"type\":\"object\",\"description\":\"The engine for `mark` jobs of each motivation.\",\"properties\":{\"highlighting\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"commenting\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"assessing\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"linking\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"},\"tagging\":{\"$ref\":\"https://xynolog.org/protocol/Engine.json\"}},\"additionalProperties\":false},\"ArchivistConfigStaging\":{\"type\":\"object\",\"description\":\"The bounds on how far the staging driver may run behind the working tree, in milliseconds. A knowledge base that does not sync git stages nothing, and reads neither.\",\"properties\":{\"flushMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The quiet period after the last change before pending changes are staged.\"},\"maxWaitMs\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The longest a change waits to be staged while others keep arriving, measured from the oldest pending change.\"}},\"required\":[\"flushMs\",\"maxWaitMs\"],\"additionalProperties\":false},\"ArchivistHealthActorsItem\":{\"type\":\"string\",\"enum\":[\"stower\",\"browser\",\"cloneTokenManager\"]},\"AssessingJobParamsTone\":{\"type\":\"string\",\"enum\":[\"analytical\",\"critical\",\"balanced\",\"constructive\"],\"description\":\"The stance the assessments are written from.\"},\"HttpEndpointProtocol\":{\"type\":\"string\",\"enum\":[\"http\",\"https\"],\"description\":\"What the gateway is reached over.\"},\"BindBodyOperationOp\":{\"type\":\"string\",\"enum\":[\"add\",\"remove\",\"replace\"],\"description\":\"The type of body operation\"},\"ResourceDescriptorContext\":{\"description\":\"JSON-LD context; URI, object, or array of these.\",\"oneOf\":[{\"type\":\"string\",\"format\":\"uri\"},{\"type\":\"object\",\"additionalProperties\":true},{\"type\":\"array\",\"items\":{\"oneOf\":[{\"type\":\"string\",\"format\":\"uri\"},{\"type\":\"object\",\"additionalProperties\":true}]}}]},\"ResourceDescriptorContextArrayItem\":{\"oneOf\":[{\"type\":\"string\",\"format\":\"uri\"},{\"type\":\"object\",\"additionalProperties\":true}]},\"ResourceDescriptorIdentifier\":{\"description\":\"Persistent identifiers (e.g., DOI, URN).\",\"oneOf\":[{\"type\":\"string\"},{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"minItems\":1},{\"type\":\"object\",\"properties\":{\"@id\":{\"type\":\"string\",\"format\":\"uri\"},\"value\":{\"type\":\"string\"},\"scheme\":{\"type\":\"string\"}},\"additionalProperties\":true}]},\"ResourceDescriptorIdentifierObject\":{\"type\":\"object\",\"properties\":{\"@id\":{\"type\":\"string\",\"format\":\"uri\"},\"value\":{\"type\":\"string\"},\"scheme\":{\"type\":\"string\"}},\"additionalProperties\":true},\"ResourceDescriptorRepresentations\":{\"description\":\"Managed or referenced byte-level renditions of this resource.\",\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/Representation.json\"},{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/Representation.json\"}}]},\"RepresentationRel\":{\"description\":\"Semantics of this rendition relative to the resource (e.g., original, thumbnail, preview, derived).\",\"type\":\"string\",\"enum\":[\"original\",\"thumbnail\",\"preview\",\"optimized\",\"derived\",\"other\"]},\"ResourceDescriptorWasDerivedFrom\":{\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"},{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\"}}],\"description\":\"W3C PROV: the resource, or resources, this one was derived from, each by its id\"},\"CommandErrorCode\":{\"type\":\"string\",\"enum\":[\"peer-unavailable\",\"not-found\",\"unauthorized\",\"none-pending\"],\"description\":\"Machine-readable failure class, for consumers that must BRANCH on why a command failed rather than log it. Optional and deliberately sparse: absent means 'no class declared', and every existing failure stays that way. An enum rather than a free string so the vocabulary has an owner \u2014 an unconstrained code is a mirror with no gate, and adding one should be a deliberate spec change. `message` remains the human-readable text and is unaffected. Members: `peer-unavailable` \u2014 the channel this command was sent on has no subscriber, i.e. the service that answers it has not connected yet. Transient by nature (a peer still starting), which is what distinguishes it from a refusal: retrying is the correct response. `not-found` \u2014 the resource this command addressed does not exist in this knowledge base. A verdict, not a symptom: it is emitted only where the answer comes from the event store, which is the system of record, and never from a projection that may merely be lagging. Deterministic, so unlike `peer-unavailable` retrying is pointless \u2014 and consumers may act destructively on it (the SDK deletes a restored tab). Absence is not denial: a future 'exists, but not for you' must travel as its own code, never as this one. `unauthorized` \u2014 that code: the caller is authenticated but not permitted to do what it asked. A verdict about the CALLER, not the resource, so retrying under the same credential cannot succeed and a consumer must never spin on it; emitted by `job:claim` for a caller whose token carries no worker role. `none-pending` \u2014 a declined claim, not an error: the queue holds no pending job of the requested types. Nothing went wrong; the one code a consumer PARKS on, meaning 'nothing to do until a wake-up'. Emitted by `job:claim` only. A `job:claim` refusal carrying neither is unclassified \u2014 a malformed record or a missing injection \u2014 and a consumer treats it as 'log it, assume nothing'.\"},\"BrowseDirectoryRequestSort\":{\"type\":\"string\",\"enum\":[\"name\",\"mtime\",\"annotationCount\"]},\"BrowseEnginesResultResponse\":{\"type\":\"object\",\"properties\":{\"engines\":{\"type\":\"array\",\"items\":{\"$ref\":\"https://xynolog.org/protocol/EngineEntry.json\"}}},\"required\":[\"engines\"]},\"MarkJobFilterParams\":{\"type\":\"object\",\"properties\":{\"motivation\":{\"$ref\":\"https://xynolog.org/protocol/Motivation.json\"}},\"required\":[\"motivation\"],\"additionalProperties\":false},\"BrowseProfilesResultResponse\":{\"type\":\"object\",\"properties\":{\"profiles\":{\"type\":\"object\",\"description\":\"Each profile, keyed by DID.\",\"additionalProperties\":{\"$ref\":\"https://xynolog.org/protocol/Profile.json\"}}},\"required\":[\"profiles\"],\"additionalProperties\":false},\"BrowseResourceResultResponse\":{\"type\":\"object\",\"properties\":{\"resource\":{\"$ref\":\"https://xynolog.org/protocol/ResourceDescriptor.json\"},\"lastSequence\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The sequence number of the resource's last event. A graph read that follows a write waits for the graph projection to reach it.\"}},\"required\":[\"resource\",\"lastSequence\"],\"additionalProperties\":false},\"BusEventMessageId\":{\"oneOf\":[{\"$ref\":\"https://xynolog.org/protocol/PersistedEventId.json\"},{\"$ref\":\"https://xynolog.org/protocol/ReplyEventId.json\"},{\"$ref\":\"https://xynolog.org/protocol/EphemeralEventId.json\"}]},\"BusResumeGapReason\":{\"type\":\"string\",\"enum\":[\"unparseable-last-event-id\",\"scope-mismatch\",\"retention-exceeded\",\"query-error\"],\"description\":\"`unparseable-last-event-id`: the watermark is not a PersistedEventId. `scope-mismatch`: it names another scope. `retention-exceeded`: the record no longer holds the events after it (what it still holds is replayed first). `query-error`: the record could not be read.\"},\"BusSubscribeRequestScopedItem\":{\"type\":\"object\",\"required\":[\"scope\",\"channels\"],\"additionalProperties\":false,\"properties\":{\"scope\":{\"$ref\":\"https://xynolog.org/protocol/ResourceId.json\",\"description\":\"Resource scope (a resourceId).\"},\"channels\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1},\"description\":\"Channels to subscribe within this scope.\",\"minItems\